DATA.exercises.push(

  // ---------- present-perfect-continuous ----------
  { id: "ppc-001", topic: "present-perfect-continuous", type: "choice", q: "I ___ for you for an hour!", options: ["have been waiting", "am waiting", "wait"], answer: "have been waiting", explain: "Действие началось раньше и идёт до сих пор (for an hour) → **have been waiting**: have/has been + -ing." },
  { id: "ppc-002", topic: "present-perfect-continuous", type: "fill", q: "How long have you ___ English?", hint: "learn", answers: ["been learning"], explain: "How long — вопрос о длительности → Present Perfect Continuous: have you **been learning**." },
  { id: "ppc-003", topic: "present-perfect-continuous", type: "fix", q: "I am living here since 2019.", answers: ["I have been living here since 2019.", "I have lived here since 2019."], explain: "since + до сих пор → Present Perfect (Continuous), не Present Continuous." },
  { id: "ppc-004", topic: "present-perfect-continuous", type: "choice", q: "She's tired because she ___ all day.", options: ["has been working", "works", "is working"], answer: "has been working", explain: "Усталость сейчас как результат длительного процесса (all day) → **has been working**." },
  { id: "ppc-005", topic: "present-perfect-continuous", type: "translate", q: "Я жду тебя уже 20 минут.", answers: ["I have been waiting for you for 20 minutes.", "I have been waiting for you for 20 minutes already."], explain: "Длительность до сейчас (for 20 minutes) → **have been waiting** (I + have). Русское «жду уже» = Perfect Continuous." },
  { id: "ppc-006", topic: "present-perfect-continuous", type: "choice", q: "I've ___ him for ten years.", options: ["known", "been knowing"], answer: "known", explain: "know — глагол состояния, без continuous." },
  { id: "ppc-007", topic: "present-perfect-continuous", type: "fill", q: "It ___ raining since morning.", answers: ["has been"], explain: "С it/she/he — **has been** + -ing: It has been raining since morning. Since + момент начала." },
  { id: "ppc-008", topic: "present-perfect-continuous", type: "choice", q: "They ___ for two hours. Let's take a break.", options: ["have been working", "are working", "work"], answer: "have been working", explain: "Процесс шёл два часа (for two hours) и важен сейчас → **have been working**." },
  { id: "ppc-009", topic: "present-perfect-continuous", type: "fill", q: "Why are your hands so dirty? What have you ___?", hint: "do", answers: ["been doing"], explain: "Видим результат (грязные руки), спрашиваем о процессе: What have you **been doing**?" },
  { id: "ppc-010", topic: "present-perfect-continuous", type: "fix", q: "I know her since we were children.", answers: ["I have known her since we were children.", "I've known her since we were children."], explain: "know — глагол состояния, без continuous, но since всё равно требует Present Perfect." },
  { id: "ppc-011", topic: "present-perfect-continuous", type: "choice", q: "You look exhausted. ___?", options: ["Have you been running", "Are you running", "Did you run"], answer: "Have you been running", explain: "Вид усталый — спрашиваем о недавнем процессе: **Have you been running**? Did you run — просто факт в прошлом." },
  { id: "ppc-012", topic: "present-perfect-continuous", type: "translate", q: "Она весь день убирает дом.", answers: ["She has been cleaning the house all day.", "She's been cleaning the house all day."], explain: "Весь день (all day) — процесс → **has been cleaning** (she + has been + -ing)." },
  { id: "ppc-013", topic: "present-perfect-continuous", type: "choice", q: "I've been reading this book for two weeks, but I ___ finished it yet.", options: ["haven't", "don't have", "am not"], answer: "haven't", explain: "Результат с yet — Present Perfect Simple: I **haven't** finished it yet. Первая часть про длительность (been reading)." },
  { id: "ppc-014", topic: "present-perfect-continuous", type: "fill", q: "I ___ this book for three days, but I haven't finished it yet.", hint: "read", answers: ["have been reading"], explain: "Длительность (for three days) → **have been reading**, а результат (haven't finished) — следствие." },
  { id: "ppc-015", topic: "present-perfect-continuous", type: "choice", q: "The children ___ in the garden all afternoon — that's why they're so dirty.", options: ["have been playing", "play", "are playing"], answer: "have been playing", explain: "Весь день играли, и это видно сейчас (грязные) → **have been playing**." },

  // ---------- present-perfect-simple-vs-continuous ----------
  { id: "ppsvc-001", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "I ___ three emails this morning, and I'm about to write one more.", options: ["have written", "have been writing"], answer: "have written", explain: "Названо количество (три письма) — важен результат: Present Perfect простое." },
  { id: "ppsvc-002", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "My hands are dirty — I ___ in the garden.", options: ["have been working", "have worked"], answer: "have been working", explain: "Видим следствие процесса (грязные руки) — важно, что действие длилось: have been working." },
  { id: "ppsvc-003", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "How long ___ studying for this exam?", options: ["have you been", "have you", "did you"], answer: "have you been", explain: "How long + процесс → have you been studying." },
  { id: "ppsvc-004", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "The train ___ — we can get on now.", options: ["has arrived", "has been arriving", "arrives"], answer: "has arrived", explain: "arrive — разовое событие, в continuous не ставится." },
  { id: "ppsvc-005", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "I ___ this book for two weeks, and I still haven't finished it.", options: ["have been reading", "have read"], answer: "have been reading", explain: "Действие не закончено (still haven't finished) — длительное." },
  { id: "ppsvc-006", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "He ___ four cups of coffee today.", options: ["has drunk", "has been drinking"], answer: "has drunk", explain: "Названо количество (four cups) — простое." },
  { id: "ppsvc-007", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "I'm tired because I ___ all day.", options: ["have been cleaning", "have cleaned"], answer: "have been cleaning", explain: "Процесс (all day), объясняет усталость." },
  { id: "ppsvc-008", topic: "present-perfect-simple-vs-continuous", type: "choice", q: "They ___ each other for ten years.", options: ["have known", "have been knowing", "know"], answer: "have known", explain: "know — глагол состояния, в continuous не ставится." },

  { id: "ppsvc-009", topic: "present-perfect-simple-vs-continuous", type: "fill", q: "We ___ a trip to Italy since January.", hint: "plan", answers: ["have been planning"], explain: "since + процесс → have been planning." },
  { id: "ppsvc-010", topic: "present-perfect-simple-vs-continuous", type: "fill", q: "How long have you ___ for the bus?", hint: "wait", answers: ["been waiting"], explain: "have you been + -ing: слово been обязательно." },
  { id: "ppsvc-011", topic: "present-perfect-simple-vs-continuous", type: "fill", q: "She ___ her report yet.", hint: "not / finish", answers: ["hasn't finished", "has not finished"], explain: "yet в отрицании: hasn't + V3." },
  { id: "ppsvc-012", topic: "present-perfect-simple-vs-continuous", type: "fill", q: "I ___ an interesting article about space.", hint: "just / read", answers: ["have just read"], explain: "just стоит между have и V3: have just read." },
  { id: "ppsvc-013", topic: "present-perfect-simple-vs-continuous", type: "fill", q: "We ___ the menu for the party.", hint: "also / plan", answers: ["have also been planning", "have also planned"], explain: "also — между have и been: have also been planning (не «have been also»). Простая форма have also planned тоже верна." },
  { id: "ppsvc-014", topic: "present-perfect-simple-vs-continuous", type: "fill", q: "He ___ to the gym lately.", hint: "not / go", answers: ["hasn't been going", "has not been going", "hasn't gone", "has not gone"], explain: "Отрицание длительного: hasn't been going. Простая форма hasn't gone тоже верна." },

  { id: "ppsvc-015", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "She has taken the exam yet.", answers: ["She hasn't taken the exam yet.", "She has not taken the exam yet."], explain: "yet в утверждении не бывает: «ещё не сдавала» — hasn't taken." },
  { id: "ppsvc-016", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "I haven't going to the gym this month.", answers: ["I haven't been going to the gym this month.", "I have not been going to the gym this month."], explain: "Длительное: haven't been going — слово been обязательно." },
  { id: "ppsvc-017", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "We have been also planning the trip.", answers: ["We have also been planning the trip.", "We've also been planning the trip."], explain: "also стоит между have и been." },
  { id: "ppsvc-018", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "The parcel has been arriving this morning.", answers: ["The parcel has arrived this morning.", "The parcel arrived this morning."], explain: "arrive — разовое событие, без continuous." },
  { id: "ppsvc-019", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "I've read this interview for an hour, but I haven't finished it.", answers: ["I've been reading this interview for an hour, but I haven't finished it.", "I have been reading this interview for an hour, but I haven't finished it."], explain: "Действие не закончено → длительное: I've been reading." },
  { id: "ppsvc-020", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "How long have you know Anna?", answers: ["How long have you known Anna?"], explain: "После have — V3: know → known (и состояние, поэтому без continuous)." },
  { id: "ppsvc-021", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "He has been losing his keys, so he can't get in.", answers: ["He has lost his keys, so he can't get in.", "He's lost his keys, so he can't get in."], explain: "lose — разовое событие, нужен результат: has lost." },
  { id: "ppsvc-022", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "Has Paul ever meet your sister?", answers: ["Has Paul ever met your sister?"], explain: "После has — V3: met. ever стоит между has и V3." },
  { id: "ppsvc-023", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "My brother has just been finish his homework.", answers: ["My brother has just finished his homework."], explain: "Лишнее слово been: has just finished." },
  { id: "ppsvc-024", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "I've been wrote three letters today.", answers: ["I've written three letters today.", "I have written three letters today."], explain: "Количество (three letters) → простое: have written." },
  { id: "ppsvc-025", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "They haven't been finish yet.", answers: ["They haven't finished yet.", "They have not finished yet."], explain: "Простое отрицание: haven't finished. Лишнее been." },
  { id: "ppsvc-026", topic: "present-perfect-simple-vs-continuous", type: "fix", q: "She's been knowing him since school.", answers: ["She's known him since school.", "She has known him since school."], explain: "know — состояние, без continuous." },

  { id: "ppsvc-027", topic: "present-perfect-simple-vs-continuous", type: "translate", q: "Я пишу этот отчёт с утра.", answers: ["I've been writing this report since morning.", "I have been writing this report since morning.", "I've been writing this report since the morning.", "I have been writing this report since the morning.", "I've been writing this report since this morning.", "I have been writing this report since this morning."], explain: "Процесс с начала утра — have been writing + since." },
  { id: "ppsvc-028", topic: "present-perfect-simple-vs-continuous", type: "translate", q: "Мы уже закончили проект.", answers: ["We have already finished the project.", "We've already finished the project.", "We have finished the project already.", "We've finished the project already."], explain: "Завершено → простое; already между have и V3 или в конце." },
  { id: "ppsvc-029", topic: "present-perfect-simple-vs-continuous", type: "translate", q: "Как давно ты ждёшь?", answers: ["How long have you been waiting?"], explain: "How long + процесс." },
  { id: "ppsvc-030", topic: "present-perfect-simple-vs-continuous", type: "translate", q: "Он ещё не позвонил.", answers: ["He hasn't called yet.", "He hasn't phoned yet.", "He hasn't rung yet.", "He has not called yet.", "He has not phoned yet.", "He has not rung yet."], explain: "«Ещё не» — hasn't + V3 + yet." },

  // ---------- past-perfect-continuous ----------
  { id: "pastpc-001", topic: "past-perfect-continuous", type: "choice", q: "She was tired because she ___ all morning.", options: ["had been running", "had run", "was running"], answer: "had been running", explain: "Процесс до момента в прошлом, объясняет состояние: had been running." },
  { id: "pastpc-002", topic: "past-perfect-continuous", type: "choice", q: "When Tom arrived, we ___ for two hours.", options: ["had been waiting", "had waited", "have been waiting"], answer: "had been waiting", explain: "Длительность до момента в прошлом: had been waiting." },
  { id: "pastpc-003", topic: "past-perfect-continuous", type: "choice", q: "His eyes were red — he ___.", options: ["had been crying", "had cried", "has been crying"], answer: "had been crying", explain: "Причина состояния в прошлом." },
  { id: "pastpc-004", topic: "past-perfect-continuous", type: "choice", q: "The ground was wet because it ___.", options: ["had been raining", "had rained", "rained"], answer: "had been raining", explain: "Причина (дождь шёл) — процесс до момента в прошлом." },
  { id: "pastpc-005", topic: "past-perfect-continuous", type: "fill", q: "They were exhausted because they ___ all day.", hint: "work", answers: ["had been working"], explain: "had + been + -ing." },
  { id: "pastpc-006", topic: "past-perfect-continuous", type: "fill", q: "How long had you ___ there before you moved?", hint: "live", answers: ["been living"], explain: "had you been + -ing." },
  { id: "pastpc-007", topic: "past-perfect-continuous", type: "fill", q: "He ___ well, so he looked tired.", hint: "not / sleep", answers: ["hadn't been sleeping", "had not been sleeping"], explain: "Отрицание: hadn't been + -ing." },
  { id: "pastpc-008", topic: "past-perfect-continuous", type: "fill", q: "We ___ outside, so we were cold.", hint: "also / wait", answers: ["had also been waiting"], explain: "also — между had и been." },
  { id: "pastpc-009", topic: "past-perfect-continuous", type: "fix", q: "He had started been shouting before we arrived.", answers: ["He had been shouting before we arrived.", "He had started shouting before we arrived."], explain: "Лишнее слово: либо had been shouting, либо had started shouting." },
  { id: "pastpc-010", topic: "past-perfect-continuous", type: "fix", q: "She was tired because she had been ran.", answers: ["She was tired because she had been running.", "She was tired because she'd been running."], explain: "После been — форма с -ing." },
  { id: "pastpc-011", topic: "past-perfect-continuous", type: "fix", q: "They had been wait for an hour when the bus came.", answers: ["They had been waiting for an hour when the bus came.", "They'd been waiting for an hour when the bus came."], explain: "had been + -ing." },
  { id: "pastpc-012", topic: "past-perfect-continuous", type: "fix", q: "I had been knowing him for years.", answers: ["I had known him for years.", "I'd known him for years."], explain: "know — состояние, без continuous." },
  { id: "pastpc-013", topic: "past-perfect-continuous", type: "fix", q: "She hadn't been finished her work, so she stayed late.", answers: ["She hadn't finished her work, so she stayed late.", "She had not finished her work, so she stayed late."], explain: "Лишнее been: hadn't finished." },
  { id: "pastpc-014", topic: "past-perfect-continuous", type: "fix", q: "How long you had been waiting when the doctor called you?", answers: ["How long had you been waiting when the doctor called you?"], explain: "Порядок в вопросе: had you been." },
  { id: "pastpc-015", topic: "past-perfect-continuous", type: "translate", q: "Мы ждали уже час, когда пришёл автобус.", answers: ["We had been waiting for an hour when the bus came.", "We had been waiting for an hour when the bus arrived.", "When the bus came, we had been waiting for an hour.", "When the bus arrived, we had been waiting for an hour.", "We'd been waiting for an hour when the bus came.", "We'd been waiting for an hour when the bus arrived."], explain: "Процесс до момента в прошлом." },

  // ---------- past-perfect ----------
  { id: "pastp-001", topic: "past-perfect", type: "choice", q: "When we arrived, the film ___.", options: ["had already started", "has already started", "already starts"], answer: "had already started", explain: "Фильм начался раньше, чем мы пришли → Past Perfect." },
  { id: "pastp-002", topic: "past-perfect", type: "fill", q: "I didn't go to the cinema because I ___ the film before.", hint: "see", answers: ["had seen"], explain: "Один случай раньше другого в прошлом: фильм был **раньше** (had seen), поэтому в кино не пошёл (didn't go)." },
  { id: "pastp-003", topic: "past-perfect", type: "fix", q: "He told me he has lost his job.", answers: ["He told me he had lost his job.", "He told me that he had lost his job.", "He told me he lost his job."], explain: "Потеря работы была раньше, чем told me: **had lost** (Past Perfect). Has lost при told me не подходит." },
  { id: "pastp-004", topic: "past-perfect", type: "choice", q: "By the time I got to the station, the train ___.", options: ["had left", "has left", "leaves"], answer: "had left", explain: "By the time I got… — к тому времени поезд уже ушёл: **had left** (Past Perfect = раньше)." },
  { id: "pastp-005", topic: "past-perfect", type: "translate", q: "Когда мы пришли, они уже ушли.", answers: ["When we arrived, they had already left.", "When we came, they had already left.", "When we got there, they had already left.", "They had already left when we arrived.", "They had already left when we came.", "They had already left when we got there.", "When we arrived, they had already gone.", "They had already gone when we arrived."], explain: "Они ушли раньше нашего прихода → **had already left**. When we arrived — Past Simple." },
  { id: "pastp-006", topic: "past-perfect", type: "choice", q: "After she ___ breakfast, she went to work.", options: ["had had", "has had", "have"], answer: "had had", explain: "After she **had had** breakfast: had + третья форма have (have → had → had). Дальше Past Simple (went)." },
  { id: "pastp-007", topic: "past-perfect", type: "choice", q: "By the time the police arrived, the thief ___.", options: ["had escaped", "escaped", "has escaped"], answer: "had escaped", explain: "К приезду полиции вор уже скрылся → **had escaped**." },
  { id: "pastp-008", topic: "past-perfect", type: "fill", q: "She wasn't hungry because she ___ lunch already.", hint: "have", answers: ["had had"], explain: "Причина (not hungry) — обед раньше → **had had** lunch already." },
  { id: "pastp-009", topic: "past-perfect", type: "fix", q: "I never saw snow before I moved to Canada.", answers: ["I had never seen snow before I moved to Canada.", "I'd never seen snow before I moved to Canada."], explain: "Снег я видел только после переезда — до этого не видел: **had never seen** (never + V3). Seen — третья форма see." },
  { id: "pastp-010", topic: "past-perfect", type: "choice", q: "He couldn't get into the house because he ___ his keys at work.", options: ["had left", "left", "has left"], answer: "had left", explain: "Причина (ключи оставил) произошла раньше → **had left** his keys." },
  { id: "pastp-011", topic: "past-perfect", type: "translate", q: "Когда я пришёл домой, дождь уже закончился.", answers: ["When I got home, the rain had already stopped.", "When I arrived home, the rain had already stopped.", "When I got home, it had already stopped raining.", "When I arrived home, it had already stopped raining."], explain: "Дождь закончился до того, как я пришёл → **had already stopped**." },
  { id: "pastp-012", topic: "past-perfect", type: "choice", q: "I ___ that film before, so I knew what would happen.", options: ["had seen", "saw", "have seen"], answer: "had seen", explain: "Видел фильм раньше, поэтому знал, что будет → **had seen**." },
  { id: "pastp-013", topic: "past-perfect", type: "fill", q: "They were tired because they ___ a long way.", hint: "walk", answers: ["had walked"], explain: "Усталость — следствие более раннего действия → **had walked** a long way." },
  { id: "pastp-014", topic: "past-perfect", type: "fix", q: "When she arrived, the meeting already started.", answers: ["When she arrived, the meeting had already started."], explain: "Собрание началось раньше её приезда → **had already started**." },
  { id: "pastp-015", topic: "past-perfect", type: "choice", q: "He didn't recognise the city because it ___ so much.", options: ["had changed", "changed", "has changed"], answer: "had changed", explain: "Изменения произошли раньше, чем он увидел город → **had changed**." },

  // --- pastp: неправильные V3, by the time / before / after ---
  { id: "pastp-016", topic: "past-perfect", type: "fix", q: "When we arrived, they had leaved.", answers: ["When we arrived, they had left.", "When we arrived, they'd left."], explain: "leave — неправильный глагол: left." },
  { id: "pastp-017", topic: "past-perfect", type: "fix", q: "He had seted off before dawn.", answers: ["He had set off before dawn.", "He'd set off before dawn."], explain: "set – set – set: V3 совпадает с инфинитивом." },
  { id: "pastp-018", topic: "past-perfect", type: "fix", q: "She had eated all the cake by the time we came.", answers: ["She had eaten all the cake by the time we came.", "She'd eaten all the cake by the time we came."], explain: "eat – ate – eaten." },
  { id: "pastp-019", topic: "past-perfect", type: "fix", q: "I had spoke to him before the meeting.", answers: ["I had spoken to him before the meeting.", "I'd spoken to him before the meeting."], explain: "speak – spoke – spoken." },
  { id: "pastp-020", topic: "past-perfect", type: "fix", q: "By the time I called, he had went to bed.", answers: ["By the time I called, he had gone to bed.", "By the time I called, he'd gone to bed."], explain: "go – went – gone." },
  { id: "pastp-021", topic: "past-perfect", type: "choice", q: "After he ___ the news, he called his mum.", options: ["had heard", "has heard", "hears"], answer: "had heard", explain: "Действие раньше другого в прошлом: had heard." },
  { id: "pastp-022", topic: "past-perfect", type: "fill", q: "I knew her face because I ___ her before.", hint: "see", answers: ["had seen", "'d seen"], explain: "see – saw – seen: had seen." },
  { id: "pastp-023", topic: "past-perfect", type: "fill", q: "By the time we got to the cinema, the film ___.", hint: "already / start", answers: ["had already started"], explain: "already — между had и V3." },
  { id: "pastp-024", topic: "past-perfect", type: "choice", q: "I ___ him before, so I recognised him.", options: ["had met", "met", "have met"], answer: "had met", explain: "Встреча была раньше момента узнавания: had met." },
  { id: "pastp-025", topic: "past-perfect", type: "choice", q: "The students ___ the room before the teacher came.", options: ["had left", "leaved", "had leaved"], answer: "had left", explain: "left — V3 от leave." },
  { id: "pastp-026", topic: "past-perfect", type: "translate", q: "К тому времени, как мы пришли, они уже поели.", answers: ["By the time we arrived, they had already eaten.", "By the time we got there, they had already eaten.", "By the time we came, they had already eaten.", "By the time we arrived, they had eaten.", "They had already eaten by the time we arrived.", "By the time we arrived, they'd already eaten."], explain: "By the time + Past Simple, Past Perfect во второй части." },
  { id: "pastp-027", topic: "past-perfect", type: "translate", q: "Он сказал, что уже видел этот фильм.", answers: ["He said he had already seen that film.", "He said that he had already seen that film.", "He said he had seen that film already.", "He said he had already seen the film.", "He told me he had already seen that film.", "He said he'd already seen that film."], explain: "Сказал в прошлом о том, что было ещё раньше: had seen." },

  // ---------- used-to ----------
  { id: "used-001", topic: "used-to", type: "choice", q: "I ___ live in a small village, but now I live in the city.", options: ["used to", "use to", "am used to"], answer: "used to", explain: "Раньше жил, а сейчас нет — **used to** + глагол (форма used to)." },
  { id: "used-002", topic: "used-to", type: "fix", q: "Did you used to play the piano?", answers: ["Did you use to play the piano?"], explain: "После did — use to (без d)." },
  { id: "used-003", topic: "used-to", type: "choice", q: "I'm not ___ getting up so early.", options: ["used to", "use to", "using to"], answer: "used to", explain: "be used to + -ing — «привык»." },
  { id: "used-004", topic: "used-to", type: "fill", q: "There ___ to be a cinema here, but now it's a supermarket.", answers: ["used"], explain: "There **used** to be — раньше было (а теперь нет). В утверждении всегда used с -d." },
  { id: "used-005", topic: "used-to", type: "translate", q: "Раньше я курил.", answers: ["I used to smoke."], explain: "Раньше курил (привычка в прошлом) → **I used to smoke**." },
  { id: "used-006", topic: "used-to", type: "choice", q: "It's hard at first, but you'll get used to ___ on the left.", options: ["driving", "drive", "drove"], answer: "driving", explain: "get used to + **-ing** — привыкать: get used to driving. Здесь to — предлог, поэтому -ing." },
  { id: "used-007", topic: "used-to", type: "fix", q: "She didn't used to like coffee.", answers: ["She didn't use to like coffee."], explain: "В отрицании и вопросе — **use to** без -d (после did/didn't): She didn't use to like coffee." },
  { id: "used-008", topic: "used-to", type: "choice", q: "I'm used to ___ up early now — I don't mind it anymore.", options: ["getting", "get", "got"], answer: "getting", explain: "be used to + **-ing** — «привык»: I'm used to getting up early." },
  { id: "used-009", topic: "used-to", type: "fill", q: "We ___ to live in Moscow, but we moved five years ago.", answers: ["used"], explain: "Раньше жили в Москве, а теперь нет → **used** to live." },
  { id: "used-010", topic: "used-to", type: "fix", q: "I use to play football every weekend when I was a child.", answers: ["I used to play football every weekend when I was a child."], explain: "В утвердительных предложениях — used to (с d)." },
  { id: "used-011", topic: "used-to", type: "choice", q: "She isn't used to ___ so much traffic — she just moved from a small town.", options: ["seeing", "see", "saw"], answer: "seeing", explain: "isn't used to + **-ing**: она не привыкла к транспорту (seeing)." },
  { id: "used-012", topic: "used-to", type: "translate", q: "Мы раньше жили у моря.", answers: ["We used to live by the sea.", "We used to live near the sea.", "We used to live at the seaside."], explain: "Раньше жили у моря → **used to live** by the sea." },
  { id: "used-013", topic: "used-to", type: "choice", q: "___ you use to have long hair?", options: ["Did", "Do", "Have"], answer: "Did", explain: "Вопрос о прошлом: **Did** you use to…? После did — use to без -d." },
  { id: "used-014", topic: "used-to", type: "fill", q: "It took a while, but I finally got used to ___ on the left side of the road.", hint: "drive", answers: ["driving"], explain: "got used to + **-ing** — привык: driving on the left. To здесь предлог." },
  { id: "used-015", topic: "used-to", type: "fix", q: "He is used to work at night — he's a nurse.", answers: ["He is used to working at night — he's a nurse."], explain: "be used to + -ing, не to + инфинитив." },

  // --- used-to: контраст «сейчас ... но раньше ...» ---
  { id: "used-016", topic: "used-to", type: "choice", q: "Dan doesn't play football now, but he ___ play every day.", options: ["used to", "didn't use to", "is used to"], answer: "used to", explain: "Сейчас НЕ играет → раньше играл → положительное used to." },
  { id: "used-017", topic: "used-to", type: "choice", q: "Anna likes spicy food now, but she ___ eat it.", options: ["didn't use to", "used to", "is used to"], answer: "didn't use to", explain: "Сейчас любит → раньше не ела → didn't use to (или never used to)." },
  { id: "used-018", topic: "used-to", type: "choice", q: "My grandfather doesn't drive now, but he ___ drive a lorry.", options: ["used to", "didn't use to", "never used to"], answer: "used to", explain: "Сейчас не водит, но раньше водил → used to." },

  { id: "used-019", topic: "used-to", type: "fix", q: "Now I live in a flat, but I didn't use to live in a house.", answers: ["Now I live in a flat, but I used to live in a house."], explain: "Раньше жил в доме → положительное used to (отрицание противоречит смыслу)." },
  { id: "used-020", topic: "used-to", type: "fix", q: "She doesn't eat meat now, but she didn't use to eat it.", answers: ["She doesn't eat meat now, but she used to eat it.", "She doesn't eat meat now, but she used to."], explain: "Сейчас не ест, значит раньше ела → used to." },
  { id: "used-021", topic: "used-to", type: "fix", q: "Now Tom wakes up early, but he used to wake up early.", answers: ["Now Tom wakes up early, but he didn't use to wake up early.", "Now Tom wakes up early, but he never used to wake up early.", "Now Tom wakes up early, but he didn't use to.", "Now Tom wakes up early, but he never used to."], explain: "Сейчас встаёт рано, значит раньше НЕ вставал → didn't use to / never used to." },
  { id: "used-022", topic: "used-to", type: "fix", q: "He didn't used to like tomatoes, but now he eats them.", answers: ["He didn't use to like tomatoes, but now he eats them.", "He never used to like tomatoes, but now he eats them."], explain: "После didn't — use to (без d)." },

  { id: "used-023", topic: "used-to", type: "fill", q: "My sister eats fish now, but she ___ to like it.", answers: ["didn't use", "never used"], explain: "Сейчас ест → раньше не любила: didn't use to / never used to." },
  { id: "used-024", topic: "used-to", type: "fill", q: "I don't have a dog now, but I ___ to have one.", answers: ["used"], explain: "Сейчас нет, раньше был → used to." },

  { id: "used-025", topic: "used-to", type: "translate", q: "Сейчас я не курю, но раньше курил.", answers: ["I don't smoke now, but I used to.", "I don't smoke now, but I used to smoke.", "Now I don't smoke, but I used to.", "Now I don't smoke, but I used to smoke.", "I don't smoke any more, but I used to.", "I don't smoke anymore, but I used to."], explain: "Сейчас не курю → раньше курил: used to." },

  // ---------- first-conditional ----------
  { id: "cond1-001", topic: "first-conditional", type: "choice", q: "If it ___ tomorrow, we'll stay at home.", options: ["rains", "will rain", "rained", "would rain"], answer: "rains", explain: "После if в условии первого типа — Present Simple, не will." },
  { id: "cond1-002", topic: "first-conditional", type: "fill", q: "If you ___ now, you'll catch the bus.", hint: "leave", answers: ["leave"], explain: "После if — Present Simple, не will: If you **leave** now, you'll catch the bus." },
  { id: "cond1-003", topic: "first-conditional", type: "fix", q: "If it will rain, we will stay at home.", answers: ["If it rains, we will stay at home.", "We will stay at home if it rains."], explain: "После if не ставят will: If it **rains**, we will stay at home." },
  { id: "cond1-004", topic: "first-conditional", type: "choice", q: "Unless you hurry, you ___ the train.", options: ["will miss", "miss", "missed"], answer: "will miss", explain: "Unless (= if not) + Present Simple, а в главной части **will miss**: Unless you hurry, you'll miss the train." },
  { id: "cond1-005", topic: "first-conditional", type: "translate", q: "Если у меня будет время, я тебе позвоню.", answers: ["If I have time, I will call you.", "If I have time, I will phone you.", "If I have time, I will give you a call.", "I will call you if I have time.", "I will phone you if I have time.", "If I have some time, I will call you."], explain: "Реальное условие: If + Present Simple (I **have** time), **will** + глагол (I will call)." },
  { id: "cond1-006", topic: "first-conditional", type: "choice", q: "I won't go ___ you come with me.", options: ["unless", "if", "when"], answer: "unless", explain: "unless = if not." },
  { id: "cond1-007", topic: "first-conditional", type: "fill", q: "What will you do if you ___ the exam?", hint: "fail", answers: ["fail"], explain: "Условная часть после if — Present Simple: if you **fail**. В главной — will you do." },
  { id: "cond1-008", topic: "first-conditional", type: "choice", q: "If you heat ice, it ___.", options: ["melts", "will melt", "melted"], answer: "melts", explain: "Общий факт — нулевое условное: Present Simple в обеих частях." },
  { id: "cond1-009", topic: "first-conditional", type: "fill", q: "If I ___ tired, I go to bed early.", hint: "be", answers: ["am"], explain: "Общий факт (всегда так) — нулевой тип: If + Present Simple, Present Simple: If I **am** tired, I go to bed." },
  { id: "cond1-010", topic: "first-conditional", type: "fix", q: "If you will heat water to 100°C, it boils.", answers: ["If you heat water to 100°C, it boils."], explain: "Научный факт — нулевой тип без will: If you **heat** water to 100°C, it **boils**." },
  { id: "cond1-011", topic: "first-conditional", type: "choice", q: "I'll text you if I ___ late.", options: ["am", "will be", "was"], answer: "am", explain: "После if — Present Simple: I'll text you if I **am** late. Will после if не ставят, даже если речь о будущем." },
  { id: "cond1-012", topic: "first-conditional", type: "translate", q: "Если ты не поторопишься, мы опоздаем.", answers: ["If you don't hurry, we'll be late.", "If you don't hurry up, we'll be late.", "We'll be late if you don't hurry.", "We'll be late if you don't hurry up."], explain: "If you **don't hurry**, we'**ll be** late. Отрицание после if — don't + глагол." },
  { id: "cond1-013", topic: "first-conditional", type: "choice", q: "If she asks, I ___ her the truth.", options: ["will tell", "tell", "told"], answer: "will tell", explain: "В главной части — **will tell**: If she asks, I **will tell**. After if — Present Simple (asks)." },
  { id: "cond1-014", topic: "first-conditional", type: "fill", q: "What happens if you ___ this button?", hint: "press", answers: ["press"], explain: "Общая закономерность — Present Simple: What happens if you **press** this button?" },
  { id: "cond1-015", topic: "first-conditional", type: "fix", q: "If it don't rain tomorrow, we'll go to the beach.", answers: ["If it doesn't rain tomorrow, we'll go to the beach."], explain: "С it — **doesn't**: If it doesn't rain. Don't только с I, you, we, they." },

  // ---------- second-conditional ----------
  { id: "cond2-001", topic: "second-conditional", type: "choice", q: "If I ___ you, I would take the job.", options: ["were", "am", "will be"], answer: "were", explain: "Совет и нереальное условие: If I **were** you (were для всех лиц), I would take the job." },
  { id: "cond2-002", topic: "second-conditional", type: "fill", q: "If I had more time, I ___ learn Chinese.", answers: ["would", "could", "might"], explain: "Нереальное условие → **would** + глагол: If I had more time, I would learn Chinese." },
  { id: "cond2-003", topic: "second-conditional", type: "fix", q: "If I would have a car, I would drive to work.", answers: ["If I had a car, I would drive to work.", "I would drive to work if I had a car."], explain: "После if — Past Simple, не would." },
  { id: "cond2-004", topic: "second-conditional", type: "choice", q: "What would you do if you ___ a million dollars?", options: ["won", "win", "would win"], answer: "won", explain: "Нереальное условие: if + **Past Simple** (won), а в главной would. Won здесь — Past Simple от win." },
  { id: "cond2-005", topic: "second-conditional", type: "translate", q: "Если бы я знал ответ, я бы тебе сказал.", answers: ["If I knew the answer, I would tell you.", "I would tell you if I knew the answer."], explain: "Нереальное условие: If I **knew**…, I **would** tell you. Хотя форма прошедшая, речь о настоящем." },
  { id: "cond2-006", topic: "second-conditional", type: "choice", q: "She would travel more if she ___ afraid of flying.", options: ["weren't", "isn't", "wouldn't be"], answer: "weren't", explain: "Нереальное условие с be: if she **weren't** (were not) afraid — но она боится." },
  { id: "cond2-007", topic: "second-conditional", type: "choice", q: "If I won the lottery, I ___ travel around the world.", options: ["would", "will", "won"], answer: "would", explain: "Нереальное условие → **would travel**: If I won, I would travel. Will было бы про реальное." },
  { id: "cond2-008", topic: "second-conditional", type: "fill", q: "If you ___ any superpower, what would you choose?", hint: "have", answers: ["had"], explain: "После if — Past Simple: If you **had** any superpower, what would you choose?" },
  { id: "cond2-009", topic: "second-conditional", type: "fix", q: "If I will be rich, I would buy a big house.", answers: ["If I were rich, I would buy a big house.", "If I was rich, I would buy a big house."], explain: "После if нет will: If I **were** rich, I would buy. Нереальное, поэтому were." },
  { id: "cond2-010", topic: "second-conditional", type: "choice", q: "What would you say if he ___ you for a date?", options: ["asked", "asks", "would ask"], answer: "asked", explain: "В if-части — Past Simple: if he **asked** you for a date. Would в if-части не ставят." },
  { id: "cond2-011", topic: "second-conditional", type: "translate", q: "Если бы у меня была машина, я бы поехал с вами.", answers: ["If I had a car, I would go with you.", "I would go with you if I had a car."], explain: "If I **had** a car, I **would go** with you: нереальное условие (машины нет)." },
  { id: "cond2-012", topic: "second-conditional", type: "choice", q: "I wouldn't do that if I ___ you.", options: ["were", "am", "being"], answer: "were", explain: "Совет: I wouldn't do that if I **were** you. Устойчивая форма совета." },
  { id: "cond2-013", topic: "second-conditional", type: "fill", q: "If she studied harder, she ___ pass the exam.", answers: ["would", "could", "might"], explain: "Нереальное условие → **would pass** (или could/might)." },
  { id: "cond2-014", topic: "second-conditional", type: "fix", q: "If I had wings, I can fly.", answers: ["If I had wings, I could fly.", "If I had wings, I would be able to fly."], explain: "В главной части — would/could + глагол: If I had wings, I **could** fly. Can для нереального не подходит." },
  { id: "cond2-015", topic: "second-conditional", type: "choice", q: "Would you mind if I ___ the window?", options: ["opened", "open", "will open"], answer: "opened", explain: "Вежливая просьба: Would you mind if I **opened**? После if — Past Simple." },

  // ---------- future-time-clauses ----------
  { id: "ftc-001", topic: "future-time-clauses", type: "choice", q: "Call me when you ___ home.", options: ["get", "will get", "got"], answer: "get", explain: "После when о будущем — Present Simple: Call me when you **get** home. Will не нужно." },
  { id: "ftc-002", topic: "future-time-clauses", type: "fix", q: "I'll wait until you will come back.", answers: ["I'll wait until you come back."], explain: "После until — настоящее время." },
  { id: "ftc-003", topic: "future-time-clauses", type: "fill", q: "As soon as I ___ the results, I'll tell you.", hint: "get", answers: ["get", "have got"], explain: "После as soon as — Present Simple: As soon as I **get** the results." },
  { id: "ftc-004", topic: "future-time-clauses", type: "choice", q: "Before you ___, turn off the lights.", options: ["leave", "will leave", "left"], answer: "leave", explain: "После before — Present Simple: Before you **leave**, turn off the lights." },
  { id: "ftc-005", topic: "future-time-clauses", type: "translate", q: "Я позвоню тебе, когда приеду.", answers: ["I will call you when I arrive.", "I will call you when I get there.", "I will call you when I come.", "I will phone you when I arrive.", "I will phone you when I get there.", "When I arrive, I will call you.", "When I get there, I will call you."], explain: "В придаточной времени — Present Simple: I will call you when I **arrive**. Не «when I will arrive»." },
  { id: "ftc-006", topic: "future-time-clauses", type: "fill", q: "We'll start dinner after everyone ___.", hint: "arrive", answers: ["arrives", "has arrived"], explain: "После after — Present Simple, с everyone — единственное число: everyone **arrives**." },
  { id: "ftc-007", topic: "future-time-clauses", type: "choice", q: "I won't leave until you ___.", options: ["arrive", "will arrive", "arrived"], answer: "arrive", explain: "После until — Present Simple: until you **arrive**." },
  { id: "ftc-008", topic: "future-time-clauses", type: "fill", q: "By the time you ___ here, dinner will be ready.", hint: "get", answers: ["get"], explain: "После by the time — Present Simple: By the time you **get** here." },
  { id: "ftc-009", topic: "future-time-clauses", type: "fix", q: "When I will finish my homework, I'll watch TV.", answers: ["When I finish my homework, I'll watch TV."], explain: "После when — Present Simple, без will: When I **finish**." },
  { id: "ftc-010", topic: "future-time-clauses", type: "choice", q: "She'll text you as soon as she ___.", options: ["lands", "will land", "landed"], answer: "lands", explain: "После as soon as — Present Simple: as soon as she **lands** (she + -s)." },
  { id: "ftc-011", topic: "future-time-clauses", type: "translate", q: "Подожди здесь, пока я не вернусь.", answers: ["Wait here until I come back.", "Wait here until I return.", "Wait here until I get back."], explain: "После until — Present Simple: Wait here until I **come** back." },
  { id: "ftc-012", topic: "future-time-clauses", type: "choice", q: "After you ___ the form, send it to us.", options: ["fill in", "will fill in", "filled in"], answer: "fill in", explain: "После after — Present Simple: After you **fill in** the form. Fill in — заполнить." },
  { id: "ftc-013", topic: "future-time-clauses", type: "fill", q: "I'll let you know as soon as I ___ any news.", hint: "have", answers: ["have"], explain: "После as soon as — Present Simple: as soon as I **have** any news." },
  { id: "ftc-014", topic: "future-time-clauses", type: "fix", q: "We'll go for a walk after it will stop raining.", answers: ["We'll go for a walk after it stops raining."], explain: "После after — Present Simple: after it **stops** raining. Не «after it will stop»." },
  { id: "ftc-015", topic: "future-time-clauses", type: "choice", q: "By the time we ___, the shops will already be closed.", options: ["arrive", "will arrive", "arrived"], answer: "arrive", explain: "После by the time — Present Simple: By the time we **arrive**." },

  // ---------- passive-present-past ----------
  { id: "pass-001", topic: "passive-present-past", type: "choice", q: "English ___ in many countries.", options: ["is spoken", "speaks", "is speaking"], answer: "is spoken", explain: "Пассив в Present Simple: **is/are + V3**: English **is spoken** (не «speaks»)." },
  { id: "pass-002", topic: "passive-present-past", type: "fill", q: "This house ___ in 1920.", hint: "build", answers: ["was built"], explain: "Пассив в Past Simple: **was/were + V3**: was **built** (build → built → built)." },
  { id: "pass-003", topic: "passive-present-past", type: "fix", q: "My bike was stole yesterday.", answers: ["My bike was stolen yesterday."], explain: "В пассиве — третья форма: stolen." },
  { id: "pass-004", topic: "passive-present-past", type: "choice", q: "The letters ___ every morning.", options: ["are delivered", "deliver", "are delivering"], answer: "are delivered", explain: "Пассив, Present Simple, множественное число: letters **are delivered**." },
  { id: "pass-005", topic: "passive-present-past", type: "translate", q: "Меня пригласили на свадьбу.", answers: ["I was invited to the wedding.", "I was invited to a wedding.", "I have been invited to the wedding.", "I have been invited to a wedding."], explain: "Меня пригласили → **I was invited** (was + V3). Действие со мной." },
  { id: "pass-006", topic: "passive-present-past", type: "choice", q: "The meeting ___ cancelled.", options: ["has been", "has", "is been"], answer: "has been", explain: "Результат есть сейчас → Present Perfect passive: **has been** cancelled (has been + V3)." },
  { id: "pass-007", topic: "passive-present-past", type: "fill", q: "The Mona Lisa was painted ___ Leonardo da Vinci.", answers: ["by"], explain: "Кто сделал — **by** + исполнитель: painted **by** Leonardo." },
  { id: "pass-008", topic: "passive-present-past", type: "choice", q: "A new bridge ___ over the river next year.", options: ["will be built", "will build", "is building"], answer: "will be built", explain: "Будущее в пассиве: **will be + V3**: will be built." },
  { id: "pass-009", topic: "passive-present-past", type: "fill", q: "The rooms ___ every day.", hint: "clean", answers: ["are cleaned"], explain: "Пассив, Present Simple (rooms, каждый день): are **cleaned**." },
  { id: "pass-010", topic: "passive-present-past", type: "fix", q: "The window was break by the wind.", answers: ["The window was broken by the wind."], explain: "После was — третья форма: was **broken** (break → broke → broken)." },
  { id: "pass-011", topic: "passive-present-past", type: "choice", q: "This problem ___ yet.", options: ["hasn't been solved", "hasn't solved", "isn't solved"], answer: "hasn't been solved", explain: "Present Perfect passive с отрицанием: **hasn't been solved** (yet)." },
  { id: "pass-012", topic: "passive-present-past", type: "translate", q: "Этот фильм сняли в 2015 году.", answers: ["This film was made in 2015.", "This movie was made in 2015.", "This film was shot in 2015.", "This movie was shot in 2015."], explain: "Пассив в Past Simple: This film **was made** in 2015 (make → made)." },
  { id: "pass-013", topic: "passive-present-past", type: "choice", q: "The documents ___ to you by email tomorrow.", options: ["will be sent", "will send", "are sending"], answer: "will be sent", explain: "Пассив в будущем: documents **will be sent**." },
  { id: "pass-014", topic: "passive-present-past", type: "fill", q: "My phone ___ yesterday — someone took it from my bag.", hint: "steal", answers: ["was stolen"], explain: "Past Simple passive: was **stolen** (steal → stole → stolen)." },
  { id: "pass-015", topic: "passive-present-past", type: "fix", q: "They are building this bridge in 1990.", answers: ["This bridge was built in 1990.", "They built this bridge in 1990."], explain: "Время (in 1990) — прошлое, поэтому Past Simple: This bridge **was built** in 1990. В пассиве объект становится подлежащим." },

  // ---------- reported-speech ----------
  { id: "rep-001", topic: "reported-speech", type: "choice", q: "«I saw the film,» he said. → He said he ___ the film.", options: ["had seen", "has seen", "sees"], answer: "had seen", explain: "Past Simple при пересказе сдвигается в Past Perfect: saw → **had seen**." },
  { id: "rep-002", topic: "reported-speech", type: "choice", q: "She ___ me that she was leaving.", options: ["told", "said", "says"], answer: "told", explain: "tell + человек; say — без человека." },
  { id: "rep-003", topic: "reported-speech", type: "fix", q: "He asked me where did I live.", answers: ["He asked me where I lived."], explain: "Косвенный вопрос — прямой порядок слов, без did." },
  { id: "rep-004", topic: "reported-speech", type: "fill", q: "She asked me ___ I liked the film.", hint: "ли", answers: ["if", "whether"], explain: "Вопрос да/нет в косвенной речи вводится **if** (или whether): asked me **if** I liked." },
  { id: "rep-005", topic: "reported-speech", type: "choice", q: "«I'll call you tomorrow,» he said. → He said he ___ call me the next day.", options: ["would", "will", "can"], answer: "would", explain: "will → **would** при пересказе: He said he **would** call me the next day." },
  { id: "rep-006", topic: "reported-speech", type: "translate", q: "Он сказал, что устал.", answers: ["He said that he was tired.", "He said he was tired."], explain: "am/is → **was**: He said (that) he **was** tired." },
  { id: "rep-007", topic: "reported-speech", type: "fix", q: "She said me that she was busy.", answers: ["She told me that she was busy.", "She told me she was busy.", "She said that she was busy.", "She said she was busy.", "She said to me that she was busy.", "She said to me she was busy."], explain: "После told нужен человек: She **told** me. Said me неверно, а said to me можно." },
  { id: "rep-008", topic: "reported-speech", type: "choice", q: "«Don't touch that!» she said. → She told me ___ touch it.", options: ["not to", "to not", "don't"], answer: "not to", explain: "Просьба «не делай» → **not to** + глагол: told me **not to** touch." },
  { id: "rep-009", topic: "reported-speech", type: "fill", q: "He asked me if I ___ tired.", hint: "be", answers: ["was"], explain: "Косвенный вопрос да/нет: asked me **if** I **was** tired (am → was)." },
  { id: "rep-010", topic: "reported-speech", type: "fix", q: "She asked me what time is it.", answers: ["She asked me what time it was."], explain: "В косвенном вопросе прямой порядок слов и сдвиг времени: what time **it was**." },
  { id: "rep-011", topic: "reported-speech", type: "choice", q: "«I can help you,» he said. → He said he ___ help me.", options: ["could", "can", "would could"], answer: "could", explain: "can → **could** при пересказе: He said he **could** help me." },
  { id: "rep-012", topic: "reported-speech", type: "translate", q: "Она спросила, откуда я.", answers: ["She asked me where I was from.", "She asked where I was from."], explain: "Косвенный вопрос — прямой порядок: where **I was** from. Не «where was I»." },
  { id: "rep-013", topic: "reported-speech", type: "choice", q: "«I've finished my homework,» she said. → She said she ___ her homework.", options: ["had finished", "has finished", "finished"], answer: "had finished", explain: "Present Perfect → **had finished**: She said she **had finished** her homework." },
  { id: "rep-014", topic: "reported-speech", type: "fill", q: "He told me ___ hurry because we were late.", hint: "to", answers: ["to"], explain: "Приказ в косвенной речи: told me **to** hurry." },
  { id: "rep-015", topic: "reported-speech", type: "fix", q: "They asked us do we want tea or coffee.", answers: ["They asked us if we wanted tea or coffee.", "They asked us whether we wanted tea or coffee."], explain: "Вопрос да/нет → **if** + прямой порядок + сдвиг: asked us **if** we **wanted** tea or coffee." },

  // ---------- relative-clauses ----------
  { id: "rel-001", topic: "relative-clauses", type: "choice", q: "The woman ___ lives next door is a doctor.", options: ["who", "which", "whose"], answer: "who", explain: "Человек (the woman) и подлежащее придаточной → **who**: The woman who lives next door." },
  { id: "rel-002", topic: "relative-clauses", type: "choice", q: "This is the book ___ I told you about.", options: ["that", "who", "where"], answer: "that", explain: "Вещь (the book) и она дополнение придаточной → **that** (или which). Who — только для людей, where — для места." },
  { id: "rel-003", topic: "relative-clauses", type: "fill", q: "That's the man ___ car was stolen.", answers: ["whose"], explain: "Принадлежность («чья машина») → **whose**: the man whose car was stolen." },
  { id: "rel-004", topic: "relative-clauses", type: "fix", q: "The city where I was born in is very small.", answers: ["The city where I was born is very small.", "The city I was born in is very small.", "The city that I was born in is very small.", "The city which I was born in is very small."], explain: "where уже значит «в котором», in не нужен." },
  { id: "rel-005", topic: "relative-clauses", type: "choice", q: "I have a friend ___ speaks five languages.", options: ["who", "which", "what"], answer: "who", explain: "Человек (a friend) и подлежащее придаточной → **who**: a friend who speaks." },
  { id: "rel-006", topic: "relative-clauses", type: "translate", q: "Это кафе, где мы познакомились.", answers: ["This is the café where we met.", "This is the cafe where we met.", "That is the café where we met.", "That is the cafe where we met.", "This is the café where we first met.", "This is the cafe where we first met."], explain: "Для места — **where**: the café where we met." },
  { id: "rel-007", topic: "relative-clauses", type: "choice", q: "My car, ___ is ten years old, still runs well.", options: ["which", "that", "who"], answer: "which", explain: "В запятых — только who/which, не that." },
  { id: "rel-008", topic: "relative-clauses", type: "choice", q: "The restaurant ___ we had dinner was excellent.", options: ["where", "which", "who"], answer: "where", explain: "Для места — **where**: the restaurant where we had dinner." },
  { id: "rel-009", topic: "relative-clauses", type: "fill", q: "Do you remember the day ___ we first met?", answers: ["when"], explain: "Для времени — **when**: the day when we first met." },
  { id: "rel-010", topic: "relative-clauses", type: "fix", q: "The book which I bought it yesterday is great.", answers: ["The book which I bought yesterday is great.", "The book I bought yesterday is great.", "The book that I bought yesterday is great."], explain: "После which/that не нужно ещё раз повторять местоимение it." },
  { id: "rel-011", topic: "relative-clauses", type: "choice", q: "That's the boy ___ dog bit me.", options: ["whose", "who", "which"], answer: "whose", explain: "Принадлежность → **whose**: the boy whose dog bit me (чья собака)." },
  { id: "rel-012", topic: "relative-clauses", type: "translate", q: "Человек, которого ты вчера видел, — мой брат.", answers: ["The man you saw yesterday is my brother.", "The man that you saw yesterday is my brother.", "The man who you saw yesterday is my brother.", "The man whom you saw yesterday is my brother."], explain: "Местоимение-дополнение можно опустить: The man (**who**) you saw yesterday. Who/that здесь не обязательны." },
  { id: "rel-013", topic: "relative-clauses", type: "choice", q: "This is the reason ___ I called you.", options: ["why", "where", "which"], answer: "why", explain: "После the reason — **why**: the reason why I called." },
  { id: "rel-014", topic: "relative-clauses", type: "fill", q: "The film, ___ was based on a true story, won several awards.", answers: ["which"], explain: "Неопределяющее придаточное в запятых — только **which** (не that): The film, which was based on…" },
  { id: "rel-015", topic: "relative-clauses", type: "fix", q: "She's the woman which helped me yesterday.", answers: ["She's the woman who helped me yesterday.", "She's the woman that helped me yesterday."], explain: "Про людей — **who** (не which): the woman who helped me." },

  // ---------- modals-deduction ----------
  { id: "deduct-001", topic: "modals-deduction", type: "choice", q: "He's been working for 12 hours. He ___ be tired.", options: ["must", "can't", "mustn't"], answer: "must", explain: "Работал 12 часов — почти уверен, что устал → **must be**." },
  { id: "deduct-002", topic: "modals-deduction", type: "choice", q: "That ___ be true! I don't believe it.", options: ["can't", "mustn't", "must"], answer: "can't", explain: "Не может быть правдой → **can't be**. Mustn't значит «нельзя», не «не может быть»." },
  { id: "deduct-003", topic: "modals-deduction", type: "fill", q: "Take an umbrella — it ___ rain later.", hint: "возможно", answers: ["might", "may", "could"], explain: "Возможно пойдёт дождь → **might** rain (может быть, не уверены)." },
  { id: "deduct-004", topic: "modals-deduction", type: "fix", q: "She mustn't be at home — the lights are off.", answers: ["She can't be at home — the lights are off."], explain: "«Не может быть» — can't. mustn't — это запрет." },
  { id: "deduct-005", topic: "modals-deduction", type: "choice", q: "Someone's knocking. It ___ be the postman — he always comes at this time.", options: ["must", "can't", "mustn't"], answer: "must", explain: "Всегда приходит в это время — почти уверен → **must be** the postman." },
  { id: "deduct-006", topic: "modals-deduction", type: "translate", q: "Он, наверное, дома.", answers: ["He must be at home.", "He must be home.", "He is probably at home.", "He is probably home."], explain: "Он, наверное, дома → **must be** at home (уверенное предположение)." },
  { id: "deduct-007", topic: "modals-deduction", type: "choice", q: "She's not answering her phone. She ___ be busy.", options: ["might", "can't", "mustn't"], answer: "might", explain: "Не отвечает — возможно, занята, но не уверены → **might be**." },
  { id: "deduct-008", topic: "modals-deduction", type: "fill", q: "He's wearing a wedding ring. He ___ be married.", hint: "уверен", answers: ["must"], explain: "Обручальное кольцо — почти уверенность → **must be** married." },
  { id: "deduct-009", topic: "modals-deduction", type: "fix", q: "You mustn't be tired after such a short walk.", answers: ["You can't be tired after such a short walk."], explain: "«Не может быть» — can't, а не mustn't (mustn't — это запрет)." },
  { id: "deduct-010", topic: "modals-deduction", type: "choice", q: "You ___ be starving — you haven't eaten all day!", options: ["must", "can't", "might"], answer: "must", explain: "Весь день не ел — почти уверен: проголодался → **must be** starving." },
  { id: "deduct-011", topic: "modals-deduction", type: "translate", q: "Возможно, они уже дома.", answers: ["They might be at home already.", "They may be at home already.", "They could be at home already."], explain: "Возможно, но не уверены → **might be** at home." },
  { id: "deduct-012", topic: "modals-deduction", type: "choice", q: "This bag is very heavy. There ___ be a lot of books in it.", options: ["must", "can't", "might"], answer: "must", explain: "Сумка тяжёлая — логический вывод → **must be** a lot of books." },
  { id: "deduct-013", topic: "modals-deduction", type: "fill", q: "I'm not sure where she is. She ___ be in the library.", hint: "возможно", answers: ["might", "may", "could"], explain: "I'm not sure → возможность → **might be**." },
  { id: "deduct-014", topic: "modals-deduction", type: "fix", q: "He must to be at home now.", answers: ["He must be at home now."], explain: "После модального глагола must — инфинитив без to." },
  { id: "deduct-015", topic: "modals-deduction", type: "choice", q: "You've been driving for ten hours. You ___ be exhausted.", options: ["must", "can't", "might"], answer: "must", explain: "Десять часов за рулём — почти уверен: измотан → **must be**." },

  // ---------- phrasal-verbs-common ----------
  { id: "phr-001", topic: "phrasal-verbs-common", type: "choice", q: "Can you ___ the TV? I want to watch the news.", options: ["turn on", "turn off", "take off"], answer: "turn on", explain: "turn **on** — включить; turn off — выключить; take off — снять/взлететь." },
  { id: "phr-002", topic: "phrasal-verbs-common", type: "choice", q: "I'm ___ my glasses. Have you seen them?", options: ["looking for", "looking after", "looking at"], answer: "looking for", explain: "look **for** — искать; look after — заботиться; look at — смотреть на." },
  { id: "phr-003", topic: "phrasal-verbs-common", type: "fill", q: "It's cold outside. ___ your jacket.", hint: "надень (2 слова)", answers: ["Put on"], explain: "put **on** — надеть (одежду)." },
  { id: "phr-004", topic: "phrasal-verbs-common", type: "fix", q: "Turn off it, please.", answers: ["Turn it off, please.", "Please turn it off."], explain: "С местоимением частица идёт после него: turn it off." },
  { id: "phr-005", topic: "phrasal-verbs-common", type: "choice", q: "We've ___ of sugar. Can you buy some?", options: ["run out", "run away", "run into"], answer: "run out", explain: "run **out** of — закончиться: we've run out of sugar. Run away — убежать, run into — случайно встретить." },
  { id: "phr-006", topic: "phrasal-verbs-common", type: "translate", q: "Я бросил курить.", answers: ["I gave up smoking.", "I have given up smoking.", "I quit smoking.", "I have quit smoking.", "I stopped smoking.", "I have stopped smoking."], explain: "give **up** — бросить; после него -ing: gave up smoking." },
  { id: "phr-007", topic: "phrasal-verbs-common", type: "fill", q: "Can you ___ me up at the airport?", answers: ["pick"], explain: "pick (someone) **up** — забрать, подвезти." },
  { id: "phr-008", topic: "phrasal-verbs-common", type: "choice", q: "Please ___ this form.", options: ["fill in", "fill on", "fill at"], answer: "fill in", explain: "fill **in** a form — заполнить анкету." },
  { id: "phr-009", topic: "phrasal-verbs-common", type: "choice", q: "Can you ___ my cat while I'm away?", options: ["look after", "look for", "look at"], answer: "look after", explain: "look **after** — присматривать, заботиться: look after my cat." },
  { id: "phr-010", topic: "phrasal-verbs-common", type: "fill", q: "I need to ___ what time the train leaves.", hint: "узнать (2 слова)", answers: ["find out"], explain: "find **out** — выяснить, узнать." },
  { id: "phr-011", topic: "phrasal-verbs-common", type: "fix", q: "My car has broken this morning, so I took the bus.", answers: ["My car broke down this morning, so I took the bus."], explain: "«сломалась» (о машине, приборе) — break down." },
  { id: "phr-012", topic: "phrasal-verbs-common", type: "choice", q: "We had to ___ the meeting until next week.", options: ["put off", "put on", "put out"], answer: "put off", explain: "put **off** — отложить: put off the meeting. Put on — надеть/включить." },
  { id: "phr-013", topic: "phrasal-verbs-common", type: "translate", q: "Я случайно встретил старого друга в магазине.", answers: ["I ran into an old friend at the shop.", "I ran into an old friend in the shop.", "I came across an old friend at the shop.", "I came across an old friend in the shop.", "I bumped into an old friend at the shop.", "I bumped into an old friend in the shop."], explain: "run **into** — случайно встретить: ran into an old friend." },
  { id: "phr-014", topic: "phrasal-verbs-common", type: "choice", q: "They don't ___ well — they argue all the time.", options: ["get on", "get up", "get off"], answer: "get on", explain: "get **on** (well) — ладить с кем-то. Get up — вставать, get off — выходить." },
  { id: "phr-015", topic: "phrasal-verbs-common", type: "fill", q: "Please ___ your shoes before you come in.", hint: "снять (2 слова)", answers: ["take off"], explain: "take **off** — снять (одежду, обувь)." },

  // --- phr: частицы up/down/in/off/out/on ---
  { id: "phr-016", topic: "phrasal-verbs-common", type: "fix", q: "I want to give up tennis. It looks fun.", answers: ["I want to take up tennis. It looks fun."], explain: "give up — бросить, take up — начать заниматься. По смыслу («выглядит весело») нужно take up." },
  { id: "phr-017", topic: "phrasal-verbs-common", type: "choice", q: "My dad ___ smoking last year, and now he feels much better.", options: ["gave up", "took up", "carried on"], answer: "gave up", explain: "give up (+ -ing) — бросить." },
  { id: "phr-018", topic: "phrasal-verbs-common", type: "fix", q: "I can't hear the TV. Please turn down the volume.", answers: ["I can't hear the TV. Please turn up the volume.", "I can't hear the TV. Please turn the volume up."], explain: "Не слышно → нужно громче: turn up. turn down — сделать тише." },
  { id: "phr-019", topic: "phrasal-verbs-common", type: "choice", q: "Only five people ___ at the party, so it was quiet.", options: ["turned up", "took up", "gave up"], answer: "turned up", explain: "turn up — появиться, прийти." },
  { id: "phr-020", topic: "phrasal-verbs-common", type: "choice", q: "It started to rain, but the players ___ playing.", options: ["carried on", "took up", "sent off"], answer: "carried on", explain: "carry on + -ing — продолжать." },
  { id: "phr-021", topic: "phrasal-verbs-common", type: "choice", q: "Can I ___ the game? It looks fun.", options: ["join in", "join on", "join up"], answer: "join in", explain: "join in — присоединиться к игре или разговору." },
  { id: "phr-022", topic: "phrasal-verbs-common", type: "choice", q: "We're tired of cooking, so let's ___ tonight.", options: ["eat out", "eat up", "eat in"], answer: "eat out", explain: "eat out — поесть в кафе, ресторане (вне дома). eat up — доесть." },
  { id: "phr-023", topic: "phrasal-verbs-common", type: "choice", q: "The referee ___ the player for a foul.", options: ["sent off", "sent out", "sent in"], answer: "sent off", explain: "send off — удалить игрока с поля." },
  { id: "phr-024", topic: "phrasal-verbs-common", type: "fix", q: "She turned the offer up because the job was too far away.", answers: ["She turned the offer down because the job was too far away.", "She turned down the offer because the job was too far away."], explain: "turn down — отклонить (предложение, приглашение)." },
  { id: "phr-025", topic: "phrasal-verbs-common", type: "fix", q: "He gave up to play the guitar after the accident.", answers: ["He gave up playing the guitar after the accident."], explain: "После give up — глагол с -ing: give up playing." },
  { id: "phr-026", topic: "phrasal-verbs-common", type: "fix", q: "Please carry on to work. I'll be back in a minute.", answers: ["Please carry on working. I'll be back in a minute."], explain: "carry on + -ing: carry on working." },
  { id: "phr-027", topic: "phrasal-verbs-common", type: "fix", q: "We never cook on Fridays; we always eat up at a restaurant.", answers: ["We never cook on Fridays; we always eat out at a restaurant."], explain: "eat out — поесть вне дома. eat up означает «доесть»." },
  { id: "phr-028", topic: "phrasal-verbs-common", type: "fix", q: "Don't send off it yet — I'm still writing the email.", answers: ["Don't send it off yet — I'm still writing the email."], explain: "С местоимением частица идёт после него: send it off (не «send off it»)." },
  { id: "phr-029", topic: "phrasal-verbs-common", type: "fill", q: "My sister wants to ___ yoga next month.", hint: "начать заниматься (2 слова)", answers: ["take up"], explain: "take up — начать заниматься (хобби, спортом)." },
  { id: "phr-030", topic: "phrasal-verbs-common", type: "translate", q: "Он не пришёл на матч.", answers: ["He didn't turn up at the match.", "He didn't turn up for the match.", "He didn't turn up to the match."], explain: "turn up — появиться, прийти. Отрицание: didn't + turn up." },

  // --- phr: письмо и учёба ---
  { id: "phr-031", topic: "phrasal-verbs-common", type: "choice", q: "Please ___ the page and read the next one.", options: ["turn over", "turn up", "turn off"], answer: "turn over", explain: "turn over — перевернуть страницу." },
  { id: "phr-032", topic: "phrasal-verbs-common", type: "choice", q: "I don't know this word — I'll ___ in a dictionary.", options: ["look it up", "look it for", "look up it"], answer: "look it up", explain: "look up — найти в словаре; с местоимением — look it up." },
  { id: "phr-033", topic: "phrasal-verbs-common", type: "fix", q: "Please write down it on the board.", answers: ["Please write it down on the board."], explain: "С местоимением частица идёт после него: write it down." },
  { id: "phr-034", topic: "phrasal-verbs-common", type: "fix", q: "She crossed the wrong answer up.", answers: ["She crossed the wrong answer out.", "She crossed out the wrong answer."], explain: "cross out — вычеркнуть." },
  { id: "phr-035", topic: "phrasal-verbs-common", type: "fix", q: "He pointed out it to me.", answers: ["He pointed it out to me."], explain: "С местоимением: pointed it out." },
  { id: "phr-036", topic: "phrasal-verbs-common", type: "fill", q: "Can you ___ the answers to the class?", hint: "прочитать вслух (2 слова)", answers: ["read out"], explain: "read out — прочитать вслух." },
  { id: "phr-037", topic: "phrasal-verbs-common", type: "fill", q: "She was so angry that she ___ the letter.", hint: "разорвать (2 слова)", answers: ["ripped up", "tore up"], explain: "rip up — разорвать на куски." },
  { id: "phr-038", topic: "phrasal-verbs-common", type: "choice", q: "Use an eraser to ___ the wrong word.", options: ["rub out", "rip up", "read out"], answer: "rub out", explain: "rub out — стереть ластиком." },
  { id: "phr-039", topic: "phrasal-verbs-common", type: "translate", q: "Запиши мой номер телефона.", answers: ["Write down my phone number.", "Write my phone number down.", "Please write down my phone number.", "Please write my phone number down.", "Write down my telephone number.", "Write my telephone number down."], explain: "write down — записать." },
  { id: "phr-040", topic: "phrasal-verbs-common", type: "translate", q: "Он указал на ошибку.", answers: ["He pointed out the mistake.", "He pointed out a mistake.", "He pointed the mistake out.", "He pointed a mistake out.", "He pointed out the error.", "He pointed out an error."], explain: "point out — указать, обратить внимание." },

  // ---------- question-tags ----------
  { id: "tag-001", topic: "question-tags", type: "choice", q: "You're from Kazan, ___?", options: ["aren't you", "are you", "don't you"], answer: "aren't you", explain: "Утверждение (You're) → отрицательный хвостик с тем же глаголом: You're…, **aren't you**?" },
  { id: "tag-002", topic: "question-tags", type: "choice", q: "She doesn't eat meat, ___?", options: ["does she", "doesn't she", "is she"], answer: "does she", explain: "Отрицание (doesn't) → положительный хвостик: …, **does she**?" },
  { id: "tag-003", topic: "question-tags", type: "fill", q: "They went to the party, ___ they?", answers: ["didn't"], explain: "Past Simple → хвостик с did: They went…, **didn't they**?" },
  { id: "tag-004", topic: "question-tags", type: "fix", q: "He can swim, doesn't he?", answers: ["He can swim, can't he?"], explain: "Хвостик берёт тот же модальный глагол: can → **can't he**. Doesn't — для обычных глаголов." },
  { id: "tag-005", topic: "question-tags", type: "choice", q: "I'm late, ___?", options: ["aren't I", "am not I", "isn't it"], answer: "aren't I", explain: "Особый случай: I'm late, **aren't I**? (не «am not I»)." },
  { id: "tag-006", topic: "question-tags", type: "fill", q: "Let's go to the beach, ___ we?", answers: ["shall"], explain: "После Let's хвостик — **shall we**?" },
  { id: "tag-007", topic: "question-tags", type: "choice", q: "It's a beautiful day, ___?", options: ["isn't it", "is it", "doesn't it"], answer: "isn't it", explain: "It's → **isn't it**: утверждение даёт отрицательный хвостик." },
  { id: "tag-008", topic: "question-tags", type: "choice", q: "Close the door, ___?", options: ["will you", "won't you", "do you"], answer: "will you", explain: "Хвостик после приказа/просьбы — will you?" },
  { id: "tag-009", topic: "question-tags", type: "fill", q: "There's a problem, ___ there?", answers: ["isn't"], explain: "There's → **isn't there**: слово there остаётся." },
  { id: "tag-010", topic: "question-tags", type: "fix", q: "He should call her, isn't he?", answers: ["He should call her, shouldn't he?"], explain: "Тот же модальный: should → **shouldn't he**. Isn't — это для be." },
  { id: "tag-011", topic: "question-tags", type: "choice", q: "Nobody called, ___?", options: ["did they", "didn't they", "have they"], answer: "did they", explain: "nobody/nothing — уже отрицание, поэтому хвостик положительный." },
  { id: "tag-012", topic: "question-tags", type: "translate", q: "Ты ведь не куришь, да?", answers: ["You don't smoke, do you?"], explain: "Отрицание → положительный хвостик: You don't smoke, **do you**?" },
  { id: "tag-013", topic: "question-tags", type: "choice", q: "I'm not late, ___?", options: ["am I", "aren't I", "isn't it"], answer: "am I", explain: "Отрицание (I'm not) → положительный хвостик: **am I**?" },
  { id: "tag-014", topic: "question-tags", type: "fill", q: "You can swim, ___ you?", answers: ["can't"], explain: "Утверждение (can) → отрицательный хвостик: **can't** you?" },
  { id: "tag-015", topic: "question-tags", type: "fix", q: "Let's have a break, do we?", answers: ["Let's have a break, shall we?"], explain: "После Let's — **shall we**? (не do we)." },

  // ---------- so-such ----------
  { id: "so-001", topic: "so-such", type: "choice", q: "It was ___ a good film!", options: ["such", "so"], answer: "such", explain: "such + a + прилагательное + существительное: **such a** good film." },
  { id: "so-002", topic: "so-such", type: "choice", q: "The weather is ___ nice today!", options: ["so", "such"], answer: "so", explain: "so + прилагательное (без существительного): **so** nice." },
  { id: "so-003", topic: "so-such", type: "fill", q: "They are ___ friendly people.", answers: ["such"], explain: "such + прилагательное + существительное во мн. числе: **such** friendly people." },
  { id: "so-004", topic: "so-such", type: "fix", q: "It was so a long day.", answers: ["It was such a long day."], explain: "Перед существительным — такая конструкция: **such a** long day. «so a long day» неверно." },
  { id: "so-005", topic: "so-such", type: "choice", q: "I was ___ tired that I fell asleep at once.", options: ["so", "such", "too"], answer: "so", explain: "so + прилагательное + that: **so** tired that…" },
  { id: "so-006", topic: "so-such", type: "translate", q: "Здесь так много людей!", answers: ["There are so many people here!", "There are so many people!"], explain: "so many + исчисляемое: **so many** people (so much — с неисчисляемыми)." },
  { id: "so-007", topic: "so-such", type: "choice", q: "He is ___ a kind person.", options: ["such", "so"], answer: "such", explain: "such a + прилагательное + существительное: **such** a kind person." },
  { id: "so-008", topic: "so-such", type: "fill", q: "It's ___ cold today!", answers: ["so"], explain: "so + прилагательное: **so** cold." },
  { id: "so-009", topic: "so-such", type: "fix", q: "She has so beautiful eyes.", answers: ["She has such beautiful eyes."], explain: "Есть существительное (eyes) → **such** beautiful eyes. So — только перед прилагательным." },
  { id: "so-010", topic: "so-such", type: "choice", q: "The music was ___ loud that we couldn't talk.", options: ["so", "such"], answer: "so", explain: "so + прилагательное + that (результат): **so** loud that." },
  { id: "so-011", topic: "so-such", type: "translate", q: "Это была такая интересная книга!", answers: ["It was such an interesting book!"], explain: "such + an + прил. + сущ.: **such an** interesting book." },
  { id: "so-012", topic: "so-such", type: "choice", q: "They have ___ many pets!", options: ["so", "such"], answer: "so", explain: "so many pets: so + many + исчисляемое." },
  { id: "so-013", topic: "so-such", type: "fill", q: "It was ___ a difficult exam that half the class failed.", answers: ["such"], explain: "such + a + прил. + сущ. + that: **such a** difficult exam that…" },
  { id: "so-014", topic: "so-such", type: "fix", q: "He speaks so good English.", answers: ["He speaks such good English.", "He speaks English so well."], explain: "Есть существительное (English) → **such** good English. So good — без существительного." },
  { id: "so-015", topic: "so-such", type: "choice", q: "I was ___ surprised to see you there!", options: ["so", "such"], answer: "so", explain: "so + прилагательное: **so** surprised. Существительного нет." },

  // ---------- verb-patterns ----------
  { id: "vp-001", topic: "verb-patterns", type: "choice", q: "I stopped ___ two years ago. I feel much better now.", options: ["smoking", "to smoke"], answer: "smoking", explain: "stop doing — перестать делать." },
  { id: "vp-002", topic: "verb-patterns", type: "choice", q: "Remember ___ the door when you leave!", options: ["to lock", "locking"], answer: "to lock", explain: "remember to do — не забыть сделать." },
  { id: "vp-003", topic: "verb-patterns", type: "fix", q: "I want that you help me.", answers: ["I want you to help me."], explain: "want + кто-то + **to** + глагол: I want **you to help** me. Нельзя «want that you»." },
  { id: "vp-004", topic: "verb-patterns", type: "fill", q: "My parents let me ___ to the party.", hint: "go", answers: ["go"], explain: "let + глагол без to." },
  { id: "vp-005", topic: "verb-patterns", type: "fix", q: "He suggested me to go to the cinema.", answers: ["He suggested going to the cinema.", "He suggested that I go to the cinema.", "He suggested I go to the cinema.", "He suggested that I should go to the cinema.", "He suggested I should go to the cinema.", "He suggested that we go to the cinema.", "He suggested we go to the cinema."], explain: "После suggest — **-ing**: suggested **going**. Suggest me to — неверно." },
  { id: "vp-006", topic: "verb-patterns", type: "choice", q: "She asked me ___ for her.", options: ["to wait", "wait", "waiting"], answer: "to wait", explain: "ask + кто-то + **to** + глагол: She asked me **to wait**." },
  { id: "vp-007", topic: "verb-patterns", type: "translate", q: "Не забудь позвонить маме.", answers: ["Don't forget to call your mum.", "Don't forget to call your mom.", "Don't forget to call mum.", "Don't forget to call mom.", "Don't forget to phone your mum.", "Don't forget to phone your mom.", "Remember to call your mum.", "Remember to call your mom."], explain: "Don't forget + **to** + глагол (не забыть сделать)." },
  { id: "vp-008", topic: "verb-patterns", type: "choice", q: "The film made me ___.", options: ["cry", "to cry", "crying"], answer: "cry", explain: "make + глагол без to." },
  { id: "vp-009", topic: "verb-patterns", type: "choice", q: "I forgot ___ my keys, so I couldn't get in.", options: ["to take", "taking"], answer: "to take", explain: "forget to do — забыть сделать; forget doing — забыть, что уже сделал." },
  { id: "vp-010", topic: "verb-patterns", type: "fill", q: "I'll never forget ___ the Northern Lights for the first time.", hint: "see", answers: ["seeing"], explain: "forget + **-ing** — забыть о том, что было (воспоминание): never forget **seeing**." },
  { id: "vp-011", topic: "verb-patterns", type: "fix", q: "He finished to read the book last night.", answers: ["He finished reading the book last night."], explain: "После finish — **-ing**: finished **reading**." },
  { id: "vp-012", topic: "verb-patterns", type: "choice", q: "Would you mind ___ the door?", options: ["closing", "to close", "close"], answer: "closing", explain: "Would you mind + **-ing**: Would you mind **closing** the door?" },
  { id: "vp-013", topic: "verb-patterns", type: "translate", q: "Он избегает есть сладкое.", answers: ["He avoids eating sweets."], explain: "После avoid — **-ing**: avoids **eating**." },
  { id: "vp-014", topic: "verb-patterns", type: "choice", q: "My boss won't let me ___ home early.", options: ["go", "to go", "going"], answer: "go", explain: "let + кто-то + глагол **без to**: won't let me **go**." },
  { id: "vp-015", topic: "verb-patterns", type: "fix", q: "She helped me to carrying the bags.", answers: ["She helped me carry the bags.", "She helped me to carry the bags."], explain: "help + кто-то + глагол без to (или to): helped me **carry**. После help не -ing." },

  // ---------- verb-patterns ----------
  { id: "vp-016", topic: "verb-patterns", type: "fix", q: "She has finished to read the book.", answers: ["She has finished reading the book.", "She's finished reading the book."], explain: "После finish — глагол с -ing." },
  { id: "vp-017", topic: "verb-patterns", type: "fix", q: "He hasn't finished to getting ready.", answers: ["He hasn't finished getting ready.", "He has not finished getting ready."], explain: "finish + -ing, без to." },
  { id: "vp-018", topic: "verb-patterns", type: "fix", q: "I enjoy to swim in the sea.", answers: ["I enjoy swimming in the sea."], explain: "enjoy + -ing." },
  { id: "vp-019", topic: "verb-patterns", type: "fix", q: "Avoid to make the same mistake.", answers: ["Avoid making the same mistake."], explain: "avoid + -ing." },
  { id: "vp-020", topic: "verb-patterns", type: "choice", q: "Keep ___ — you're almost there!", options: ["trying", "to try", "try"], answer: "trying", explain: "keep + -ing." },
  { id: "vp-021", topic: "verb-patterns", type: "fill", q: "They suggested ___ a taxi.", hint: "take", answers: ["taking"], explain: "suggest + -ing." },
  { id: "vp-022", topic: "verb-patterns", type: "choice", q: "I don't mind ___ for you.", options: ["waiting", "to wait", "wait"], answer: "waiting", explain: "mind + -ing." },
  { id: "vp-023", topic: "verb-patterns", type: "translate", q: "Я закончил писать письмо.", answers: ["I have finished writing the letter.", "I've finished writing the letter.", "I finished writing the letter.", "I have finished writing a letter.", "I finished writing a letter.", "I've finished writing a letter."], explain: "finish + -ing." },

  // ---------- linking-words ----------
  { id: "link-001", topic: "linking-words", type: "choice", q: "___ it was raining, we went for a walk.", options: ["Although", "Despite", "However"], answer: "Although", explain: "Although + целое предложение (it was raining): **Although** it was raining, we went." },
  { id: "link-002", topic: "linking-words", type: "choice", q: "___ the rain, we went for a walk.", options: ["Despite", "Although", "Because"], answer: "Despite", explain: "Despite + существительное (the rain): **Despite** the rain. После despite нет предложения." },
  { id: "link-003", topic: "linking-words", type: "fill", q: "The flight was delayed because ___ the fog.", answers: ["of"], explain: "because **of** + существительное (the fog). Because + предложение." },
  { id: "link-004", topic: "linking-words", type: "fix", q: "Despite it was cold, she didn't wear a coat.", answers: ["Although it was cold, she didn't wear a coat.", "Even though it was cold, she didn't wear a coat.", "Though it was cold, she didn't wear a coat.", "Despite the cold, she didn't wear a coat.", "Despite it being cold, she didn't wear a coat."], explain: "despite + существительное; с целым предложением — although." },
  { id: "link-005", topic: "linking-words", type: "choice", q: "The hotel was expensive. ___, it was worth it.", options: ["However", "Although", "Despite"], answer: "However", explain: "However — «однако» в начале нового предложения, с запятой: **However**, it was worth it." },
  { id: "link-006", topic: "linking-words", type: "translate", q: "Я учу английский, чтобы найти работу за границей.", answers: ["I am learning English to find a job abroad.", "I am learning English in order to find a job abroad.", "I am learning English so that I can find a job abroad.", "I am studying English to find a job abroad.", "I am studying English in order to find a job abroad.", "I am studying English so that I can find a job abroad.", "I am learning English to get a job abroad.", "I am studying English to get a job abroad.", "I learn English to find a job abroad."], explain: "Цель: **to** + глагол (или in order to): to find a job." },
  { id: "link-007", topic: "linking-words", type: "choice", q: "___ the traffic, we arrived on time.", options: ["In spite of", "Although", "Because"], answer: "In spite of", explain: "In spite of + существительное (the traffic): **In spite of** the traffic." },
  { id: "link-008", topic: "linking-words", type: "fill", q: "I like her, ___ she can be a bit rude sometimes.", answers: ["although", "though", "even though"], explain: "Although + предложение: I like her, **although** she can be rude." },
  { id: "link-009", topic: "linking-words", type: "fix", q: "Despite that it was raining, we went out.", answers: ["Despite the rain, we went out.", "Although it was raining, we went out.", "In spite of the rain, we went out.", "Despite it raining, we went out."], explain: "После despite — существительное: **Despite the rain**. «despite that + предложение» неверно." },
  { id: "link-010", topic: "linking-words", type: "choice", q: "He failed the exam ___ he didn't study.", options: ["because", "despite", "however"], answer: "because", explain: "Причина (didn't study) → **because**." },
  { id: "link-011", topic: "linking-words", type: "translate", q: "Хотя было холодно, дети играли на улице.", answers: ["Although it was cold, the children played outside.", "Even though it was cold, the children played outside.", "Though it was cold, the children played outside."], explain: "Although + предложение: **Although** it was cold, …" },
  { id: "link-012", topic: "linking-words", type: "choice", q: "My sister loves sports, ___ I prefer reading.", options: ["whereas", "despite", "because"], answer: "whereas", explain: "Противопоставление двух людей: **whereas** («тогда как»): my sister loves sports, whereas I prefer reading." },
  { id: "link-013", topic: "linking-words", type: "fill", q: "The flight was cancelled because ___ the storm.", answers: ["of"], explain: "because **of** + существительное (the storm)." },
  { id: "link-014", topic: "linking-words", type: "fix", q: "Although he is rich, but he is not happy.", answers: ["Although he is rich, he is not happy.", "Though he is rich, he is not happy.", "Even though he is rich, he is not happy.", "He is rich, but he is not happy.", "He is rich. However, he is not happy.", "He is rich; however, he is not happy.", "Although he is rich, he is unhappy."], explain: "Although (хотя) и but (но) вместе не употребляются: в предложении нужно что-то одно. Либо Although he is rich, he is not happy, либо He is rich, but he is not happy." },
  { id: "link-015", topic: "linking-words", type: "choice", q: "___ she was tired, she kept working.", options: ["Even though", "Despite", "Because of"], answer: "Even though", explain: "Even though + предложение (она устала, но продолжила): **Even though** she was tired." },

  // ---------- vocab-feelings-character ----------
  { id: "v-feel-001", topic: "vocab-feelings-character", type: "choice", q: "I'm really ___ about the exam tomorrow.", options: ["worried", "worrying", "proud"], answer: "worried", explain: "worried **about** the exam — беспокоюсь. Worrying — «тревожный» (о том, что вызывает)." },
  { id: "v-feel-002", topic: "vocab-feelings-character", type: "choice", q: "She always helps people and gives money to charity. She's very ___.", options: ["generous", "lazy", "shy"], answer: "generous", explain: "Помогает людям, даёт деньги на благотворительность → **generous** (щедрый)." },
  { id: "v-feel-003", topic: "vocab-feelings-character", type: "fill", q: "We're very proud ___ you!", answers: ["of"], explain: "proud **of** — гордиться кем-то." },
  { id: "v-feel-004", topic: "vocab-feelings-character", type: "choice", q: "He never gets angry, even with difficult customers. He's very ___.", options: ["patient", "jealous", "rude"], answer: "patient", explain: "Не злится — **patient** (терпеливый). Jealous — ревнивый, rude — грубый." },
  { id: "v-feel-005", topic: "vocab-feelings-character", type: "translate", q: "Я боюсь собак.", answers: ["I am afraid of dogs.", "I am scared of dogs.", "I am frightened of dogs."], explain: "afraid **of** — бояться чего-то: afraid of dogs." },
  { id: "v-feel-006", topic: "vocab-feelings-character", type: "fix", q: "She is angry on me.", answers: ["She is angry with me.", "She is angry at me."], explain: "angry **with** someone — сердиться на человека (angry about — на что-то)." },

  // ---------- word-formation ----------
  { id: "wf-001", topic: "word-formation", type: "fill", q: "Thanks for the advice, it was very ___.", hint: "use", answers: ["useful"], explain: "use + **-ful** → useful (полезный)." },
  { id: "wf-002", topic: "word-formation", type: "choice", q: "I'm sorry, I ___ what you said.", options: ["misunderstood", "disunderstood", "ununderstood"], answer: "misunderstood", explain: "mis- — «неправильно»: **misunderstood** (понял неверно). Disunderstood не существует." },
  { id: "wf-003", topic: "word-formation", type: "fill", q: "Money doesn't always bring ___.", hint: "happy", answers: ["happiness"], explain: "happy → **happiness** (y → i + ness): после слова bring нужно существительное." },
  { id: "wf-004", topic: "word-formation", type: "choice", q: "This chair is very ___.", options: ["comfortable", "comfortful", "uncomfortful"], answer: "comfortable", explain: "**comfortable** — удобный. Comfortful не существует." },
  { id: "wf-005", topic: "word-formation", type: "fill", q: "It's ___ to park here. You'll get a fine.", hint: "legal", answers: ["illegal"], explain: "il- перед l: **illegal** (незаконный)." },
  { id: "wf-006", topic: "word-formation", type: "choice", q: "We need more ___ about the trip.", options: ["information", "informative", "inform"], answer: "information", explain: "После more нужно существительное: **information** (inform — глагол, informative — прилагательное)." },
  { id: "wf-007", topic: "word-formation", type: "fill", q: "This phone is ___ — it broke after two days!", hint: "use", answers: ["useless"], explain: "use + **-less** → useless (бесполезный). Он сломался за два дня." },

  // --- wf: часть речи по месту в предложении, суффиксы ---
  { id: "wf-008", topic: "word-formation", type: "fill", q: "He has a huge CD ___ of rock albums.", hint: "collect", answers: ["collection"], explain: "После a / the / прилагательного — существительное. collect + ion = collection. «collectioner» не существует." },
  { id: "wf-009", topic: "word-formation", type: "fill", q: "My grandfather is a stamp ___.", hint: "collect", answers: ["collector"], explain: "Нужен человек: collect + or = collector (-or, как в actor, sailor)." },
  { id: "wf-010", topic: "word-formation", type: "fill", q: "She plays the violin in an orchestra — she is a talented ___.", hint: "music", answers: ["musician"], explain: "После a + прилагательное — существительное-человек: music + ian = musician (без h)." },
  { id: "wf-011", topic: "word-formation", type: "fill", q: "The show was very ___, and everybody laughed.", hint: "entertain", answers: ["entertaining"], explain: "После was very — прилагательное: entertaining (занимательный)." },
  { id: "wf-012", topic: "word-formation", type: "fill", q: "Cinemas and theatres are popular forms of ___.", hint: "entertain", answers: ["entertainment"], explain: "После of — существительное: entertain + ment = entertainment." },
  { id: "wf-013", topic: "word-formation", type: "fill", q: "My uncle works as a ___ on a big boat.", hint: "sail", answers: ["sailor"], explain: "Человек, который плавает: sail + or = sailor (не «sailer»)." },
  { id: "wf-014", topic: "word-formation", type: "fill", q: "Mia is a very ___ girl: she runs, swims and plays tennis.", hint: "athlete", answers: ["athletic"], explain: "После very, перед существительным — прилагательное: athletic (спортивный)." },
  { id: "wf-015", topic: "word-formation", type: "fill", q: "Leon is a great ___; his voice is beautiful.", hint: "sing", answers: ["singer"], explain: "Человек: sing + er = singer (не «signer» — это «подписывающий»)." },
  { id: "wf-016", topic: "word-formation", type: "fill", q: "She wants to take part in the singing ___.", hint: "compete", answers: ["competition"], explain: "После the + прилагательное — существительное: compete → competition." },
  { id: "wf-017", topic: "word-formation", type: "fill", q: "There were two hundred ___ in the race.", hint: "compete", answers: ["competitors"], explain: "Люди во множественном числе: competitor + s = competitors." },

  { id: "wf-018", topic: "word-formation", type: "fix", q: "He has a big CD collections.", answers: ["He has a big CD collection."], explain: "После a — существительное в единственном числе: a CD collection." },
  { id: "wf-019", topic: "word-formation", type: "fix", q: "My brother is a stamp collectioner.", answers: ["My brother is a stamp collector."], explain: "collection — уже существительное. Человек: collect + or = collector." },
  { id: "wf-020", topic: "word-formation", type: "fix", q: "She is a famous signer; her songs are on the radio.", answers: ["She is a famous singer; her songs are on the radio."], explain: "singer (sing + er). signer — тот, кто подписывает." },
  { id: "wf-021", topic: "word-formation", type: "fix", q: "He wants to be a professional musichian.", answers: ["He wants to be a professional musician."], explain: "music + ian = musician: буквы h нет." },
  { id: "wf-022", topic: "word-formation", type: "fix", q: "Theatre is a good entertains for children.", answers: ["Theatre is a good entertainment for children.", "Theatre is good entertainment for children."], explain: "После a good нужно существительное: entertainment." },
  { id: "wf-023", topic: "word-formation", type: "fix", q: "The film was entertain, so we laughed a lot.", answers: ["The film was entertaining, so we laughed a lot."], explain: "После was нужно прилагательное: entertaining." },
  { id: "wf-024", topic: "word-formation", type: "fix", q: "She is very athlete and goes running every day.", answers: ["She is very athletic and goes running every day."], explain: "После very нужно прилагательное: athletic. athlete — существительное (спортсмен)." },
  { id: "wf-025", topic: "word-formation", type: "fix", q: "My uncle is a sailer and travels all over the world.", answers: ["My uncle is a sailor and travels all over the world."], explain: "sail + or = sailor." },
  { id: "wf-026", topic: "word-formation", type: "fix", q: "She loves athletic — running and jumping are her favourite sports.", answers: ["She loves athletics — running and jumping are her favourite sports."], explain: "После loves нужно существительное: athletics (лёгкая атлетика). athletic — прилагательное." },
  { id: "wf-027", topic: "word-formation", type: "fix", q: "He plays a music instrument — the piano.", answers: ["He plays a musical instrument — the piano."], explain: "Перед существительным (instrument) нужно прилагательное: musical." },

  { id: "wf-028", topic: "word-formation", type: "choice", q: "Выберите суффикс: guitar + ___ = человек, который играет на гитаре.", options: ["-ist", "-ian", "-ment"], answer: "-ist", explain: "guitar + ist = guitarist (как artist, scientist)." },
  { id: "wf-029", topic: "word-formation", type: "choice", q: "Выберите суффикс: music + ___ = человек, который профессионально занимается музыкой.", options: ["-ian", "-er", "-ment"], answer: "-ian", explain: "music + ian = musician (как electrician)." },
  { id: "wf-030", topic: "word-formation", type: "choice", q: "Выберите суффикс: entertain + ___ = существительное «развлечение».", options: ["-ment", "-ion", "-ful"], answer: "-ment", explain: "entertain + ment = entertainment (как enjoyment, movement)." },
  { id: "wf-031", topic: "word-formation", type: "choice", q: "Выберите суффикс: collect + ___ = существительное «коллекция».", options: ["-ion", "-ment", "-ness"], answer: "-ion", explain: "collect + ion = collection (как action, decoration)." },
  { id: "wf-032", topic: "word-formation", type: "choice", q: "Выберите прилагательное «спортивный»: She is a very ___ person.", options: ["athletic", "athlete", "athletics"], answer: "athletic", explain: "После is a very — прилагательное: athletic." },

  // --- wf: слова из уроков ---
  { id: "wf-033", topic: "word-formation", type: "fill", q: "Her ___ saved the child's life.", hint: "brave", answers: ["bravery"], explain: "После Her — существительное: brave + ery = bravery." },
  { id: "wf-034", topic: "word-formation", type: "fill", q: "Please check your answers and make any ___.", hint: "correct", answers: ["corrections"], explain: "После any — существительное во мн. числе: correct + ion = corrections." },
  { id: "wf-035", topic: "word-formation", type: "fill", q: "Your answer is ___ — try again.", hint: "correct", answers: ["incorrect"], explain: "После is — прилагательное с отрицательной приставкой: incorrect." },
  { id: "wf-036", topic: "word-formation", type: "fix", q: "The divide of the class into groups took five minutes.", answers: ["The division of the class into groups took five minutes."], explain: "После The нужно существительное: divide → division." },
  { id: "wf-037", topic: "word-formation", type: "fill", q: "I can't ___ all these dates.", hint: "memory", answers: ["memorise", "memorize"], explain: "После can't — глагол: memorise (в США memorize)." },
  { id: "wf-038", topic: "word-formation", type: "fix", q: "There is a memory in the park for the soldiers.", answers: ["There is a memorial in the park for the soldiers."], explain: "memory — память; memorial — памятник, мемориал." },
  { id: "wf-039", topic: "word-formation", type: "fill", q: "A good ___ will help you learn to swim.", hint: "instruct", answers: ["instructor"], explain: "Человек: instruct + or = instructor." },
  { id: "wf-040", topic: "word-formation", type: "fix", q: "Read the instruct carefully before you start.", answers: ["Read the instructions carefully before you start.", "Read the instruction carefully before you start."], explain: "После the — существительное: instruction(s)." },
  { id: "wf-041", topic: "word-formation", type: "fill", q: "In ___, the exam room was quiet.", hint: "silent", answers: ["silence"], explain: "После In — существительное: silent → silence." },
  { id: "wf-042", topic: "word-formation", type: "fill", q: "The children listened ___.", hint: "silent", answers: ["silently"], explain: "После глагола — наречие: silent + ly." },
  { id: "wf-043", topic: "word-formation", type: "fill", q: "We need to ___ the rules so that everyone understands.", hint: "simple", answers: ["simplify"], explain: "После to — глагол: simple → simplify." },
  { id: "wf-044", topic: "word-formation", type: "fix", q: "The simple of the design makes it beautiful.", answers: ["The simplicity of the design makes it beautiful."], explain: "После The — существительное: simple → simplicity." },
  { id: "wf-045", topic: "word-formation", type: "fill", q: "Every ___ needs time and patience.", hint: "begin", answers: ["beginner"], explain: "Человек: begin + n + er = beginner." },
  { id: "wf-046", topic: "word-formation", type: "fill", q: "She has a good ___ — she went to a top university.", hint: "educate", answers: ["education"], explain: "После a good — существительное: educate → education." },
  { id: "wf-047", topic: "word-formation", type: "fix", q: "He showed great brave when he saved the dog.", answers: ["He showed great bravery when he saved the dog."], explain: "После great — существительное: bravery." },
  { id: "wf-048", topic: "word-formation", type: "fix", q: "Please make a correct to the third line.", answers: ["Please make a correction to the third line."], explain: "После a — существительное: correction." },
  { id: "wf-049", topic: "word-formation", type: "fix", q: "She works as an instruct at a swimming school.", answers: ["She works as an instructor at a swimming school."], explain: "Человек: instructor." },
  { id: "wf-050", topic: "word-formation", type: "fix", q: "She listened to the music in silent.", answers: ["She listened to the music in silence."], explain: "После in — существительное: silence." },
  { id: "wf-051", topic: "word-formation", type: "fix", q: "I need to simple this explanation.", answers: ["I need to simplify this explanation."], explain: "После to — глагол: simplify." },
  { id: "wf-052", topic: "word-formation", type: "fix", q: "It was the begin of a great friendship.", answers: ["It was the beginning of a great friendship."], explain: "После the — существительное: beginning (n удваивается)." },

  // ---------- vocab-education ----------
  { id: "v-edu-001", topic: "vocab-education", type: "choice", q: "She is very ___ — she solves difficult puzzles quickly.", options: ["clever", "mental", "hesitate"], answer: "clever", explain: "clever — умный, сообразительный." },
  { id: "v-edu-002", topic: "vocab-education", type: "choice", q: "I need to ___ for tomorrow's exam.", options: ["revise", "consider", "wonder"], answer: "revise", explain: "revise — повторять материал (UK)." },
  { id: "v-edu-003", topic: "vocab-education", type: "choice", q: "She worked hard and ___ all her exams with top marks.", options: ["passed", "failed", "missed"], answer: "passed", explain: "Хорошие оценки — значит, сдала успешно: passed. failed — провалила, missed — пропустила." },
  { id: "v-edu-004", topic: "vocab-education", type: "choice", q: "I got a good ___ for my essay.", options: ["mark", "term", "course"], answer: "mark", explain: "mark — оценка." },
  { id: "v-edu-005", topic: "vocab-education", type: "choice", q: "The school ___ said that Tim has made good progress.", options: ["report", "term", "skill"], answer: "report", explain: "school report — табель с отзывом." },
  { id: "v-edu-006", topic: "vocab-education", type: "choice", q: "It's hard to ___ on my work when it's noisy.", options: ["concentrate", "hesitate", "revise"], answer: "concentrate", explain: "concentrate on — сосредоточиться на." },
  { id: "v-edu-007", topic: "vocab-education", type: "choice", q: "If you have questions, don't ___ to ask.", options: ["hesitate", "wonder", "remind"], answer: "hesitate", explain: "don't hesitate to ask — не стесняйтесь спрашивать." },
  { id: "v-edu-008", topic: "vocab-education", type: "choice", q: "I ___ if the shop is open on Sundays.", options: ["wonder", "remind", "achieve"], answer: "wonder", explain: "I wonder if... — «интересно, ...»." },
  { id: "v-edu-009", topic: "vocab-education", type: "fill", q: "She is studying for a ___ in design.", hint: "курс", answers: ["course"], explain: "course — курс обучения." },
  { id: "v-edu-010", topic: "vocab-education", type: "fill", q: "The first ___ of the school year starts in September.", hint: "семестр, четверть", answers: ["term"], explain: "term — учебный семестр, триместр." },
  { id: "v-edu-011", topic: "vocab-education", type: "fill", q: "He has all the right ___ for the job.", hint: "квалификации", answers: ["qualifications"], explain: "qualification — квалификация, диплом." },
  { id: "v-edu-012", topic: "vocab-education", type: "fill", q: "Could you ___ me to call the dentist?", hint: "напомнить", answers: ["remind"], explain: "remind sb to do — напомнить сделать." },
  { id: "v-edu-013", topic: "vocab-education", type: "fill", q: "I'm ___ moving to another city.", hint: "consider (-ing)", answers: ["considering"], explain: "consider + -ing: «обдумываю»." },
  { id: "v-edu-014", topic: "vocab-education", type: "fill", q: "We have ___ a lot of progress this term.", hint: "make", answers: ["made"], explain: "make progress; после have — V3: made." },
  { id: "v-edu-015", topic: "vocab-education", type: "fix", q: "He made an exam yesterday, but he doesn't know the result yet.", answers: ["He took an exam yesterday, but he doesn't know the result yet.", "He took the exam yesterday, but he doesn't know the result yet.", "He sat an exam yesterday, but he doesn't know the result yet."], explain: "Экзамен «сдают» глаголом take (или sit): take an exam. make an exam — «составить экзамен»." },
  { id: "v-edu-016", topic: "vocab-education", type: "fix", q: "I need to concentrate in my homework.", answers: ["I need to concentrate on my homework."], explain: "concentrate on." },
  { id: "v-edu-017", topic: "vocab-education", type: "fix", q: "Don't hesitate asking if you need help.", answers: ["Don't hesitate to ask if you need help.", "Do not hesitate to ask if you need help."], explain: "hesitate to + глагол." },
  { id: "v-edu-018", topic: "vocab-education", type: "fix", q: "You've all make a lot of progress.", answers: ["You've all made a lot of progress.", "You have all made a lot of progress."], explain: "После have — V3: made." },
  { id: "v-edu-019", topic: "vocab-education", type: "fix", q: "The teacher gave me a good note for my essay.", answers: ["The teacher gave me a good mark for my essay.", "The teacher gave me a good grade for my essay."], explain: "Оценка — mark (в США grade); note — заметка." },
  { id: "v-edu-020", topic: "vocab-education", type: "fix", q: "I wonder that the library is open.", answers: ["I wonder if the library is open.", "I wonder whether the library is open."], explain: "I wonder if / whether — «интересно, ...»." },
  { id: "v-edu-021", topic: "vocab-education", type: "fix", q: "I have a lot of experiences in teaching.", answers: ["I have a lot of experience in teaching."], explain: "experience (опыт) — неисчисляемое." },
  { id: "v-edu-022", topic: "vocab-education", type: "fix", q: "We should consider to move to another city.", answers: ["We should consider moving to another city."], explain: "consider + -ing." },
  { id: "v-edu-023", topic: "vocab-education", type: "translate", q: "Мне нужно повторить материал к экзамену.", answers: ["I need to revise for the exam.", "I need to revise for my exam.", "I have to revise for the exam.", "I have to revise for my exam.", "I need to revise for the test.", "I have to revise for the test."], explain: "revise for the exam — готовиться, повторяя материал." },
  { id: "v-edu-024", topic: "vocab-education", type: "translate", q: "Не стесняйтесь спрашивать.", answers: ["Don't hesitate to ask.", "Do not hesitate to ask.", "Please don't hesitate to ask.", "Please do not hesitate to ask."], explain: "don't hesitate to ask." },
  { id: "v-edu-025", topic: "vocab-education", type: "translate", q: "Мне интересно, который час.", answers: ["I wonder what time it is.", "I wonder what the time is."], explain: "I wonder + косвенный вопрос (порядок слов как в утверждении)." },

  // ---------- confusing-words ----------
  { id: "conf-001", topic: "confusing-words", type: "choice", q: "Can I ___ your pen?", options: ["borrow", "lend"], answer: "borrow", explain: "**borrow** — взять на время; lend — дать на время. Can I borrow your pen?" },
  { id: "conf-002", topic: "confusing-words", type: "choice", q: "He ___ me a funny story.", options: ["told", "said"], answer: "told", explain: "**told** me a story: tell + кому. Said me — неверно." },
  { id: "conf-003", topic: "confusing-words", type: "fill", q: "Hurry up or we'll ___ the bus!", answers: ["miss"], explain: "**miss** the bus — опоздать на автобус (lose — потерять)." },
  { id: "conf-004", topic: "confusing-words", type: "fix", q: "Can you remember me to buy milk?", answers: ["Can you remind me to buy milk?"], explain: "remind — напоминать." },
  { id: "conf-005", topic: "confusing-words", type: "choice", q: "The party was great ___! We danced all night.", options: ["fun", "funny"], answer: "fun", explain: "fun — весело, приятно; funny — смешной." },
  { id: "conf-006", topic: "confusing-words", type: "translate", q: "Я скучаю по тебе.", answers: ["I miss you."], explain: "**miss** you — скучать по тебе." },
  { id: "conf-007", topic: "confusing-words", type: "choice", q: "Please ___ your passport when you come to our office.", options: ["bring", "take"], answer: "bring", explain: "bring — принести сюда, к говорящему." },

  // ---------- future-forms ----------
  { id: "ff-001", topic: "future-forms", type: "choice", q: "Careful! The ladder ___.", options: ["is going to fall", "falls", "fall"], answer: "is going to fall", explain: "Видим признак прямо сейчас (лестница шатается) — предсказание по признакам: be going to." },
  { id: "ff-002", topic: "future-forms", type: "choice", q: "According to the timetable, our train ___ at 7.40.", options: ["leaves", "leave", "is leave"], answer: "leaves", explain: "Расписание — Present Simple; с it/train глагол получает -s: leaves." },
  { id: "ff-003", topic: "future-forms", type: "choice", q: "We have run out of bread. — OK, I ___ some.", options: ["will buy", "am buying", "buys"], answer: "will buy", explain: "Решение принято прямо в момент речи — will." },
  { id: "ff-004", topic: "future-forms", type: "choice", q: "Dan has bought the tickets, so on Saturday he ___ to Paris.", options: ["is flying", "flies", "will fly"], answer: "is flying", explain: "Билеты куплены — это договорённость: Present Continuous. will для договорённостей не подходит." },
  { id: "ff-005", topic: "future-forms", type: "choice", q: "I've decided: when I'm older, I ___ a vet.", options: ["am going to become", "am becoming", "become"], answer: "am going to become", explain: "Намерение, план на жизнь — be going to. Present Continuous нужен для договорённостей, не для намерений." },
  { id: "ff-006", topic: "future-forms", type: "choice", q: "___ I carry your bag? It looks heavy.", options: ["Shall", "Will", "Do"], answer: "Shall", explain: "Shall I… — предлагаем помощь или спрашиваем «как лучше?»." },
  { id: "ff-007", topic: "future-forms", type: "choice", q: "The film ___ at eight, so please don't be late.", options: ["starts", "start", "will starting"], answer: "starts", explain: "Программа, расписание — Present Simple: the film starts." },
  { id: "ff-008", topic: "future-forms", type: "choice", q: "I think it ___ warm next week.", options: ["will be", "is being", "be"], answer: "will be", explain: "Мнение, предсказание после I think — will; «будет» = will be." },
  { id: "ff-009", topic: "future-forms", type: "fill", q: "Используй Present Continuous. Jack ___ his cousin on Sunday; they have agreed on the time.", answers: ["is meeting", "'s meeting", "is seeing", "'s seeing"], hint: "meet", explain: "Договорённость — Present Continuous: is meeting." },
  { id: "ff-010", topic: "future-forms", type: "fill", q: "Используй Present Simple. The concert ___ at 7.30 p.m.", answers: ["begins", "starts"], hint: "begin", explain: "Расписание — Present Simple, с it -s: begins / starts." },
  { id: "ff-011", topic: "future-forms", type: "fill", q: "Используй be going to. We ___ the kitchen yellow this summer; we have already bought the paint.", answers: ["are going to paint", "'re going to paint"], hint: "paint", explain: "План, который уже решён — be going to + глагол." },
  { id: "ff-012", topic: "future-forms", type: "fill", q: "Используй will. It's cold in here. I ___ the window.", answers: ["will close", "'ll close", "shall close"], hint: "close", explain: "Решение в момент речи — will." },
  { id: "ff-013", topic: "future-forms", type: "fill", q: "Используй Present Continuous. ___ Lisa coming to the party on Friday?", answers: ["Is"], hint: "be", explain: "Вопрос в Present Continuous: Is + подлежащее + -ing." },
  { id: "ff-014", topic: "future-forms", type: "fill", q: "Используй Present Simple. Our flight ___ Madrid at 6.15 a.m.", answers: ["leaves"], hint: "leave", explain: "Расписание рейса — Present Simple: leaves." },
  { id: "ff-015", topic: "future-forms", type: "fill", q: "Используй be going to. Look at the sky! It ___ soon.", answers: ["is going to rain", "'s going to rain"], hint: "rain", explain: "Видим тучи — предсказание по признакам: is going to rain." },
  { id: "ff-016", topic: "future-forms", type: "fill", q: "Используй will (отрицание). Don't worry, I ___ anyone your secret.", answers: ["won't tell", "will not tell"], hint: "tell", explain: "Обещание — will; отрицание won't." },
  { id: "ff-017", topic: "future-forms", type: "fill", q: "Используй Present Continuous (отрицание). We ___ to the cinema tonight; we're staying in.", answers: ["aren't going", "are not going", "'re not going"], hint: "go", explain: "Отрицание Present Continuous: aren't going." },
  { id: "ff-018", topic: "future-forms", type: "fill", q: "Используй Present Simple (отрицание). The bank ___ on Sundays.", answers: ["doesn't open", "does not open"], hint: "open", explain: "Отрицание в Present Simple: doesn't + глагол без -s." },
  { id: "ff-019", topic: "future-forms", type: "fix", q: "My plane will leave at nine tomorrow morning.", answers: ["My plane leaves at nine tomorrow morning.", "My plane is leaving at nine tomorrow morning."], explain: "Рейс по расписанию — Present Simple: leaves (will здесь не нужен)." },
  { id: "ff-020", topic: "future-forms", type: "fix", q: "The museum will open at ten and will close at five.", answers: ["The museum opens at ten and closes at five."], explain: "Часы работы — это расписание: Present Simple." },
  { id: "ff-021", topic: "future-forms", type: "fix", q: "We will visit my grandma this weekend; Dad has already bought the tickets.", answers: ["We are visiting my grandma this weekend; Dad has already bought the tickets.", "We're visiting my grandma this weekend; Dad has already bought the tickets.", "We are going to visit my grandma this weekend; Dad has already bought the tickets."], explain: "Билеты уже куплены — договорённость: Present Continuous (are visiting)." },
  { id: "ff-022", topic: "future-forms", type: "fix", q: "I'm becoming an explorer when I grow up.", answers: ["I'm going to become an explorer when I grow up.", "I am going to become an explorer when I grow up.", "I'm going to be an explorer when I grow up.", "I am going to be an explorer when I grow up."], explain: "Намерение — be going to. Present Continuous для намерений («когда вырасту») не используют." },
  { id: "ff-023", topic: "future-forms", type: "fix", q: "She will meet her dentist at 4.30 tomorrow; it's in her diary.", answers: ["She is meeting her dentist at 4.30 tomorrow; it's in her diary.", "She is seeing her dentist at 4.30 tomorrow; it's in her diary.", "She is going to meet her dentist at 4.30 tomorrow; it's in her diary."], explain: "Запись в дневнике — договорённость: is meeting (Present Continuous)." },
  { id: "ff-024", topic: "future-forms", type: "fix", q: "The train is going to leave at 8.15 every morning.", answers: ["The train leaves at 8.15 every morning."], explain: "«Каждое утро по расписанию» — Present Simple." },
  { id: "ff-025", topic: "future-forms", type: "fix", q: "I'm going to shopping on Saturday.", answers: ["I'm going shopping on Saturday.", "I am going shopping on Saturday.", "I'm going to go shopping on Saturday.", "I am going to go shopping on Saturday."], explain: "go shopping — без to: going shopping." },
  { id: "ff-026", topic: "future-forms", type: "fix", q: "They are going to swimming tomorrow.", answers: ["They are going swimming tomorrow.", "They are going to go swimming tomorrow."], explain: "go + занятие на -ing — без to: go swimming." },
  { id: "ff-027", topic: "future-forms", type: "fix", q: "There won't any tickets left on Friday.", answers: ["There won't be any tickets left on Friday.", "There will not be any tickets left on Friday."], explain: "there won't be — be нельзя терять." },
  { id: "ff-028", topic: "future-forms", type: "fix", q: "I think there will no problem with the bus.", answers: ["I think there will be no problem with the bus.", "I think there won't be any problem with the bus.", "I think there won't be any problems with the bus."], explain: "there will be — be нужен." },
  { id: "ff-029", topic: "future-forms", type: "fix", q: "Look at those clouds! It will rain.", answers: ["Look at those clouds! It is going to rain.", "Look at those clouds! It's going to rain."], explain: "Предсказание по видимым признакам — be going to." },
  { id: "ff-030", topic: "future-forms", type: "fix", q: "Be careful! You will drop the glasses!", answers: ["Be careful! You are going to drop the glasses!", "Be careful! You're going to drop the glasses!"], explain: "Опасность прямо сейчас видна — be going to." },
  { id: "ff-031", topic: "future-forms", type: "fix", q: "The phone is ringing. I'm going to answer it.", answers: ["The phone is ringing. I'll answer it.", "The phone is ringing. I will answer it."], explain: "Решение в момент речи — will, а не going to." },
  { id: "ff-032", topic: "future-forms", type: "fix", q: "Do I carry your bag?", answers: ["Shall I carry your bag?", "Can I carry your bag?", "Should I carry your bag?"], explain: "Предлагая помощь, говорим Shall I…?" },
  { id: "ff-033", topic: "future-forms", type: "fix", q: "Does the film begins at eight tonight?", answers: ["Does the film begin at eight tonight?"], explain: "После does глагол без -s." },
  { id: "ff-034", topic: "future-forms", type: "fix", q: "He isn't going to goes to the party.", answers: ["He isn't going to go to the party.", "He's not going to go to the party."], explain: "После going to — глагол без -s: to go." },
  { id: "ff-035", topic: "future-forms", type: "translate", q: "У меня встреча с врачом завтра в девять.", answers: ["I'm seeing the doctor at nine tomorrow.", "I'm seeing the doctor tomorrow at nine.", "I'm meeting the doctor at nine tomorrow.", "I have an appointment with the doctor at nine tomorrow.", "I have an appointment with the doctor tomorrow at nine."], explain: "Договорённость — Present Continuous: I'm seeing…" },
  { id: "ff-036", topic: "future-forms", type: "translate", q: "Поезд в Казань отправляется в шесть утра.", answers: ["The train to Kazan leaves at six in the morning.", "The train to Kazan leaves at six a.m.", "The train to Kazan leaves at 6 a.m."], explain: "Расписание — Present Simple." },
  { id: "ff-037", topic: "future-forms", type: "translate", q: "Я собираюсь стать исследователем, когда вырасту.", answers: ["I'm going to become an explorer when I grow up.", "I'm going to be an explorer when I grow up.", "I am going to become an explorer when I grow up.", "I am going to be an explorer when I grow up."], explain: "Намерение — be going to; после when — настоящее время (grow up)." },
  { id: "ff-038", topic: "future-forms", type: "translate", q: "Осторожно, ты сейчас упадёшь!", answers: ["Be careful, you're going to fall!", "Careful! You're going to fall!", "Watch out! You're going to fall!", "Be careful! You are going to fall!", "Look out! You're going to fall!"], explain: "Признаки видны сейчас — be going to." },
  { id: "ff-039", topic: "future-forms", type: "translate", q: "В субботу мы идём по магазинам.", answers: ["We're going shopping on Saturday.", "On Saturday we're going shopping.", "We are going shopping on Saturday.", "On Saturday we are going shopping."], explain: "Договорённость — Present Continuous; go shopping без to." },
  { id: "ff-040", topic: "future-forms", type: "translate", q: "Завтра я не иду в школу.", answers: ["I'm not going to school tomorrow.", "I am not going to school tomorrow.", "Tomorrow I'm not going to school.", "Tomorrow I am not going to school."], explain: "Договорённость (завтра выходной) — Present Continuous. Здесь to нужен: school — место." },

  // ---------- phrasal-verbs-common (доп.) ----------
  { id: "phr-041", topic: "phrasal-verbs-common", type: "fill", q: "Simon ___ out the wrong answer with an eraser.", answers: ["rubbed"], hint: "r…  (стёр ластиком)", explain: "rub out — стереть ластиком." },
  { id: "phr-042", topic: "phrasal-verbs-common", type: "fix", q: "She ripped down the letter and threw it away.", answers: ["She ripped up the letter and threw it away.", "She ripped the letter up and threw it away."], explain: "rip up — разорвать на куски." },
  { id: "phr-043", topic: "phrasal-verbs-common", type: "fill", q: "Please ___ out all the wrong words.", answers: ["cross"], hint: "c…  (зачеркните)", explain: "cross out — зачеркнуть." },
  { id: "phr-044", topic: "phrasal-verbs-common", type: "fill", q: "If you don't know a word, ___ it up in a dictionary.", answers: ["look"], hint: "l…  (найди в словаре)", explain: "look up — найти в словаре." },
  { id: "phr-045", topic: "phrasal-verbs-common", type: "fill", q: "The teacher ___ out the names of the winners.", answers: ["read"], hint: "r…  (зачитала вслух)", explain: "read out — прочитать вслух." },
  { id: "phr-046", topic: "phrasal-verbs-common", type: "fix", q: "He pointed up a mistake in my essay.", answers: ["He pointed out a mistake in my essay.", "He pointed a mistake out in my essay."], explain: "point out — указать, обратить внимание." },
  { id: "phr-047", topic: "phrasal-verbs-common", type: "fill", q: "___ down the address before you forget it.", answers: ["Write"], hint: "w…  (запиши)", explain: "write down — записать." },
  { id: "phr-048", topic: "phrasal-verbs-common", type: "fix", q: "He crossed the wrong word up.", answers: ["He crossed the wrong word out.", "He crossed out the wrong word."], explain: "cross out — зачеркнуть." },
  { id: "phr-049", topic: "phrasal-verbs-common", type: "fix", q: "Write down it, please.", answers: ["Write it down, please."], explain: "С местоимением частица идёт после него: write it down." },
  { id: "phr-050", topic: "phrasal-verbs-common", type: "fix", q: "She rubbed up the mistake with an eraser.", answers: ["She rubbed out the mistake with an eraser.", "She rubbed the mistake out with an eraser."], explain: "rub out — стереть." },
  { id: "phr-051", topic: "phrasal-verbs-common", type: "fix", q: "She read down the results to the class.", answers: ["She read out the results to the class.", "She read the results out to the class."], explain: "read out — прочитать вслух." },
  { id: "phr-052", topic: "phrasal-verbs-common", type: "translate", q: "Он зачеркнул неправильный ответ.", answers: ["He crossed out the wrong answer.", "He crossed the wrong answer out.", "He crossed out the incorrect answer.", "He crossed the incorrect answer out."], explain: "cross out — зачеркнуть." },
  { id: "phr-053", topic: "phrasal-verbs-common", type: "translate", q: "Запиши номер телефона.", answers: ["Write down the phone number.", "Write the phone number down.", "Write down the telephone number.", "Write the telephone number down."], explain: "write down — записать." },
  { id: "phr-054", topic: "phrasal-verbs-common", type: "translate", q: "Найди это слово в словаре.", answers: ["Look the word up in the dictionary.", "Look up the word in the dictionary.", "Look this word up in the dictionary.", "Look up this word in the dictionary.", "Look the word up in a dictionary.", "Look up the word in a dictionary."], explain: "look up — найти в словаре." },

  // ---------- word-formation (доп.) ----------
  { id: "wf-053", topic: "word-formation", type: "fill", q: "My piano ___ is very patient.", answers: ["instructor"], hint: "instruct", explain: "Человек — суффикс -or: instructor." },
  { id: "wf-054", topic: "word-formation", type: "choice", q: "He's a ___ at tennis; he started last week.", options: ["beginner", "beginning", "begin"], answer: "beginner", explain: "Человек — beginner (n удваивается)." },
  { id: "wf-055", topic: "word-formation", type: "fill", q: "Her dream is to become a professional ___.", answers: ["musician"], hint: "music", explain: "Человек: music → musician (-ian)." },
  { id: "wf-056", topic: "word-formation", type: "fill", q: "The room was in complete ___.", answers: ["silence"], hint: "silent", explain: "Существительное: silent → silence." },
  { id: "wf-057", topic: "word-formation", type: "fill", q: "Please read the ___ before you start.", answers: ["instructions", "instruction"], hint: "instruct", explain: "Существительное: instruct → instruction." },
  { id: "wf-058", topic: "word-formation", type: "fill", q: "The ___ of 12 by 3 is 4.", answers: ["division"], hint: "divide", explain: "divide → division." },
  { id: "wf-059", topic: "word-formation", type: "fill", q: "The firefighter was given a medal for her ___.", answers: ["bravery"], hint: "brave", explain: "brave → bravery (-ery)." },
  { id: "wf-060", topic: "word-formation", type: "fix", q: "My guitar instructer is Spanish.", answers: ["My guitar instructor is Spanish."], explain: "Человек — суффикс -or: instructor." },
  { id: "wf-061", topic: "word-formation", type: "fix", q: "She is a famous musichian.", answers: ["She is a famous musician."], explain: "musician — без h." },
  { id: "wf-062", topic: "word-formation", type: "fix", q: "He walked away silencely.", answers: ["He walked away silently."], explain: "Наречие от silent — silently." },

  // ---------- vocab-education (доп.) ----------
  { id: "v-edu-026", topic: "vocab-education", type: "choice", q: "The driving ___ taught me how to park.", options: ["instructor", "instruction", "instructions"], answer: "instructor", explain: "Человек, который учит, — instructor." },
  { id: "v-edu-027", topic: "vocab-education", type: "fix", q: "Our swimming instructer is very kind.", answers: ["Our swimming instructor is very kind."], explain: "instructor — окончание -or." },
  { id: "v-edu-028", topic: "vocab-education", type: "fill", q: "The teacher asked for ___ so that everyone could hear the story.", answers: ["silence"], hint: "silent", explain: "silence — тишина." },
  { id: "v-edu-029", topic: "vocab-education", type: "choice", q: "The students listened ___ to the instructor.", options: ["silently", "silence", "silent"], answer: "silently", explain: "Наречие после глагола: silently." },
  { id: "v-edu-030", topic: "vocab-education", type: "translate", q: "Инструктор показал нам, как это делать.", answers: ["The instructor showed us how to do it.", "The instructor showed us how to do this.", "The instructor showed us how to do that."], explain: "instructor — инструктор." },

  // ---------- phrasal-verbs-common: в дорогу (get in/on/off/out, go away/back, set off, take off) ----------
  { id: "phr-055", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: The man ___ (get in) his car and drove away.", answers: ["got in"], hint: "get in", explain: "Past Simple: get → got, частица in остаётся: got in." },
  { id: "phr-056", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: We ran to the train and ___ (get on).", answers: ["got on"], hint: "get on", explain: "В поезд — get on; в прошедшем: got on." },
  { id: "phr-057", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: Last night our plane ___ (take off) twenty minutes late.", answers: ["took off"], hint: "take off", explain: "take → took: took off." },
  { id: "phr-058", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: They ___ (set off) before sunrise.", answers: ["set off"], hint: "set off", explain: "set — неправильный глагол, V2 не меняется: set off." },
  { id: "phr-059", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: After the holiday we ___ (go back) to work.", answers: ["went back"], hint: "go back", explain: "go → went: went back." },
  { id: "phr-060", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: She ___ (get out) of the taxi and paid the driver.", answers: ["got out"], hint: "get out", explain: "get out of the taxi — выйти из такси; got out." },
  { id: "phr-061", topic: "phrasal-verbs-common", type: "fix", q: "The man get in his car and drove to the harbour.", answers: ["The man got in his car and drove to the harbour."], explain: "Рассказ о прошлом: get → got (drove уже в прошедшем)." },
  { id: "phr-062", topic: "phrasal-verbs-common", type: "fix", q: "We ran to the train and get on just in time.", answers: ["We ran to the train and got on just in time."], explain: "ran — прошедшее, значит и get on → got on." },
  { id: "phr-063", topic: "phrasal-verbs-common", type: "fix", q: "My neighbours go away last weekend.", answers: ["My neighbours went away last weekend."], explain: "last weekend — прошлое: go → went away." },
  { id: "phr-064", topic: "phrasal-verbs-common", type: "fix", q: "The plane take off at nine o'clock last night.", answers: ["The plane took off at nine o'clock last night.", "The plane took off at 9 o'clock last night."], explain: "last night — прошлое: take → took off." },
  { id: "phr-065", topic: "phrasal-verbs-common", type: "fix", q: "Did you got off at the right stop?", answers: ["Did you get off at the right stop?"], explain: "После did глагол в начальной форме: Did you get off…?" },
  { id: "phr-066", topic: "phrasal-verbs-common", type: "translate", q: "Мы вышли из автобуса и пошли пешком.", answers: ["We got off the bus and walked.", "We got off the bus and went on foot.", "We got off the bus and walked there."], explain: "got off the bus — вышли из автобуса (Past Simple)." },

  // ---------- word-formation: «Going abroad» (часть речи по контексту) ----------
  { id: "wf-063", topic: "word-formation", type: "fill", q: "We have never ___ over the Alps before.", hint: "fly", answers: ["flown"], explain: "После have never — V3: fly → flown." },
  { id: "wf-064", topic: "word-formation", type: "fill", q: "The old town is very ___, with colourful houses and narrow streets.", hint: "attract", answers: ["attractive"], explain: "После very, is — прилагательное: attractive." },
  { id: "wf-065", topic: "word-formation", type: "fill", q: "Choosing a hotel was difficult because there was too much ___.", hint: "choose", answers: ["choice"], explain: "После much — существительное: choice." },
  { id: "wf-066", topic: "word-formation", type: "fill", q: "Yesterday my father ___ for six hours without a rest.", hint: "drive", answers: ["drove"], explain: "Yesterday — Past Simple: drive → drove." },
  { id: "wf-067", topic: "word-formation", type: "fill", q: "Hotel ___ must leave their rooms by eleven.", hint: "visit", answers: ["visitors"], explain: "Люди, множественное число: visitor + s." },
  { id: "wf-068", topic: "word-formation", type: "fill", q: "Most of the ___ on the train were students from Poland.", hint: "travel", answers: ["travellers", "travelers"], explain: "Люди, множественное число: traveller + s (в США — traveler)." },
  { id: "wf-069", topic: "word-formation", type: "fill", q: "The seats on the old bus were hard and very ___.", hint: "comfort", answers: ["uncomfortable"], explain: "Hard и very — значит неудобные: un + comfortable." },
  { id: "wf-070", topic: "word-formation", type: "fill", q: "The ___ time is 8.15, so please arrive early.", hint: "depart", answers: ["departure"], explain: "Перед time — существительное: departure." },
  { id: "wf-071", topic: "word-formation", type: "fill", q: "He drove the car ___ out of the garage.", hint: "back", answers: ["backwards", "backward"], explain: "После глагола — наречие: backwards." },
  { id: "wf-072", topic: "word-formation", type: "fill", q: "We got lost and had to ask for ___.", hint: "direct", answers: ["directions"], explain: "После for — существительное, чаще во множественном числе: directions." },
  { id: "wf-073", topic: "word-formation", type: "fill", q: "A famous tourist ___ in the city is the old castle.", hint: "attract", answers: ["attraction"], explain: "После tourist — существительное: attraction." },
  { id: "wf-074", topic: "word-formation", type: "fix", q: "It was a long fly from Moscow to Bangkok.", answers: ["It was a long flight from Moscow to Bangkok."], explain: "После a long — существительное: flight." },
  { id: "wf-075", topic: "word-formation", type: "fix", q: "My uncle is a bus drive.", answers: ["My uncle is a bus driver."], explain: "Профессия, человек: drive + r = driver." },
  { id: "wf-076", topic: "word-formation", type: "fix", q: "I had to choose between two hotels, but it was an easy choose.", answers: ["I had to choose between two hotels, but it was an easy choice."], explain: "После an easy — существительное: choice." },
  { id: "wf-077", topic: "word-formation", type: "fix", q: "The beach is very attraction, so it is always full.", answers: ["The beach is very attractive, so it is always full.", "The beach is very attractive, so it's always full."], explain: "После very — прилагательное: attractive." },
  { id: "wf-078", topic: "word-formation", type: "fix", q: "The room was noisy and the bed was hard, so it was very comfortable.", answers: ["The room was noisy and the bed was hard, so it was very uncomfortable."], explain: "По смыслу нужно отрицание: uncomfortable (приставка un-)." },
  { id: "wf-079", topic: "word-formation", type: "fix", q: "The tourist asked for direct to the station.", answers: ["The tourist asked for directions to the station."], explain: "После for — существительное: directions." },
  { id: "wf-080", topic: "word-formation", type: "fix", q: "Please check the depart time on your ticket.", answers: ["Please check the departure time on your ticket."], explain: "Перед time — существительное: departure." },
  { id: "wf-081", topic: "word-formation", type: "fix", q: "Many visit come to the island in summer.", answers: ["Many visitors come to the island in summer."], explain: "Many + люди во мн. числе: visitors." },
  { id: "wf-082", topic: "word-formation", type: "fix", q: "Two travel from Canada sat next to us on the plane.", answers: ["Two travellers from Canada sat next to us on the plane.", "Two travelers from Canada sat next to us on the plane."], explain: "Two + человек: travellers (мн. число)." },
  { id: "wf-083", topic: "word-formation", type: "fix", q: "We flown to Rome last Saturday.", answers: ["We flew to Rome last Saturday."], explain: "Last Saturday — Past Simple: flew. Flown — только с have/has." },
  { id: "wf-084", topic: "word-formation", type: "choice", q: "We booked a ___ from Paris to Cairo.", options: ["flight", "flew", "flown"], answer: "flight", explain: "После a — существительное: flight." },
  { id: "wf-085", topic: "word-formation", type: "choice", q: "She ___ the red dress because it was cheaper.", options: ["chose", "choice", "chosen"], answer: "chose", explain: "Past Simple: choose → chose. Chosen — только с have/was." },
  { id: "wf-086", topic: "word-formation", type: "choice", q: "The hotel has a very ___ view of the harbour.", options: ["attractive", "attraction", "attract"], answer: "attractive", explain: "Перед существительным view — прилагательное." },
  { id: "wf-087", topic: "word-formation", type: "translate", q: "Время отправления — девять часов.", answers: ["The departure time is nine o'clock.", "The departure time is 9 o'clock.", "The departure time is nine.", "The departure time is 9.", "Departure time is nine o'clock."], explain: "departure time — время отправления." },

  // ---------- passive-present-past: Unit 10 (be + V3; present / past / will; отрицание, вопрос, фразовые) ----------
  // Ступени: 1) только форма 2) выбор времени 3) отрицание 4) вопрос 5) актив → пассив 6) ошибки 7) фразовые глаголы 8) перевод
  { id: "pass-016", topic: "passive-present-past", type: "fill", q: "Используй Present Simple (пассив): Spanish ___ in Mexico. (speak)", answers: ["is spoken"], explain: "Present Simple пассив: is/are + V3. Spanish — одно, значит is; speak → spoken." },
  { id: "pass-017", topic: "passive-present-past", type: "fill", q: "Используй Present Simple (пассив): These cars ___ in Germany. (make)", answers: ["are made"], explain: "Cars — много, значит are; make → made." },
  { id: "pass-018", topic: "passive-present-past", type: "fill", q: "Используй Present Simple (пассив): Our streets ___ every night. (clean)", answers: ["are cleaned"], explain: "Streets — много: are + cleaned (-ed)." },
  { id: "pass-019", topic: "passive-present-past", type: "choice", q: "Milk ___ in the fridge.", options: ["is kept", "keeps", "are kept"], answer: "is kept", explain: "Молоко «хранят» — пассив; milk — одно, значит is kept." },
  { id: "pass-020", topic: "passive-present-past", type: "choice", q: "Tourists ___ to the island by boat.", options: ["are taken", "take", "is taken"], answer: "are taken", explain: "Туристов «возят» — пассив; tourists — много: are taken." },
  { id: "pass-021", topic: "passive-present-past", type: "fill", q: "Используй Past Simple (пассив): The window ___ by a ball. (break)", answers: ["was broken"], explain: "Past Simple пассив: was/were + V3. break → broken (не broke!)." },
  { id: "pass-022", topic: "passive-present-past", type: "fill", q: "Используй Past Simple (пассив): These photos ___ last summer. (take)", answers: ["were taken"], explain: "Photos — много: were; take → taken." },
  { id: "pass-023", topic: "passive-present-past", type: "fill", q: "Используй Past Simple (пассив): The thief ___ by the police yesterday. (catch)", answers: ["was caught"], explain: "catch → caught (V2 и V3 совпадают)." },
  { id: "pass-024", topic: "passive-present-past", type: "fill", q: "Используй Past Simple (пассив): These letters ___ in 1990. (write)", answers: ["were written"], explain: "Letters — много: were; write → written." },
  { id: "pass-025", topic: "passive-present-past", type: "choice", q: "My wallet ___ on the bus.", options: ["was stolen", "stole", "were stolen"], answer: "was stolen", explain: "Кошелёк «украли» — пассив; wallet — одно: was stolen." },
  { id: "pass-026", topic: "passive-present-past", type: "choice", q: "All the tickets ___ last week.", options: ["were sold", "was sold", "sold"], answer: "were sold", explain: "Tickets — много: were; sell → sold." },
  { id: "pass-027", topic: "passive-present-past", type: "fill", q: "Используй will (пассив): The results ___ tomorrow. (announce)", answers: ["will be announced"], explain: "will + be + V3. После will всегда be." },
  { id: "pass-028", topic: "passive-present-past", type: "fill", q: "Используй will (пассив): The party ___ next Friday. (hold)", answers: ["will be held"], explain: "hold → held; will be held." },
  { id: "pass-029", topic: "passive-present-past", type: "choice", q: "Dinner ___ at eight.", options: ["will be served", "will serve", "will served"], answer: "will be served", explain: "Ужин «подадут» — пассив: will be served." },
  { id: "pass-030", topic: "passive-present-past", type: "fix", q: "The guests will invited to the wedding.", answers: ["The guests will be invited to the wedding."], explain: "После will пропущено be: will be invited." },
  { id: "pass-031", topic: "passive-present-past", type: "choice", q: "Yesterday my car ___ .", options: ["was repaired", "is repaired", "will be repaired"], answer: "was repaired", explain: "Yesterday — прошлое: was + V3." },
  { id: "pass-032", topic: "passive-present-past", type: "choice", q: "Every year thousands of cars ___ here.", options: ["are made", "were made", "will be made"], answer: "are made", explain: "Every year — привычное повторяющееся: Present Simple (are)." },
  { id: "pass-033", topic: "passive-present-past", type: "choice", q: "Next week the road ___ .", options: ["will be closed", "was closed", "is closed"], answer: "will be closed", explain: "Next week — будущее: will be + V3." },
  { id: "pass-034", topic: "passive-present-past", type: "fill", q: "Используй Present Simple, отрицание (пассив): Smoking ___ here. (allow)", answers: ["is not allowed"], explain: "Отрицание: be + not + V3: isn't allowed. Без do!" },
  { id: "pass-035", topic: "passive-present-past", type: "fill", q: "Используй Past Simple, отрицание (пассив): The door ___ last night. (lock)", answers: ["was not locked"], explain: "wasn't + V3: The door wasn't locked." },
  { id: "pass-036", topic: "passive-present-past", type: "fill", q: "Используй will, отрицание (пассив): The neighbours ___ to the party. (invite)", answers: ["will not be invited"], explain: "won't be + V3: The neighbours won't be invited." },
  { id: "pass-037", topic: "passive-present-past", type: "fix", q: "The bike didn't stolen.", answers: ["The bike wasn't stolen.", "The bike was not stolen."], explain: "В пассиве нет did: отрицание делает be — wasn't stolen." },
  { id: "pass-038", topic: "passive-present-past", type: "translate", q: "Эти телефоны не производят в России.", answers: ["These phones aren't made in Russia.", "These phones are not made in Russia."], explain: "are not made — отрицание через be, без do." },
  { id: "pass-039", topic: "passive-present-past", type: "choice", q: "___ everyone invited to the party?", options: ["Is", "Does", "Did"], answer: "Is", explain: "Вопрос в пассиве: be вперёд — Is everyone invited?" },
  { id: "pass-040", topic: "passive-present-past", type: "fill", q: "___ these photos taken in Rome last year?", answers: ["Were"], explain: "Past Simple, photos — много: Were these photos taken…?" },
  { id: "pass-041", topic: "passive-present-past", type: "fix", q: "Did Simon invited to the party?", answers: ["Was Simon invited to the party?"], explain: "Вопрос в пассиве: Was + подлежащее + V3. Did не нужен." },
  { id: "pass-042", topic: "passive-present-past", type: "translate", q: "Саймона пригласили?", answers: ["Was Simon invited?"], explain: "Was вперёд + V3." },
  { id: "pass-043", topic: "passive-present-past", type: "choice", q: "___ the neighbours be invited?", options: ["Will", "Are", "Do"], answer: "Will", explain: "Вопрос с will: Will + подлежащее + be + V3." },
  { id: "pass-044", topic: "passive-present-past", type: "fix", q: "Сделай пассив: They invited Uncle Adrian.", answers: ["Uncle Adrian was invited."], explain: "Объект (Uncle Adrian) вперёд; invited — Past → was; V3 = invited. «They» выбрасываем." },
  { id: "pass-045", topic: "passive-present-past", type: "fix", q: "Сделай пассив: They always invite Grandma.", answers: ["Grandma is always invited."], explain: "invite — Present: is; always стоит между be и V3." },
  { id: "pass-046", topic: "passive-present-past", type: "fix", q: "Сделай пассив: They will invite the neighbours.", answers: ["The neighbours will be invited."], explain: "will invite → will be invited." },
  { id: "pass-047", topic: "passive-present-past", type: "fix", q: "Сделай пассив: People speak English in many countries.", answers: ["English is spoken in many countries."], explain: "People (неизвестно кто) выбрасываем; speak → is spoken." },
  { id: "pass-048", topic: "passive-present-past", type: "fix", q: "Сделай пассив: Someone broke the window.", answers: ["The window was broken."], explain: "Someone выбрасываем; broke — Past → was; V3 = broken." },
  { id: "pass-049", topic: "passive-present-past", type: "fix", q: "Сделай пассив: They make these shoes in Italy.", answers: ["These shoes are made in Italy."], explain: "make — Present; shoes — много: are made." },
  { id: "pass-050", topic: "passive-present-past", type: "fix", q: "Сделай пассив: Somebody cleaned the room yesterday.", answers: ["The room was cleaned yesterday."], explain: "cleaned — Past: was cleaned." },
  { id: "pass-051", topic: "passive-present-past", type: "fix", q: "Сделай пассив: They will open the new shop next month.", answers: ["The new shop will be opened next month."], explain: "will open → will be opened." },
  { id: "pass-052", topic: "passive-present-past", type: "fix", q: "Сделай пассив: Leonardo da Vinci painted the Mona Lisa.", answers: ["The Mona Lisa was painted by Leonardo da Vinci."], explain: "Здесь исполнитель важен — добавляем by." },
  { id: "pass-053", topic: "passive-present-past", type: "fix", q: "This house build in 1920.", answers: ["This house was built in 1920."], explain: "Нужно be (was) и V3: build → built." },
  { id: "pass-054", topic: "passive-present-past", type: "fix", q: "English speaks in many countries.", answers: ["English is spoken in many countries."], explain: "На английском «говорят» — пассив: is spoken." },
  { id: "pass-055", topic: "passive-present-past", type: "fix", q: "My phone was steal yesterday.", answers: ["My phone was stolen yesterday."], explain: "После was — V3: stolen." },
  { id: "pass-056", topic: "passive-present-past", type: "fix", q: "These books are write by a famous author.", answers: ["These books are written by a famous author."], explain: "После are — V3: written." },
  { id: "pass-057", topic: "passive-present-past", type: "fix", q: "The pictures was painted in 1900.", answers: ["The pictures were painted in 1900."], explain: "Pictures — много: were." },
  { id: "pass-058", topic: "passive-present-past", type: "fix", q: "The film is made in 2015.", answers: ["The film was made in 2015."], explain: "In 2015 — прошлое: was made." },
  { id: "pass-059", topic: "passive-present-past", type: "fill", q: "Используй Past Simple (пассив): The broken glass ___ yesterday. (pick up)", answers: ["was picked up"], explain: "Фразовый глагол: частица up остаётся — was picked up." },
  { id: "pass-060", topic: "passive-present-past", type: "fill", q: "Используй Past Simple (пассив): The match ___ because of the rain. (call off)", answers: ["was called off"], explain: "call off — отменить; в пассиве частица off остаётся." },
  { id: "pass-061", topic: "passive-present-past", type: "choice", q: "The old shoes ___ last week.", options: ["were thrown away", "were thrown", "threw away"], answer: "were thrown away", explain: "throw away — выбросить; в пассиве: were thrown away (V3 = thrown, away остаётся)." },
  { id: "pass-062", topic: "passive-present-past", type: "fix", q: "The broken glass was picked.", answers: ["The broken glass was picked up."], explain: "Фразовый глагол pick up — частицу up терять нельзя." },
  { id: "pass-063", topic: "passive-present-past", type: "translate", q: "Эту песню написали в 1980 году.", answers: ["This song was written in 1980.", "The song was written in 1980."], explain: "Песню «написали» — пассив, 1980 — прошлое: was written." },
  { id: "pass-064", topic: "passive-present-past", type: "translate", q: "Английский говорят во всём мире.", answers: ["English is spoken all over the world.", "English is spoken around the world.", "English is spoken in the whole world.", "English is spoken throughout the world."], explain: "Present Simple пассив: is spoken." },
  { id: "pass-065", topic: "passive-present-past", type: "translate", q: "Мою машину вчера украли.", answers: ["My car was stolen yesterday.", "My car was stolen."], explain: "Вчера — Past: was stolen." },
  { id: "pass-066", topic: "passive-present-past", type: "translate", q: "Завтра нас отвезут в аэропорт.", answers: ["We will be taken to the airport tomorrow.", "Tomorrow we will be taken to the airport.", "We'll be taken to the airport tomorrow."], explain: "Завтра — will be taken (take → taken)." },
  { id: "pass-067", topic: "passive-present-past", type: "translate", q: "Ужин подадут в восемь.", answers: ["Dinner will be served at eight.", "Dinner will be served at 8.", "Dinner will be served at eight o'clock.", "Dinner will be served at 8 o'clock."], explain: "will be served." },
  { id: "pass-068", topic: "passive-present-past", type: "translate", q: "Где сделаны эти часы?", answers: ["Where are these watches made?", "Where is this watch made?", "Where are these clocks made?", "Where is this clock made?"], explain: "Вопрос: слово where + are + подлежащее + V3." },

  // ---------- passive-simple (be + V3: Present Simple / Past Simple / will) ----------
  // Present Simple
  { id: "pas-001", topic: "passive-simple", type: "choice", q: "___ the letters delivered to your house every day?", options: ["Are", "Do", "Is"], answer: "Are", explain: "Вопрос в пассиве: be выходит вперёд. Letters — множественное число, значит Are (без do)." },
  { id: "pas-002", topic: "passive-simple", type: "choice", q: "The rooms in this hotel ___ every morning.", options: ["are cleaned", "is cleaned", "clean"], answer: "are cleaned", explain: "Комнаты не убирают сами — их убирают: are + V3. Rooms — множественное число: are." },
  { id: "pas-003", topic: "passive-simple", type: "fix", q: "Fresh bread is bake in our shop every day.", answers: ["Fresh bread is baked in our shop every day."], explain: "После is глагол в V3: baked." },
  { id: "pas-004", topic: "passive-simple", type: "fill", q: "Используй Passive, Present Simple: These shirts ___ (make) from cotton.", hint: "make", answers: ["are made"], explain: "Shirts — мн. число: are + V3 (make → made)." },
  { id: "pas-005", topic: "passive-simple", type: "fill", q: "Используй Passive, Present Simple, отрицание: Pets ___ (not allow) in this hotel.", hint: "allow", answers: ["aren't allowed", "are not allowed"], explain: "Отрицание: are not (aren't) + V3." },
  { id: "pas-006", topic: "passive-simple", type: "fix", q: "The classroom is cleans every evening.", answers: ["The classroom is cleaned every evening."], explain: "is + V3, а не is + глагол с -s: is cleaned." },
  { id: "pas-007", topic: "passive-simple", type: "fix", q: "These cars are make in Spain.", answers: ["These cars are made in Spain."], explain: "После are — V3: make → made." },
  { id: "pas-008", topic: "passive-simple", type: "fix", q: "The old newspapers are throw away every month.", answers: ["The old newspapers are thrown away every month."], explain: "V3 от throw — thrown; частица away остаётся." },
  { id: "pas-009", topic: "passive-simple", type: "fix", q: "The letters are delivers by a young postman.", answers: ["The letters are delivered by a young postman."], explain: "После are — V3: delivered." },
  { id: "pas-010", topic: "passive-simple", type: "fix", q: "Our new teacher is know by all the students.", answers: ["Our new teacher is known by all the students."], explain: "V3 от know — known." },
  { id: "pas-011", topic: "passive-simple", type: "translate", q: "Используй Passive, Present Simple (вопрос): Где делают эти часы?", answers: ["Where are these watches made?", "Where are these clocks made?", "Where are the watches made?", "Where are the clocks made?"], explain: "Вопросительное слово + are + подлежащее + V3." },
  { id: "pas-012", topic: "passive-simple", type: "translate", q: "Перепиши в пассиве (Present Simple): The cleaners wash the windows every Friday.", answers: ["The windows are washed every Friday.", "The windows are washed by the cleaners every Friday.", "The windows are washed every Friday by the cleaners."], explain: "Объект (the windows) — вперёд, are + washed; by the cleaners можно опустить." },
  { id: "pas-013", topic: "passive-simple", type: "translate", q: "Используй Passive, Present Simple, отрицание: Эти фильмы не показывают по телевизору.", answers: ["These films aren't shown on TV.", "These films are not shown on TV.", "These films aren't shown on television.", "These films are not shown on television.", "These movies aren't shown on TV.", "These movies are not shown on TV.", "These movies aren't shown on television.", "These movies are not shown on television."], explain: "are not + V3 (show → shown); on TV." },
  { id: "pas-014", topic: "passive-simple", type: "translate", q: "Составь предложение (Passive, Present Simple): the garden — water — every evening", answers: ["The garden is watered every evening.", "Every evening the garden is watered."], explain: "is + watered; время — в конце или в начале." },
  { id: "pas-015", topic: "passive-simple", type: "fill", q: "Используй Passive, Present Simple: The little children ___ (look after) by a nanny.", hint: "look after", answers: ["are looked after"], explain: "Фразовый глагол: are looked after — частица after остаётся." },
  // Past Simple
  { id: "pas-016", topic: "passive-simple", type: "choice", q: "The old bridge ___ in 1890.", options: ["was built", "built", "were built"], answer: "was built", explain: "Мост один — was; build → built (V3)." },
  { id: "pas-017", topic: "passive-simple", type: "choice", q: "The match ___ in spite of the rain, so we played.", options: ["wasn't cancelled", "wasn't cancel", "didn't cancelled"], answer: "wasn't cancelled", explain: "Отрицание в пассиве: wasn't + V3, без did." },
  { id: "pas-018", topic: "passive-simple", type: "fill", q: "Используй Passive, Past Simple, вопрос: ___ the pictures painted by your sister?", answers: ["Were"], explain: "Pictures — мн. число, прошлое: Were." },
  { id: "pas-019", topic: "passive-simple", type: "fill", q: "Используй Passive, Past Simple: This song ___ (write) in 1975.", hint: "write", answers: ["was written"], explain: "Песня одна — was; write → written." },
  { id: "pas-020", topic: "passive-simple", type: "fill", q: "Используй Passive, Past Simple, отрицание: The parcel ___ (not deliver) on Monday.", hint: "deliver", answers: ["wasn't delivered", "was not delivered"], explain: "wasn't + V3." },
  { id: "pas-021", topic: "passive-simple", type: "fix", q: "We was teached to swim at the age of six.", answers: ["We were taught to swim at the age of six."], explain: "С we — were; V3 от teach — taught («teached» не существует)." },
  { id: "pas-022", topic: "passive-simple", type: "fix", q: "The kitchen window was broke by a ball.", answers: ["The kitchen window was broken by a ball."], explain: "После was — V3: broken, а не broke." },
  { id: "pas-023", topic: "passive-simple", type: "fix", q: "My wallet was steal on the bus.", answers: ["My wallet was stolen on the bus."], explain: "После was — V3: steal → stolen." },
  { id: "pas-024", topic: "passive-simple", type: "fix", q: "The window broken during the storm.", answers: ["The window was broken during the storm."], explain: "Нельзя пропускать be: was broken." },
  { id: "pas-025", topic: "passive-simple", type: "fix", q: "When the castle built?", answers: ["When was the castle built?"], explain: "В вопросе нужен be: When was the castle built?" },
  { id: "pas-026", topic: "passive-simple", type: "fix", q: "The garden wasn't water last week.", answers: ["The garden wasn't watered last week.", "The garden was not watered last week."], explain: "После wasn't — V3: watered." },
  { id: "pas-027", topic: "passive-simple", type: "fix", q: "The prizes was gived to the winners.", answers: ["The prizes were given to the winners."], explain: "Prizes — мн. число: were; give → given («gived» не бывает)." },
  { id: "pas-028", topic: "passive-simple", type: "translate", q: "Перепиши в пассиве (Past Simple): Someone stole our car last night.", answers: ["Our car was stolen last night."], explain: "Someone в пассиве опускаем. Our car was stolen." },
  { id: "pas-029", topic: "passive-simple", type: "translate", q: "Перепиши в пассиве (Past Simple): The school set up a chess club last year.", answers: ["A chess club was set up last year.", "A chess club was set up by the school last year.", "A chess club was set up last year by the school."], explain: "set up — фразовый глагол, V3 = set: was set up." },
  { id: "pas-030", topic: "passive-simple", type: "translate", q: "Составь предложение (Passive, Past Simple): my phone — steal — on the train", answers: ["My phone was stolen on the train.", "On the train my phone was stolen."], explain: "was + stolen; уточнение места — в конце или в начале." },
  // will
  { id: "pas-031", topic: "passive-simple", type: "fix", q: "The new songs will be play on the radio tomorrow.", answers: ["The new songs will be played on the radio tomorrow."], explain: "will be + V3: played." },
  { id: "pas-032", topic: "passive-simple", type: "choice", q: "Don't worry, your parcel ___ tomorrow morning.", options: ["will be delivered", "will deliver", "will be deliver"], answer: "will be delivered", explain: "Посылку доставят: will be + V3." },
  { id: "pas-033", topic: "passive-simple", type: "fill", q: "Используй Passive, will: The broken chairs ___ (take away) tomorrow.", hint: "take away", answers: ["will be taken away", "'ll be taken away"], explain: "will be + taken away (take → taken)." },
  { id: "pas-034", topic: "passive-simple", type: "translate", q: "Составь предложение (Passive, will): the results — publish — on Friday", answers: ["The results will be published on Friday.", "On Friday the results will be published."], explain: "will be + published." },
  { id: "pas-035", topic: "passive-simple", type: "fill", q: "Используй Passive, will, отрицание: The concert ___ (not cancel) if it rains.", hint: "cancel", answers: ["won't be cancelled", "will not be cancelled", "won't be canceled", "will not be canceled"], explain: "won't be + V3." },
  { id: "pas-036", topic: "passive-simple", type: "fix", q: "We will be invited our neighbours to the party.", answers: ["We will invite our neighbours to the party."], explain: "Мы сами приглашаем — актив: will invite. Пассив был бы: Our neighbours will be invited." },
  { id: "pas-037", topic: "passive-simple", type: "fix", q: "The new rules will explained to everyone.", answers: ["The new rules will be explained to everyone."], explain: "После will нужен be: will be explained." },
  { id: "pas-038", topic: "passive-simple", type: "fix", q: "The guests will be pick up from the airport.", answers: ["The guests will be picked up from the airport."], explain: "will be + V3, частица up остаётся: picked up." },
  { id: "pas-039", topic: "passive-simple", type: "translate", q: "Перепиши в пассиве (will): They will build a new bridge here next year.", answers: ["A new bridge will be built here next year.", "Here a new bridge will be built next year."], explain: "They опускаем; will be built." },
  { id: "pas-040", topic: "passive-simple", type: "translate", q: "Используй Passive, will (вопрос): Когда доставят заказ?", answers: ["When will the order be delivered?", "When will my order be delivered?", "When will your order be delivered?", "When will our order be delivered?"], explain: "When + will + подлежащее + be + V3." },
  // Выбор времени
  { id: "pas-041", topic: "passive-simple", type: "choice", q: "The first computers ___ in the 1940s.", options: ["were made", "are made", "will be made"], answer: "were made", explain: "in the 1940s — прошлое: were + V3." },
  { id: "pas-042", topic: "passive-simple", type: "choice", q: "Don't worry, the room ___ before you arrive tomorrow.", options: ["was cleaned", "will be cleaned", "cleaned"], answer: "will be cleaned", explain: "tomorrow — будущее: will be cleaned." },
  { id: "pas-043", topic: "passive-simple", type: "choice", q: "Every morning the post ___ to our door.", options: ["is brought", "was brought", "will be brought"], answer: "is brought", explain: "Every morning — регулярно: Present Simple, is brought." },
  { id: "pas-044", topic: "passive-simple", type: "fix", q: "Yesterday my lost keys was find under a sofa.", answers: ["Yesterday my lost keys were found under a sofa."], explain: "Keys — мн. число: were; find → found." },
  { id: "pas-045", topic: "passive-simple", type: "choice", q: "Last Monday the tickets ___ at the door.", options: ["were sold", "are sold", "will be sold"], answer: "were sold", explain: "Last Monday — прошлое: were sold." },

  // ---------- future-forms: добор по Review 3 ----------
  { id: "ff-041", topic: "future-forms", type: "choice", q: "Watch out! You ___ off the ladder.", options: ["are going to fall", "fall", "are falling", "fell"], answer: "are going to fall", explain: "Видим признак прямо сейчас (лестница шатается) — очевидная угроза: be going to." },
  { id: "ff-042", topic: "future-forms", type: "choice", q: "Dark clouds are coming and the wind is rising. It ___ soon.", options: ["is going to rain", "rains", "rained", "has rained"], answer: "is going to rain", explain: "Предсказание по признакам (тучи, ветер): be going to." },
  { id: "ff-043", topic: "future-forms", type: "fill", q: "Используй Present Continuous (договорённость): We ___ (meet) Anna at six; we agreed yesterday.", hint: "meet", answers: ["are meeting", "'re meeting"], explain: "Заранее договорились — Present Continuous: are meeting." },
  { id: "ff-044", topic: "future-forms", type: "fill", q: "Используй will (решение в момент речи): There's no milk left! I ___ (buy) some.", hint: "buy", answers: ["will buy", "'ll buy"], explain: "Решили только что — will." },
  { id: "ff-045", topic: "future-forms", type: "fill", q: "Используй be going to (намерение): She has already decided: she ___ (study) medicine.", hint: "study", answers: ["is going to study", "'s going to study"], explain: "Намерение, решение принято заранее — be going to." },
  { id: "ff-046", topic: "future-forms", type: "fix", q: "My cousin visits us next Sunday; we arranged it yesterday.", answers: ["My cousin is visiting us next Sunday; we arranged it yesterday.", "My cousin is going to visit us next Sunday; we arranged it yesterday."], explain: "Договорённость о будущем — Present Continuous (или be going to), а не Present Simple." },
  { id: "ff-047", topic: "future-forms", type: "fix", q: "The train will leaving at 8.15 tomorrow.", answers: ["The train leaves at 8.15 tomorrow.", "The train is leaving at 8.15 tomorrow.", "The train will leave at 8.15 tomorrow.", "The train leaves at 8:15 tomorrow.", "The train will leave at 8:15 tomorrow."], explain: "После will — глагол без -ing. Расписание лучше передаёт Present Simple: leaves." },
  { id: "ff-048", topic: "future-forms", type: "fix", q: "Look at that car! It will crash into the wall.", answers: ["Look at that car! It is going to crash into the wall.", "Look at that car! It's going to crash into the wall."], explain: "Мы видим угрозу прямо сейчас — be going to." },
  { id: "ff-049", topic: "future-forms", type: "fix", q: "I am going learn Spanish this year.", answers: ["I am going to learn Spanish this year.", "I'm going to learn Spanish this year."], explain: "be going TO + глагол: пропущено to." },
  { id: "ff-050", topic: "future-forms", type: "translate", q: "Используй Present Continuous: Завтра вечером мы ужинаем с друзьями.", answers: ["We are having dinner with our friends tomorrow evening.", "We are having dinner with friends tomorrow evening.", "Tomorrow evening we are having dinner with our friends.", "Tomorrow evening we are having dinner with friends."], explain: "Договорённость — Present Continuous; have dinner — ужинать." },

  // ---------- phrasal-verbs-common: в дорогу, добор ----------
  { id: "phr-067", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: It started to rain, so we quickly ___ (get into) the car.", hint: "g… into", answers: ["got into"], explain: "get into the car — сесть в машину; Past Simple: got into." },
  { id: "phr-068", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: She opened the door and ___ (get out of) the car.", hint: "g… out of", answers: ["got out of"], explain: "get out of the car — выйти из машины; got out of." },
  { id: "phr-069", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: We ___ (set off) at five, so we arrived early.", hint: "s… off", answers: ["set off"], explain: "set off — отправиться в путь. V2 = set (не меняется)." },
  { id: "phr-070", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: The plane ___ (take off) in a thunderstorm.", hint: "t… off", answers: ["took off"], explain: "take off — взлететь; took off." },
  { id: "phr-071", topic: "phrasal-verbs-common", type: "fill", q: "Используй Present Simple: My neighbours often ___ (go away) at the weekend.", hint: "g… away", answers: ["go away"], explain: "Present Simple, they — без -s: go away." },
  { id: "phr-072", topic: "phrasal-verbs-common", type: "fill", q: "Используй Past Simple: Our aunt ___ (look after) us when Mum was ill.", hint: "l… after", answers: ["looked after"], explain: "look after — присматривать; looked after." },
  { id: "phr-073", topic: "phrasal-verbs-common", type: "fix", q: "Only three people turn up at the party yesterday.", answers: ["Only three people turned up at the party yesterday."], explain: "yesterday — прошлое: turn up → turned up." },
  { id: "phr-074", topic: "phrasal-verbs-common", type: "fix", q: "He get out of the car and slammed the door.", answers: ["He got out of the car and slammed the door."], explain: "slammed — прошедшее, значит get → got out of." },
  { id: "phr-075", topic: "phrasal-verbs-common", type: "fix", q: "Last Friday we set up at six to avoid the traffic.", answers: ["Last Friday we set off at six to avoid the traffic."], explain: "Отправиться в путь — set off (set up — «основать, настроить»)." },
  { id: "phr-076", topic: "phrasal-verbs-common", type: "fix", q: "My sister look after the dog last weekend.", answers: ["My sister looked after the dog last weekend."], explain: "last weekend — прошлое: looked after." },

  // ---------- word-formation: Going abroad, добор ----------
  { id: "wf-088", topic: "word-formation", type: "fill", q: "Check the board for the ___ of your train.", hint: "depart", answers: ["departure"], explain: "После the — существительное: departure." },
  { id: "wf-089", topic: "word-formation", type: "fill", q: "After a long journey, their ___ at the hotel was very late.", hint: "arrive", answers: ["arrival"], explain: "После their — существительное: arrival." },
  { id: "wf-090", topic: "word-formation", type: "fill", q: "The wind suddenly changed ___, and the boat turned.", hint: "direct", answers: ["direction"], explain: "После глагола changed — существительное: change direction." },
  { id: "wf-091", topic: "word-formation", type: "fill", q: "The ___ stopped the bus and opened the doors.", hint: "drive", answers: ["driver"], explain: "После the — человек, который делает: driver." },
  { id: "wf-092", topic: "word-formation", type: "fill", q: "A ___ with a big backpack asked me the way.", hint: "travel", answers: ["traveller", "traveler"], explain: "После a — человек: traveller (в США — traveler)." },
  { id: "wf-093", topic: "word-formation", type: "fill", q: "The lake is very ___ in autumn, when the trees turn red.", hint: "attract", answers: ["attractive"], explain: "После is very — прилагательное: attractive." },
  { id: "wf-094", topic: "word-formation", type: "fix", q: "The seats are very comfort, so I slept well.", answers: ["The seats are very comfortable, so I slept well."], explain: "После very — прилагательное: comfortable." },
  { id: "wf-095", topic: "word-formation", type: "fix", q: "I made a good choose when I picked this hotel.", answers: ["I made a good choice when I picked this hotel."], explain: "После a good — существительное: choice." },
  { id: "wf-096", topic: "word-formation", type: "fix", q: "She has flew to Berlin twice this year.", answers: ["She has flown to Berlin twice this year."], explain: "После has — V3: flown." },
  { id: "wf-097", topic: "word-formation", type: "fix", q: "Yesterday a big bird flown over our garden.", answers: ["Yesterday a big bird flew over our garden."], explain: "Yesterday — Past Simple: flew." }
);

// =====================================================================
// ДОПОЛНЕНИЕ «База B1»: новая тема mixed-tenses (время нужно выбрать самому)
// и по 15+ новых упражнений к самым «тонким» темам B1.
// =====================================================================
DATA.exercises.push(

  // ---------- mixed-tenses ----------
  { id: "mt-001", topic: "mixed-tenses", type: "choice", q: "Look! It ___ outside.", options: ["snows", "is snowing", "has snowed", "snowed"], answer: "is snowing", explain: "**Look!** — действие идёт прямо сейчас: Present Continuous (is + -ing)." },
  { id: "mt-002", topic: "mixed-tenses", type: "choice", q: "I ___ this film three times, so I know the ending.", options: ["see", "saw", "have seen", "am seeing"], answer: "have seen", explain: "Опыт к настоящему моменту, время не названо (three times) — Present Perfect." },
  { id: "mt-003", topic: "mixed-tenses", type: "choice", q: "We ___ to Spain two years ago.", options: ["have gone", "went", "go", "had gone"], answer: "went", explain: "**two years ago** — законченное время в прошлом: только Past Simple. С ago Present Perfect не бывает." },
  { id: "mt-004", topic: "mixed-tenses", type: "choice", q: "When I got to the station, the train ___.", options: ["already leaves", "has already left", "had already left", "is already leaving"], answer: "had already left", explain: "Поезд ушёл РАНЬШЕ, чем я пришёл (got — прошлое): «прошлое до прошлого» — Past Perfect (had + V3)." },
  { id: "mt-005", topic: "mixed-tenses", type: "choice", q: "She usually ___ to work, but today she ___ the bus.", options: ["walks / is taking", "is walking / takes", "walks / takes", "walked / took"], answer: "walks / is taking", explain: "**usually** — привычка (Present Simple), **today** — временное действие сейчас (Present Continuous)." },
  { id: "mt-006", topic: "mixed-tenses", type: "choice", q: "I ___ dinner when the phone rang.", options: ["cooked", "was cooking", "have cooked", "am cooking"], answer: "was cooking", explain: "Длинное действие-фон (was cooking), которое прервало короткое (rang): Past Continuous + Past Simple." },
  { id: "mt-007", topic: "mixed-tenses", type: "choice", q: "How long ___ here? — Since 2020.", options: ["do you live", "are you living", "have you lived", "did you live"], answer: "have you lived", explain: "**How long … since** — началось в прошлом и продолжается сейчас: Present Perfect. По-русски здесь настоящее («живёшь»), в английском — нет." },
  { id: "mt-008", topic: "mixed-tenses", type: "choice", q: "I think it ___ tomorrow.", options: ["rains", "is raining", "will rain", "rained"], answer: "will rain", explain: "**I think … tomorrow** — предсказание, мнение о будущем: will + глагол." },
  { id: "mt-009", topic: "mixed-tenses", type: "choice", q: "I ___ my keys. Can you help me look for them?", options: ["lose", "am losing", "have lost", "had lost"], answer: "have lost", explain: "Важен результат сейчас (ключей нет, ищем) — Present Perfect." },
  { id: "mt-010", topic: "mixed-tenses", type: "choice", q: "He ___ football every Saturday when he was a child.", options: ["plays", "played", "has played", "is playing"], answer: "played", explain: "**when he was a child** — законченный период в прошлом: Past Simple, даже если действие повторялось." },
  { id: "mt-011", topic: "mixed-tenses", type: "choice", q: "I'll call you when I ___ home.", options: ["will get", "get", "got", "am getting"], answer: "get", explain: "После **when** о будущем — Present Simple, а не will: when I **get** home." },
  { id: "mt-012", topic: "mixed-tenses", type: "choice", q: "___ to London? — Yes, twice.", options: ["Do you ever be", "Have you ever been", "Are you ever being", "Had you ever been"], answer: "Have you ever been", explain: "Вопрос об опыте за всю жизнь — Present Perfect: Have you ever **been to**…" },
  { id: "mt-013", topic: "mixed-tenses", type: "choice", q: "I can't talk now — I ___.", options: ["drive", "am driving", "drove", "have driven"], answer: "am driving", explain: "**now** — действие в процессе: am driving." },
  { id: "mt-014", topic: "mixed-tenses", type: "choice", q: "By the time we arrived, the film ___.", options: ["starts", "has started", "had started", "will start"], answer: "had started", explain: "**By the time** + прошлое (arrived): фильм начался раньше — Past Perfect." },
  { id: "mt-015", topic: "mixed-tenses", type: "choice", q: "This house ___ to my grandparents.", options: ["is belonging", "belongs", "has been belonging", "was belonging"], answer: "belongs", explain: "**belong** — глагол состояния, в Continuous не ставится: belongs." },
  { id: "mt-016", topic: "mixed-tenses", type: "choice", q: "They ___ married in 2015 and they are still together.", options: ["have got", "got", "get", "had got"], answer: "got", explain: "**in 2015** — точное время в прошлом: Past Simple, хотя результат есть и сейчас." },
  { id: "mt-017", topic: "mixed-tenses", type: "fill", q: "Yesterday I ___ to the cinema with my brother.", hint: "go — время выбери сам", answers: ["went"], explain: "**Yesterday** — Past Simple: go → went." },
  { id: "mt-018", topic: "mixed-tenses", type: "fill", q: "Be quiet, please. The baby ___.", hint: "sleep — время выбери сам", answers: ["is sleeping"], explain: "Действие идёт прямо сейчас (Be quiet!) — Present Continuous: is sleeping." },
  { id: "mt-019", topic: "mixed-tenses", type: "fill", q: "My father ___ in a bank. He likes his job.", hint: "work — время выбери сам", answers: ["works"], explain: "Постоянный факт — Present Simple; с he не забудь **-s**: works." },
  { id: "mt-020", topic: "mixed-tenses", type: "fill", q: "I ___ never been to Japan, but I want to go.", hint: "вспомогательный глагол", answers: ["have"], explain: "Опыт к настоящему моменту: have + never + V3 (been)." },
  { id: "mt-021", topic: "mixed-tenses", type: "fill", q: "While we ___ TV, the lights went out.", hint: "watch — время выбери сам", answers: ["were watching"], explain: "**While** + длинное действие-фон в прошлом — Past Continuous: were watching." },
  { id: "mt-022", topic: "mixed-tenses", type: "fill", q: "She ___ her homework yet, so she can't go out.", hint: "not finish — время выбери сам", answers: ["hasn't finished", "has not finished"], explain: "**yet** в отрицании — Present Perfect: hasn't finished." },
  { id: "mt-023", topic: "mixed-tenses", type: "fill", q: "I ___ him last week, but I haven't seen him since then.", hint: "meet — время выбери сам", answers: ["met"], explain: "**last week** — законченное время: Past Simple (meet → met)." },
  { id: "mt-024", topic: "mixed-tenses", type: "fill", q: "When we came home, dinner was on the table: Mum ___ it an hour before.", hint: "cook — время выбери сам", answers: ["had cooked"], explain: "Мама приготовила РАНЬШЕ, чем мы пришли (an hour before) — Past Perfect: had cooked." },
  { id: "mt-025", topic: "mixed-tenses", type: "fill", q: "If it ___ tomorrow, we will stay at home.", hint: "rain — время выбери сам", answers: ["rains"], explain: "После **if** о будущем — Present Simple, не will: if it rains." },
  { id: "mt-026", topic: "mixed-tenses", type: "fill", q: "What ___ you doing at eight o'clock last night?", hint: "вспомогательный глагол", answers: ["were"], explain: "Действие в процессе в конкретный момент прошлого — Past Continuous: were you doing." },
  { id: "mt-027", topic: "mixed-tenses", type: "fill", q: "He ___ here since Monday.", hint: "be — время выбери сам", answers: ["has been"], explain: "**since Monday** — с прошлого до сейчас: Present Perfect (has been)." },
  { id: "mt-028", topic: "mixed-tenses", type: "fill", q: "Those bags look heavy. Don't worry, I ___ you.", hint: "help — время выбери сам", answers: ["will help", "'ll help"], explain: "Решение принято в момент речи (предложение помощи) — will: I'll help you." },
  { id: "mt-029", topic: "mixed-tenses", type: "fix", q: "I have seen him yesterday.", answers: ["I saw him yesterday."], explain: "**yesterday** — законченное время: Past Simple (saw), а не Present Perfect." },
  { id: "mt-030", topic: "mixed-tenses", type: "fix", q: "She is knowing the answer.", answers: ["She knows the answer."], explain: "**know** — глагол состояния, не бывает в Continuous: She knows." },
  { id: "mt-031", topic: "mixed-tenses", type: "fix", q: "I didn't finished my work yesterday.", answers: ["I didn't finish my work yesterday."], explain: "После **didn't** глагол без -ed: прошедшее время уже показал did." },
  { id: "mt-032", topic: "mixed-tenses", type: "fix", q: "He works at the moment, so he can't come.", answers: ["He is working at the moment, so he can't come."], explain: "**at the moment** — прямо сейчас: Present Continuous (is working)." },
  { id: "mt-033", topic: "mixed-tenses", type: "fix", q: "I live here since 2019.", answers: ["I have lived here since 2019.", "I have been living here since 2019."], explain: "**since 2019** — началось в прошлом и длится до сих пор: Present Perfect (have lived / have been living)." },
  { id: "mt-034", topic: "mixed-tenses", type: "fix", q: "When I'll see her, I'll tell her.", answers: ["When I see her, I'll tell her."], explain: "После **when** о будущем — Present Simple: when I see her." },
  { id: "mt-035", topic: "mixed-tenses", type: "fix", q: "We had went home before the rain started.", answers: ["We had gone home before the rain started."], explain: "После **had** нужна третья форма: go — went — **gone**." },
  { id: "mt-036", topic: "mixed-tenses", type: "fix", q: "I was watching TV when she was calling me.", answers: ["I was watching TV when she called me."], explain: "Звонок — короткое действие, которое прервало длинное: Past Simple (called)." },
  { id: "mt-037", topic: "mixed-tenses", type: "fix", q: "Does he playing tennis every Sunday?", answers: ["Does he play tennis every Sunday?"], explain: "**every Sunday** — привычка, Present Simple: Does + глагол без -ing." },
  { id: "mt-038", topic: "mixed-tenses", type: "fix", q: "I have been in Italy twice.", answers: ["I have been to Italy twice."], explain: "Об опыте поездок — have been **to**: I have been to Italy." },
  { id: "mt-039", topic: "mixed-tenses", type: "translate", q: "Я уже сделал домашнее задание.", answers: ["I have already done my homework.", "I have done my homework already.", "I have already done the homework.", "I have already finished my homework."], explain: "**уже** + результат сейчас — Present Perfect; already стоит между have и V3." },
  { id: "mt-040", topic: "mixed-tenses", type: "translate", q: "Что ты делал вчера в шесть часов?", answers: ["What were you doing at six o'clock yesterday?", "What were you doing yesterday at six o'clock?", "What were you doing at six yesterday?", "What were you doing yesterday at six?"], explain: "Действие в процессе в конкретный момент прошлого — Past Continuous: What were you doing…?" },
  { id: "mt-041", topic: "mixed-tenses", type: "translate", q: "Она работает здесь с 2020 года.", answers: ["She has worked here since 2020.", "She has been working here since 2020."], explain: "По-русски настоящее время, но **с 2020 года** = since 2020: Present Perfect (Simple или Continuous)." },
  { id: "mt-042", topic: "mixed-tenses", type: "translate", q: "Я позвоню тебе, когда закончу.", answers: ["I will call you when I finish.", "I will call you when I have finished.", "I will phone you when I finish.", "When I finish, I will call you."], explain: "Главная часть — will, а после **when** — Present Simple (не will finish)." },
  { id: "mt-043", topic: "mixed-tenses", type: "translate", q: "Сейчас я читаю книгу, а обычно я смотрю фильмы.", answers: ["I am reading a book now, but I usually watch films.", "Now I am reading a book, but I usually watch films.", "I am reading a book now, but usually I watch films.", "Now I am reading a book, but usually I watch films.", "I am reading a book now, but I usually watch movies.", "Now I am reading a book, but I usually watch movies.", "I am reading a book now, but usually I watch movies.", "Now I am reading a book, but usually I watch movies.", "I am reading a book now, and I usually watch films.", "Now I am reading a book, and I usually watch films."], explain: "**сейчас** — Present Continuous (am reading), **обычно** — Present Simple (watch)." },
  { id: "mt-044", topic: "mixed-tenses", type: "translate", q: "Когда я пришёл, они уже ушли.", answers: ["When I came, they had already left.", "When I arrived, they had already left.", "They had already left when I came.", "They had already left when I arrived.", "When I came, they had already gone.", "When I arrived, they had already gone."], explain: "Они ушли РАНЬШЕ, чем я пришёл: Past Perfect (had already left) + Past Simple (came)." },

  // ---------- first-conditional (дополнение) ----------
  { id: "cond1-016", topic: "first-conditional", type: "choice", q: "If we ___ the bus, we'll take a taxi.", options: ["miss", "will miss", "missed"], answer: "miss", explain: "После **if** — Present Simple, will только в главной части." },
  { id: "cond1-017", topic: "first-conditional", type: "choice", q: "You'll feel better if you ___ some water.", options: ["drink", "will drink", "drank"], answer: "drink", explain: "if может стоять и во второй половине — правило то же: после if нет will." },
  { id: "cond1-018", topic: "first-conditional", type: "choice", q: "If he doesn't call, I ___ him myself.", options: ["call", "will call", "called"], answer: "will call", explain: "Главная часть (результат в будущем) — will + глагол." },
  { id: "cond1-019", topic: "first-conditional", type: "choice", q: "___ you help me if I ask you?", options: ["Do", "Will", "Did"], answer: "Will", explain: "Вопрос о будущем результате: Will you help…, а после if — Present Simple (ask)." },
  { id: "cond1-020", topic: "first-conditional", type: "choice", q: "We'll be late ___ we leave right now.", options: ["if", "unless", "when"], answer: "unless", explain: "**unless** = if … not: опоздаем, ЕСЛИ НЕ выйдем прямо сейчас." },
  { id: "cond1-021", topic: "first-conditional", type: "fill", q: "If she ___, we'll start without her.", hint: "not come", answers: ["doesn't come", "does not come"], explain: "После if — Present Simple; отрицание с she — doesn't + глагол без -s." },
  { id: "cond1-022", topic: "first-conditional", type: "fill", q: "If you eat too much, you ___ sick.", hint: "feel", answers: ["will feel", "'ll feel"], explain: "Результат в будущем — will feel." },
  { id: "cond1-023", topic: "first-conditional", type: "fill", q: "I ___ you if I need help.", hint: "ask", answers: ["will ask", "'ll ask"], explain: "Главная часть — will ask; после if — Present Simple (need)." },
  { id: "cond1-024", topic: "first-conditional", type: "fill", q: "If they ___ us, we'll go to the party.", hint: "invite", answers: ["invite"], explain: "После if — Present Simple: they invite (без -s, потому что they)." },
  { id: "cond1-025", topic: "first-conditional", type: "fix", q: "If I will see him, I'll give him your message.", answers: ["If I see him, I'll give him your message."], explain: "После if не ставим will: If I **see** him." },
  { id: "cond1-026", topic: "first-conditional", type: "fix", q: "If you don't study, you fail the exam tomorrow.", answers: ["If you don't study, you will fail the exam tomorrow."], explain: "Результат в будущем (tomorrow) — will fail." },
  { id: "cond1-027", topic: "first-conditional", type: "fix", q: "Unless you don't hurry, you'll miss the train.", answers: ["Unless you hurry, you'll miss the train.", "If you don't hurry, you'll miss the train."], explain: "**unless** уже содержит отрицание (= if not), второе don't лишнее." },
  { id: "cond1-028", topic: "first-conditional", type: "fix", q: "She will be angry if you will be late again.", answers: ["She will be angry if you are late again."], explain: "will — только в главной части; после if — Present Simple: if you **are** late." },
  { id: "cond1-029", topic: "first-conditional", type: "translate", q: "Если будет холодно, я надену пальто.", answers: ["If it is cold, I will wear a coat.", "If it is cold, I will put on a coat.", "If it is cold, I will wear my coat.", "If it is cold, I will put on my coat.", "If it is cold, I will put my coat on.", "I will wear a coat if it is cold.", "I will put on a coat if it is cold."], explain: "По-русски «если будет», по-английски после if — настоящее: If it **is** cold." },
  { id: "cond1-030", topic: "first-conditional", type: "translate", q: "Что ты будешь делать, если он не придёт?", answers: ["What will you do if he doesn't come?", "If he doesn't come, what will you do?", "What are you going to do if he doesn't come?"], explain: "Вопрос — What will you do; после if — Present Simple с отрицанием: he doesn't come." },

  // ---------- second-conditional (дополнение) ----------
  { id: "cond2-016", topic: "second-conditional", type: "choice", q: "If I ___ more money, I'd buy a new laptop.", options: ["have", "had", "would have"], answer: "had", explain: "Нереальное условие о настоящем: после if — Past Simple (had), would — только в главной части." },
  { id: "cond2-017", topic: "second-conditional", type: "choice", q: "If she lived closer, we ___ each other more often.", options: ["see", "will see", "would see"], answer: "would see", explain: "Условие нереальное (lived) — результат would + глагол." },
  { id: "cond2-018", topic: "second-conditional", type: "choice", q: "Where would you live if you ___ choose any country?", options: ["can", "could", "would"], answer: "could", explain: "После if вместо can — could (прошедшая форма): if you could choose." },
  { id: "cond2-019", topic: "second-conditional", type: "choice", q: "I don't have a car. If I ___ one, I'd drive you home.", options: ["have", "had", "will have"], answer: "had", explain: "Машины нет — ситуация воображаемая: If I had." },
  { id: "cond2-020", topic: "second-conditional", type: "choice", q: "If I were you, I ___ to a doctor.", options: ["will go", "would go", "went"], answer: "would go", explain: "**If I were you, I would…** — стандартная формула совета." },
  { id: "cond2-021", topic: "second-conditional", type: "fill", q: "If he ___ English better, he would get the job.", hint: "speak", answers: ["spoke"], explain: "После if — Past Simple: speak → spoke." },
  { id: "cond2-022", topic: "second-conditional", type: "fill", q: "I ___ happier if I had more free time.", hint: "be", answers: ["would be", "'d be"], explain: "Главная часть — would + глагол: would be." },
  { id: "cond2-023", topic: "second-conditional", type: "fill", q: "If we ___ in a big city, we could go to the theatre every week.", hint: "live", answers: ["lived"], explain: "Воображаемая ситуация — Past Simple после if: lived." },
  { id: "cond2-024", topic: "second-conditional", type: "fill", q: "What ___ you do if you lost your passport abroad?", answers: ["would"], explain: "Вопрос во втором условном: What **would** you do if + Past Simple." },
  { id: "cond2-025", topic: "second-conditional", type: "fix", q: "If I would know her number, I would call her.", answers: ["If I knew her number, I would call her."], explain: "После if нет would: If I **knew**." },
  { id: "cond2-026", topic: "second-conditional", type: "fix", q: "If I had more time, I will read more books.", answers: ["If I had more time, I would read more books."], explain: "had после if — значит ситуация нереальная, и результат — would, а не will." },
  { id: "cond2-027", topic: "second-conditional", type: "fix", q: "If he was taller, he will play basketball.", answers: ["If he was taller, he would play basketball.", "If he were taller, he would play basketball."], explain: "Нереальное условие — результат с would. В условии можно was или (правильнее) were." },
  { id: "cond2-028", topic: "second-conditional", type: "fix", q: "I would help you if I can.", answers: ["I would help you if I could."], explain: "Во втором условном после if — прошедшая форма: can → could." },
  { id: "cond2-029", topic: "second-conditional", type: "translate", q: "На твоём месте я бы не покупал эту машину.", answers: ["If I were you, I would not buy this car.", "I would not buy this car if I were you.", "If I were you, I would not buy that car.", "I would not buy that car if I were you."], explain: "«На твоём месте» = **If I were you** (were, не was), дальше would not + глагол." },
  { id: "cond2-030", topic: "second-conditional", type: "translate", q: "Если бы я жил у моря, я бы плавал каждый день.", answers: ["If I lived by the sea, I would swim every day.", "If I lived near the sea, I would swim every day.", "I would swim every day if I lived by the sea.", "I would swim every day if I lived near the sea.", "If I lived at the seaside, I would swim every day.", "If I lived by the sea, I would go swimming every day."], explain: "«Если бы» — Past Simple после if (lived), «я бы» — would swim." },

  // ---------- reported-speech (дополнение) ----------
  { id: "rep-016", topic: "reported-speech", type: "choice", q: "«I'm working,» he said. → He said he ___.", options: ["is working", "was working", "has worked"], answer: "was working", explain: "Сдвиг времени назад: am working → was working." },
  { id: "rep-017", topic: "reported-speech", type: "choice", q: "«I must go,» she said. → She said she ___ go.", options: ["must to", "had to", "has to"], answer: "had to", explain: "must в косвенной речи обычно → had to." },
  { id: "rep-018", topic: "reported-speech", type: "choice", q: "He ___ that he didn't know the answer.", options: ["said", "told", "asked"], answer: "said", explain: "После **said** нет слова «кому»; после told оно обязательно (told me)." },
  { id: "rep-019", topic: "reported-speech", type: "choice", q: "«Where do you work?» → She asked me where I ___.", options: ["work", "worked", "did work"], answer: "worked", explain: "В косвенном вопросе порядок слов как в утверждении, без do/did, время сдвигается: worked." },
  { id: "rep-020", topic: "reported-speech", type: "choice", q: "«I'll do it tomorrow.» → He said he would do it ___.", options: ["tomorrow", "the next day", "yesterday"], answer: "the next day", explain: "Меняются и слова времени: tomorrow → the next day." },
  { id: "rep-021", topic: "reported-speech", type: "choice", q: "«Please sit down.» → The teacher asked us ___.", options: ["sit down", "to sit down", "sitting down"], answer: "to sit down", explain: "Просьба в косвенной речи: ask + кого + **to** + глагол." },
  { id: "rep-022", topic: "reported-speech", type: "fill", q: "«I can't swim.» → She said she ___ swim.", answers: ["couldn't", "could not"], explain: "can't → couldn't." },
  { id: "rep-023", topic: "reported-speech", type: "fill", q: "«I have lost my keys.» → He said he ___ lost his keys.", answers: ["had"], explain: "Present Perfect (have lost) → Past Perfect (had lost)." },
  { id: "rep-024", topic: "reported-speech", type: "fill", q: "She ___ me that the shop was closed.", hint: "say или tell — в прошедшем", answers: ["told"], explain: "Есть «кому» (me) — значит told, а не said." },
  { id: "rep-025", topic: "reported-speech", type: "fill", q: "«Don't be late!» → Mum told me ___ to be late.", answers: ["not"], explain: "Отрицательная просьба: told me **not to** + глагол." },
  { id: "rep-026", topic: "reported-speech", type: "fix", q: "He said me that he was ill.", answers: ["He told me that he was ill.", "He told me he was ill.", "He said that he was ill.", "He said he was ill.", "He said to me that he was ill."], explain: "say + что; tell + кому + что. «Said me» не бывает." },
  { id: "rep-027", topic: "reported-speech", type: "fix", q: "She asked me where was the station.", answers: ["She asked me where the station was."], explain: "В косвенном вопросе прямой порядок слов: where the station **was**." },
  { id: "rep-028", topic: "reported-speech", type: "fix", q: "He told that he would come later.", answers: ["He said that he would come later.", "He said he would come later.", "He told me that he would come later.", "He told me he would come later.", "He told us that he would come later."], explain: "После told обязательно «кому». Если его нет — said." },
  { id: "rep-029", topic: "reported-speech", type: "fix", q: "She said that she will call me the next day.", answers: ["She said that she would call me the next day.", "She said she would call me the next day."], explain: "will → would после said." },
  { id: "rep-030", topic: "reported-speech", type: "fix", q: "The doctor told me don't eat sugar.", answers: ["The doctor told me not to eat sugar."], explain: "Запрет в косвенной речи: told me **not to** eat." },
  { id: "rep-031", topic: "reported-speech", type: "translate", q: "Он спросил, люблю ли я кофе.", answers: ["He asked me if I liked coffee.", "He asked if I liked coffee.", "He asked me whether I liked coffee.", "He asked whether I liked coffee."], explain: "«ли» = **if / whether**; после него — прямой порядок слов и сдвиг времени: I liked." },
  { id: "rep-032", topic: "reported-speech", type: "translate", q: "Она сказала мне, что не может прийти.", answers: ["She told me that she could not come.", "She told me she could not come.", "She said to me that she could not come."], explain: "«сказала мне» = told me; can't → couldn't." },

  // ---------- relative-clauses (дополнение) ----------
  { id: "rel-016", topic: "relative-clauses", type: "choice", q: "The people ___ live upstairs are very noisy.", options: ["who", "which", "whose"], answer: "who", explain: "О людях — who (или that)." },
  { id: "rel-017", topic: "relative-clauses", type: "choice", q: "The phone ___ I bought last week is already broken.", options: ["who", "which", "where"], answer: "which", explain: "О вещах — which (или that)." },
  { id: "rel-018", topic: "relative-clauses", type: "choice", q: "The hotel ___ we stayed was near the beach.", options: ["which", "where", "when"], answer: "where", explain: "Место, В котором что-то происходило, — where. (С which понадобился бы предлог: which we stayed **in**.)" },
  { id: "rel-019", topic: "relative-clauses", type: "choice", q: "I met a girl ___ father is a famous actor.", options: ["who", "whose", "which"], answer: "whose", explain: "**whose** = «чей»: девушка, чей отец…" },
  { id: "rel-020", topic: "relative-clauses", type: "choice", q: "2020 was the year ___ I started learning English.", options: ["where", "when", "which"], answer: "when", explain: "О времени — when." },
  { id: "rel-021", topic: "relative-clauses", type: "choice", q: "My brother, ___ lives in Canada, is coming next week.", options: ["that", "who", "which"], answer: "who", explain: "После запятой (дополнительная информация) that не используется: только who." },
  { id: "rel-022", topic: "relative-clauses", type: "fill", q: "A vet is a doctor ___ treats animals.", answers: ["who", "that"], explain: "О человеке — who или that." },
  { id: "rel-023", topic: "relative-clauses", type: "fill", q: "This is the shop ___ I bought my jacket.", answers: ["where"], explain: "Место, где произошло действие, — where." },
  { id: "rel-024", topic: "relative-clauses", type: "fill", q: "The film ___ we watched last night was boring.", answers: ["which", "that"], explain: "О вещи — which или that (здесь слово можно и вовсе опустить)." },
  { id: "rel-025", topic: "relative-clauses", type: "fill", q: "She is the teacher ___ lessons everyone loves.", answers: ["whose"], explain: "«Чьи уроки» — whose lessons." },
  { id: "rel-026", topic: "relative-clauses", type: "fix", q: "The man which lives next door is a pilot.", answers: ["The man who lives next door is a pilot.", "The man that lives next door is a pilot."], explain: "О людях — who / that, не which." },
  { id: "rel-027", topic: "relative-clauses", type: "fix", q: "This is the house where I grew up in.", answers: ["This is the house where I grew up.", "This is the house which I grew up in.", "This is the house that I grew up in.", "This is the house I grew up in.", "This is the house in which I grew up."], explain: "**where** уже значит «в котором» — предлог in лишний." },
  { id: "rel-028", topic: "relative-clauses", type: "fix", q: "The girl who I met her at the party is from Spain.", answers: ["The girl who I met at the party is from Spain.", "The girl whom I met at the party is from Spain.", "The girl that I met at the party is from Spain.", "The girl I met at the party is from Spain."], explain: "who уже заменяет her — второе местоимение не нужно." },
  { id: "rel-029", topic: "relative-clauses", type: "fix", q: "I have a friend who he plays the guitar.", answers: ["I have a friend who plays the guitar.", "I have a friend that plays the guitar."], explain: "who — подлежащее придаточного, he лишнее." },
  { id: "rel-030", topic: "relative-clauses", type: "translate", q: "Это книга, которую я читаю сейчас.", answers: ["This is the book that I am reading now.", "This is the book which I am reading now.", "This is the book I am reading now.", "This is the book that I am reading at the moment.", "This is the book I am reading at the moment.", "It is the book I am reading now.", "It is the book that I am reading now."], explain: "«которую» — that / which, а в разговорной речи его можно опустить: the book I am reading." },
  { id: "rel-031", topic: "relative-clauses", type: "translate", q: "У меня есть друг, который живёт в Лондоне.", answers: ["I have a friend who lives in London.", "I have a friend that lives in London.", "I have got a friend who lives in London.", "I have got a friend that lives in London."], explain: "О человеке — who; глагол после него согласуется с friend: lives." },

  // ---------- modals-deduction (дополнение) ----------
  { id: "deduct-016", topic: "modals-deduction", type: "choice", q: "She speaks perfect French. She ___ be from France.", options: ["must", "can't", "mustn't"], answer: "must", explain: "Есть основание так думать, почти уверен — must." },
  { id: "deduct-017", topic: "modals-deduction", type: "choice", q: "He ___ be a doctor — he's only sixteen!", options: ["must", "can't", "might"], answer: "can't", explain: "Уверен, что это невозможно, — can't." },
  { id: "deduct-018", topic: "modals-deduction", type: "choice", q: "I'm not sure, but this ___ be Anna's bag.", options: ["must", "could", "can't"], answer: "could", explain: "**I'm not sure** — только возможность: could / might / may." },
  { id: "deduct-019", topic: "modals-deduction", type: "choice", q: "The lights are on, so they ___ be at home.", options: ["must", "can't", "mustn't"], answer: "must", explain: "Вывод из факта (свет горит) — must." },
  { id: "deduct-020", topic: "modals-deduction", type: "choice", q: "It ___ be easy to work at night and study during the day.", options: ["mustn't", "can't", "must"], answer: "can't", explain: "«Не может быть легко» — can't. Mustn't означает запрет, а не догадку." },
  { id: "deduct-021", topic: "modals-deduction", type: "choice", q: "Take a jacket. It ___ get cold in the evening.", options: ["must", "may", "can't"], answer: "may", explain: "Возможно, но не точно — may / might." },
  { id: "deduct-022", topic: "modals-deduction", type: "fill", q: "She has three cars and a big house. She ___ be rich.", answers: ["must"], explain: "Уверенный вывод — must." },
  { id: "deduct-023", topic: "modals-deduction", type: "fill", q: "He ___ be hungry — he has just eaten two pizzas.", answers: ["can't", "cannot"], explain: "Уверен, что это не так, — can't." },
  { id: "deduct-024", topic: "modals-deduction", type: "fill", q: "I don't know where Tom is. He ___ be at the gym or at work.", answers: ["might", "may", "could"], explain: "Не знаю точно — might / may / could." },
  { id: "deduct-025", topic: "modals-deduction", type: "fill", q: "You've passed all your exams! You ___ be very happy.", answers: ["must"], explain: "Логичный вывод — must be." },
  { id: "deduct-026", topic: "modals-deduction", type: "fix", q: "He can be at work, but I'm not sure.", answers: ["He might be at work, but I'm not sure.", "He may be at work, but I'm not sure.", "He could be at work, but I'm not sure."], explain: "Для догадки о конкретной ситуации в утверждении — might / may / could, не can." },
  { id: "deduct-027", topic: "modals-deduction", type: "fix", q: "It mustn't be Tom at the door — he is in Spain now.", answers: ["It can't be Tom at the door — he is in Spain now."], explain: "«Не может быть» = can't. Mustn't — это «нельзя»." },
  { id: "deduct-028", topic: "modals-deduction", type: "fix", q: "She might to be late today.", answers: ["She might be late today."], explain: "После модальных глаголов — глагол без to." },
  { id: "deduct-029", topic: "modals-deduction", type: "fix", q: "They must are tired after the trip.", answers: ["They must be tired after the trip."], explain: "После must — начальная форма: be, а не are." },
  { id: "deduct-030", topic: "modals-deduction", type: "translate", q: "Это не может быть правдой.", answers: ["It can't be true.", "This can't be true.", "That can't be true."], explain: "«Не может быть» — can't be." },
  { id: "deduct-031", topic: "modals-deduction", type: "translate", q: "Она, должно быть, очень устала.", answers: ["She must be very tired."], explain: "«Должно быть» (догадка) — must be." },
  { id: "deduct-032", topic: "modals-deduction", type: "translate", q: "Возможно, он на работе.", answers: ["He might be at work.", "He may be at work.", "He could be at work.", "Maybe he is at work.", "Perhaps he is at work."], explain: "Неуверенная догадка: might / may / could + be (или Maybe he is…)." },

  // ---------- future-time-clauses (дополнение) ----------
  { id: "ftc-016", topic: "future-time-clauses", type: "choice", q: "I'll tell her as soon as she ___.", options: ["arrives", "will arrive", "arrived"], answer: "arrives", explain: "После **as soon as** о будущем — Present Simple." },
  { id: "ftc-017", topic: "future-time-clauses", type: "choice", q: "When I ___ older, I'll travel around the world.", options: ["will be", "am", "was"], answer: "am", explain: "После when о будущем — Present Simple: when I **am** older." },
  { id: "ftc-018", topic: "future-time-clauses", type: "choice", q: "We won't start until everyone ___ here.", options: ["is", "will be", "was"], answer: "is", explain: "После **until** — Present Simple, не will." },
  { id: "ftc-019", topic: "future-time-clauses", type: "choice", q: "I'll finish this before the boss ___ back.", options: ["comes", "will come", "came"], answer: "comes", explain: "После **before** о будущем — Present Simple: comes." },
  { id: "ftc-020", topic: "future-time-clauses", type: "choice", q: "After I ___ this book, I'll give it to you.", options: ["will read", "have read", "had read"], answer: "have read", explain: "После after можно Present Simple или Present Perfect (действие завершится): after I have read. Will — нельзя." },
  { id: "ftc-021", topic: "future-time-clauses", type: "choice", q: "When you see him, ___ him to call me.", options: ["tell", "will tell", "told"], answer: "tell", explain: "В главной части здесь просьба — повелительное наклонение: tell him." },
  { id: "ftc-022", topic: "future-time-clauses", type: "fill", q: "Text me when you ___ at the airport.", hint: "arrive", answers: ["arrive"], explain: "После when о будущем — Present Simple." },
  { id: "ftc-023", topic: "future-time-clauses", type: "fill", q: "I'll stay at home until the rain ___.", hint: "stop", answers: ["stops", "has stopped"], explain: "После until — Present Simple; the rain = it → stops." },
  { id: "ftc-024", topic: "future-time-clauses", type: "fill", q: "As soon as she ___ work, she'll come here.", hint: "finish", answers: ["finishes", "has finished"], explain: "После as soon as — Present Simple (finishes) или Present Perfect (has finished), но не will." },
  { id: "ftc-025", topic: "future-time-clauses", type: "fill", q: "Before I ___ to bed, I'll check my email.", hint: "go", answers: ["go"], explain: "После before о будущем — Present Simple." },
  { id: "ftc-026", topic: "future-time-clauses", type: "fix", q: "I'll phone you when I will arrive.", answers: ["I'll phone you when I arrive."], explain: "will — только в главной части; после when — arrive." },
  { id: "ftc-027", topic: "future-time-clauses", type: "fix", q: "Before you will go, please close the window.", answers: ["Before you go, please close the window."], explain: "После before нет will: before you go." },
  { id: "ftc-028", topic: "future-time-clauses", type: "fix", q: "As soon as he will come, we'll have dinner.", answers: ["As soon as he comes, we'll have dinner."], explain: "После as soon as — Present Simple; с he — comes." },
  { id: "ftc-029", topic: "future-time-clauses", type: "fix", q: "I'll wait here until she will finish.", answers: ["I'll wait here until she finishes.", "I'll wait here until she has finished."], explain: "После until нет will: until she finishes." },
  { id: "ftc-030", topic: "future-time-clauses", type: "translate", q: "Когда я вернусь, мы поговорим.", answers: ["When I come back, we will talk.", "When I get back, we will talk.", "When I return, we will talk.", "We will talk when I come back.", "We will talk when I get back.", "We will talk when I return."], explain: "«Когда вернусь» — будущее по-русски, но после when — Present Simple: when I come back." },
  { id: "ftc-031", topic: "future-time-clauses", type: "translate", q: "Я куплю хлеб, прежде чем пойду домой.", answers: ["I will buy bread before I go home.", "I will buy some bread before I go home.", "Before I go home, I will buy bread.", "Before I go home, I will buy some bread."], explain: "will — в главной части; после before — Present Simple: before I go home." },

  // ---------- linking-words (дополнение) ----------
  { id: "link-016", topic: "linking-words", type: "choice", q: "I took an umbrella ___ it was raining.", options: ["because", "although", "so"], answer: "because", explain: "**because** вводит причину." },
  { id: "link-017", topic: "linking-words", type: "choice", q: "It was raining, ___ I took an umbrella.", options: ["because", "so", "but"], answer: "so", explain: "**so** вводит результат: шёл дождь, поэтому…" },
  { id: "link-018", topic: "linking-words", type: "choice", q: "___ being tired, he finished the report.", options: ["Although", "Despite", "However"], answer: "Despite", explain: "**despite** + существительное или -ing (being). После although нужно целое предложение (although he was tired)." },
  { id: "link-019", topic: "linking-words", type: "choice", q: "She studied hard. ___, she failed the exam.", options: ["However", "Although", "Because"], answer: "However", explain: "**However** начинает новое предложение и отделяется запятой." },
  { id: "link-020", topic: "linking-words", type: "choice", q: "I went to the shop ___ buy some milk.", options: ["for", "to", "so"], answer: "to", explain: "Цель действия — **to** + глагол. Не «for buy» и не «for to buy»." },
  { id: "link-021", topic: "linking-words", type: "choice", q: "He speaks slowly ___ everyone can understand him.", options: ["so that", "because of", "despite"], answer: "so that", explain: "**so that** + предложение — «чтобы» (цель)." },
  { id: "link-022", topic: "linking-words", type: "choice", q: "We stayed at home ___ the bad weather.", options: ["because", "because of", "although"], answer: "because of", explain: "**because of** + существительное; because + предложение (because the weather was bad)." },
  { id: "link-023", topic: "linking-words", type: "fill", q: "___ he is only ten, he plays chess very well.", hint: "хотя", answers: ["Although", "Though", "Even though"], explain: "«Хотя» + предложение — although / though / even though." },
  { id: "link-024", topic: "linking-words", type: "fill", q: "The film was long. ___, I enjoyed it.", hint: "однако", answers: ["However", "Nevertheless", "Still"], explain: "**However** — «однако», в начале нового предложения, после него запятая." },
  { id: "link-025", topic: "linking-words", type: "fill", q: "In spite ___ the noise, the baby slept well.", answers: ["of"], explain: "**in spite of** — всегда с of; despite — без of." },
  { id: "link-026", topic: "linking-words", type: "fill", q: "I got up early so ___ I could catch the first train.", answers: ["that"], explain: "**so that** + предложение — цель." },
  { id: "link-027", topic: "linking-words", type: "fix", q: "Because of it was late, we took a taxi.", answers: ["Because it was late, we took a taxi."], explain: "Перед предложением (it was late) — because, без of." },
  { id: "link-028", topic: "linking-words", type: "fix", q: "In spite the rain, we played football.", answers: ["In spite of the rain, we played football.", "Despite the rain, we played football."], explain: "in spite **of**; либо despite без of." },
  { id: "link-029", topic: "linking-words", type: "fix", q: "Although it was expensive, but I bought it.", answers: ["Although it was expensive, I bought it.", "It was expensive, but I bought it."], explain: "although и but вместе не ставят — нужен только один из них." },
  { id: "link-030", topic: "linking-words", type: "fix", q: "I went to the bank for to get some money.", answers: ["I went to the bank to get some money.", "I went to the bank in order to get some money."], explain: "Цель — to + глагол, без for." },
  { id: "link-031", topic: "linking-words", type: "translate", q: "Несмотря на дождь, мы пошли гулять.", answers: ["Despite the rain, we went for a walk.", "In spite of the rain, we went for a walk.", "We went for a walk despite the rain.", "We went for a walk in spite of the rain.", "Despite the rain, we went out for a walk.", "In spite of the rain, we went out for a walk."], explain: "«Несмотря на» + существительное — despite / in spite of." },
  { id: "link-032", topic: "linking-words", type: "translate", q: "Я опоздал, потому что пропустил автобус.", answers: ["I was late because I missed the bus.", "I was late because I had missed the bus.", "I was late because I missed my bus."], explain: "because + предложение; «опоздал» = was late." },

  // ---------- vocab-feelings-character (дополнение) ----------
  { id: "v-feel-007", topic: "vocab-feelings-character", type: "choice", q: "He always tells the truth. He's very ___.", options: ["honest", "shy", "lazy"], answer: "honest", explain: "honest — честный." },
  { id: "v-feel-008", topic: "vocab-feelings-character", type: "choice", q: "She never changes her mind, even when she is wrong. She's so ___.", options: ["stubborn", "generous", "calm"], answer: "stubborn", explain: "stubborn — упрямый." },
  { id: "v-feel-009", topic: "vocab-feelings-character", type: "choice", q: "You can always count on Tom. He's very ___.", options: ["reliable", "selfish", "moody"], answer: "reliable", explain: "reliable — надёжный: на него можно положиться (count on)." },
  { id: "v-feel-010", topic: "vocab-feelings-character", type: "choice", q: "I was ___ when I didn't get the job.", options: ["disappointed", "disappointing", "delighted"], answer: "disappointed", explain: "Что чувствую я — **-ed**: disappointed. Disappointing — то, что разочаровывает." },
  { id: "v-feel-011", topic: "vocab-feelings-character", type: "choice", q: "Thank you so much! I'm really ___ for your help.", options: ["grateful", "jealous", "anxious"], answer: "grateful", explain: "grateful for — благодарный за." },
  { id: "v-feel-012", topic: "vocab-feelings-character", type: "choice", q: "He thinks only about himself. He's ___.", options: ["selfish", "sensitive", "sociable"], answer: "selfish", explain: "selfish — эгоистичный." },
  { id: "v-feel-013", topic: "vocab-feelings-character", type: "choice", q: "She's ___ of her sister's success and can't be happy for her.", options: ["jealous", "proud", "fond"], answer: "jealous", explain: "jealous of — завидует, ревнует. Proud of — гордится (тогда она была бы рада)." },
  { id: "v-feel-014", topic: "vocab-feelings-character", type: "fill", q: "I'm fed up ___ this weather.", answers: ["with"], explain: "fed up **with** — сыт по горло чем-то." },
  { id: "v-feel-015", topic: "vocab-feelings-character", type: "fill", q: "She is very good ___ listening to people.", answers: ["at"], explain: "good **at** + -ing." },
  { id: "v-feel-016", topic: "vocab-feelings-character", type: "fill", q: "I'm tired ___ waiting. Let's go.", answers: ["of"], explain: "tired **of** + -ing — надоело." },
  { id: "v-feel-017", topic: "vocab-feelings-character", type: "fill", q: "Don't be so shy! You should be more ___.", hint: "уверенный в себе: c…", answers: ["confident"], explain: "confident — уверенный в себе." },
  { id: "v-feel-018", topic: "vocab-feelings-character", type: "fix", q: "I'm very exciting about the trip.", answers: ["I'm very excited about the trip."], explain: "Человек чувствует — **-ed**: excited. Exciting — сама поездка." },
  { id: "v-feel-019", topic: "vocab-feelings-character", type: "fix", q: "She is afraid from spiders.", answers: ["She is afraid of spiders."], explain: "afraid **of**." },
  { id: "v-feel-020", topic: "vocab-feelings-character", type: "fix", q: "I'm worried for my exam.", answers: ["I'm worried about my exam."], explain: "worried **about**." },
  { id: "v-feel-021", topic: "vocab-feelings-character", type: "fix", q: "He is a very sensible person — he cries at sad films.", answers: ["He is a very sensitive person — he cries at sad films."], explain: "**sensitive** — чувствительный; **sensible** — благоразумный (ложный друг переводчика)." },
  { id: "v-feel-022", topic: "vocab-feelings-character", type: "translate", q: "Он очень упрямый.", answers: ["He is very stubborn."], explain: "stubborn — упрямый." },
  { id: "v-feel-023", topic: "vocab-feelings-character", type: "translate", q: "Я горжусь своей сестрой.", answers: ["I am proud of my sister."], explain: "be proud **of** — гордиться кем-то." },
  { id: "v-feel-024", topic: "vocab-feelings-character", type: "translate", q: "Мне надоела эта работа.", answers: ["I am tired of this job.", "I am tired of this work.", "I am fed up with this job.", "I am fed up with this work.", "I am sick of this job."], explain: "«Надоело» — be tired **of** / be fed up **with**." },

  // ---------- confusing-words (дополнение) ----------
  { id: "conf-008", topic: "confusing-words", type: "choice", q: "Can you ___ me some money until Friday?", options: ["lend", "borrow", "rent"], answer: "lend", explain: "**lend** — давать в долг (кому-то); **borrow** — брать в долг (у кого-то)." },
  { id: "conf-009", topic: "confusing-words", type: "choice", q: "She ___ she was tired.", options: ["said", "told", "spoke"], answer: "said", explain: "say + что; tell + кому (told me)." },
  { id: "conf-010", topic: "confusing-words", type: "choice", q: "Oh no! I ___ my wallet at home.", options: ["left", "forgot", "lost"], answer: "left", explain: "Если названо место (at home) — **leave**: I left my wallet at home. Forget — без места: I forgot my wallet." },
  { id: "conf-011", topic: "confusing-words", type: "choice", q: "We had a lot of ___ at the party.", options: ["fun", "funny", "joke"], answer: "fun", explain: "**fun** — веселье (have fun); **funny** — смешной." },
  { id: "conf-012", topic: "confusing-words", type: "choice", q: "I love ___. I've been to twenty countries.", options: ["travelling", "journey", "trip"], answer: "travelling", explain: "Путешествия вообще — travelling / travel. Journey и trip — одна конкретная поездка, с артиклем." },
  { id: "conf-013", topic: "confusing-words", type: "choice", q: "Could you ___ me the way to the station?", options: ["tell", "say", "speak"], answer: "tell", explain: "tell + кому: tell me the way." },
  { id: "conf-014", topic: "confusing-words", type: "choice", q: "Prices will ___ next year.", options: ["rise", "raise", "arise"], answer: "rise", explain: "**rise** — расти самому (prices rise); **raise** — поднимать что-то (raise prices, raise your hand)." },
  { id: "conf-015", topic: "confusing-words", type: "choice", q: "I'm ___ a film at the moment.", options: ["watching", "looking", "seeing"], answer: "watching", explain: "**watch** — смотреть то, что движется (фильм, матч); **look at** — посмотреть на; **see** — видеть." },
  { id: "conf-016", topic: "confusing-words", type: "choice", q: "Do you drink coffee? — ___, I don't like it. I prefer tea.", options: ["Actually", "Currently", "Nowadays"], answer: "Actually", explain: "**actually** = «на самом деле», а не «актуально». «В настоящее время» — currently / nowadays." },
  { id: "conf-017", topic: "confusing-words", type: "fill", q: "It's going to rain. ___ an umbrella with you when you go out.", hint: "t…", answers: ["Take"], explain: "**take** — взять с собой ОТСЮДА туда; **bring** — принести СЮДА." },
  { id: "conf-018", topic: "confusing-words", type: "fill", q: "Please ___ me to call the dentist tomorrow.", hint: "r…", answers: ["remind"], explain: "**remind** — напомнить кому-то; **remember** — помнить самому." },
  { id: "conf-019", topic: "confusing-words", type: "fill", q: "How much does this jacket ___?", hint: "cost или price", answers: ["cost"], explain: "**cost** — глагол «стоить»; **price** — существительное «цена»." },
  { id: "conf-020", topic: "confusing-words", type: "fill", q: "What is the ___ of this jacket?", hint: "cost или price", answers: ["price"], explain: "После the нужно существительное «цена» — price." },
  { id: "conf-021", topic: "confusing-words", type: "fix", q: "Can you borrow me your pen?", answers: ["Can you lend me your pen?"], explain: "Дать на время — lend. Borrow — взять: Can I borrow your pen?" },
  { id: "conf-022", topic: "confusing-words", type: "fix", q: "He said me the truth.", answers: ["He told me the truth."], explain: "tell + кому + что: told me the truth." },
  { id: "conf-023", topic: "confusing-words", type: "fix", q: "I forgot my keys at home.", answers: ["I left my keys at home."], explain: "С местом (at home) — left, а не forgot." },
  { id: "conf-024", topic: "confusing-words", type: "fix", q: "I am looking TV now.", answers: ["I am watching TV now."], explain: "Телевизор и фильмы — watch." },
  { id: "conf-025", topic: "confusing-words", type: "fix", q: "Please say me your name.", answers: ["Please tell me your name."], explain: "«Скажи мне» — tell me. После say нельзя сразу ставить me." },
  { id: "conf-026", topic: "confusing-words", type: "translate", q: "Она сказала, что занята.", answers: ["She said that she was busy.", "She said she was busy."], explain: "Нет «кому» — said. Время сдвигается: was busy." },
  { id: "conf-027", topic: "confusing-words", type: "translate", q: "Я оставил телефон дома.", answers: ["I left my phone at home.", "I have left my phone at home.", "I left the phone at home.", "I left my mobile at home."], explain: "«Оставил / забыл дома» — left … at home." }
);
